// Package config loads and validates the mrmr YAML config. Validation happens
// before anything is activated: an invalid config must fail startup loudly
// rather than produce a runtime that silently misbehaves (a policy with no
// then, a model that doesn't exist). Config is the only place mrmr's behavior
// is described, so it is also the first place to look when behavior surprises.
package config

import (
	"bytes"
	"fmt"
	"math"
	"os"
	"regexp"
	"strings"
	"time"

	"gopkg.in/yaml.v3"

	"github.com/heath0xff/mrmr/internal/filter"
	"github.com/heath0xff/mrmr/internal/model"
	"github.com/heath0xff/mrmr/internal/policy"
)

type Server struct {
	Addr string `yaml:"addr"`
}

type DB struct {
	Path string `yaml:"path"`
}

type Interpret struct {
	Model     string          `yaml:"model"`
	Prompt    string          `yaml:"prompt"`
	Schema    model.Schema    `yaml:"schema"`
	Questions model.Questions `yaml:"questions"`
}

// Source configures a built-in pull adapter. Common fields name its events
// and schedule; adapter-specific fields are rejected on the wrong type so
// a misplaced option cannot silently broaden ingestion. Secrets are env
// references, never values stored in this configuration.
type Source struct {
	Name           string        `yaml:"name"`
	Type           string        `yaml:"type"`
	URL            string        `yaml:"url"`              // may reference {{ .cursor }}
	Every          time.Duration `yaml:"every"`            // min 1s: protects the polled target
	BearerTokenEnv string        `yaml:"bearer_token_env"` // optional
	ItemPath       string        `yaml:"item_path"`        // optional dot-path to the record array
	CursorField    string        `yaml:"cursor_field"`     // optional; dedup id + watermark
	SubjectField   string        `yaml:"subject_field"`    // optional
	TimestampField string        `yaml:"timestamp_field"`  // optional; RFC3339
	EventType      string        `yaml:"event_type"`
	Units          []string      `yaml:"units"`    // systemd-journal: exact system unit names
	Priority       string        `yaml:"priority"` // systemd-journal: this severity or higher
}

// Exact names only: no patterns, journalctl options, paths, or user-unit
// selectors. This intentionally accepts a conservative subset of systemd
// names; escaped unit names can be added when a real source needs them.
var journalUnitName = regexp.MustCompile(`^[A-Za-z0-9_][A-Za-z0-9_.@:-]*\.(service|socket|timer|target|mount|automount|path|slice|scope|swap|device)$`)

// JournalPriority follows syslog numbering: smaller means more severe.
// Configuration and the source use the same mapping to avoid a filter that
// silently interprets "warning" differently at the two boundaries.
func JournalPriority(name string) (int, bool) {
	for i, p := range []string{"emerg", "alert", "crit", "err", "warning", "notice", "info", "debug"} {
		if p == name {
			return i, true
		}
	}
	return 0, false
}

// Agent is a delegation target. v0.1 ships only the generic HTTP adapter,
// so there is no type field yet: every agent is an HTTP endpoint that
// receives {event_id, decision, prompt} and returns 2xx.
type Agent struct {
	Endpoint string `yaml:"endpoint"`
}

type Config struct {
	Server Server `yaml:"server"`
	DB     DB     `yaml:"db"`
	// Filter is the pre-model gate (IMPLEMENTATION.md section 3):
	// deterministic checks that run before any model call. An event
	// that fails any Spec is recorded and ignored before
	// interpretation.
	Filter    filter.List             `yaml:"filter"`
	Models    map[string]model.Config `yaml:"models"`
	Interpret Interpret               `yaml:"interpret"`
	// Policy is inlined so the YAML reads exactly like IMPLEMENTATION.md:
	// a top-level `policy:` list plus a sibling `default:`.
	Policy policy.Policy `yaml:"policy,inline"`
	// Agents are delegation targets referenced by name from policy rules.
	// Endpoints live here, not in policy, so policies stay readable and
	// agent locations change without touching rule logic.
	Agents map[string]Agent `yaml:"agents"`
	// Sources are pull-based ingesters; each runs its own goroutine and
	// feeds the same pipeline as POST /api/events.
	Sources []Source `yaml:"sources"`
}

// Load reads, parses, and validates the config at path. Defaults (addr,
// db path) are applied for the values a minimal local setup never needs to
// set; anything the runtime cannot run correctly without stays required.
// Decoding is strict — unknown keys are errors, not warnings — because a
// typo like `api_keyenv:` silently disabling auth is far worse than a
// refused startup.
func Load(path string) (*Config, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read config %s: %w", path, err)
	}
	var c Config
	d := yaml.NewDecoder(bytes.NewReader(b))
	d.KnownFields(true)
	if err := d.Decode(&c); err != nil {
		return nil, fmt.Errorf("parse config %s: %w", path, err)
	}
	if c.Server.Addr == "" {
		c.Server.Addr = ":4242"
	}
	if c.DB.Path == "" {
		c.DB.Path = "mrmr.db"
	}
	if err := c.Validate(); err != nil {
		return nil, err
	}
	return &c, nil
}

func (c *Config) Validate() error {
	if c.Interpret.Model == "" {
		return fmt.Errorf("config: interpret.model is required")
	}
	mc, ok := c.Models[c.Interpret.Model]
	if !ok {
		return fmt.Errorf("config: interpret.model %q not defined in models", c.Interpret.Model)
	}
	if mc.BaseURL == "" {
		return fmt.Errorf("config: model %q: base_url is required", c.Interpret.Model)
	}
	switch mc.Provider {
	case "openai-compatible":
		if c.Interpret.Prompt == "" {
			return fmt.Errorf("config: interpret.prompt is required for openai-compatible models")
		}
		if len(c.Interpret.Schema) == 0 {
			return fmt.Errorf("config: interpret.schema is required for openai-compatible models")
		}
		if len(c.Interpret.Questions) != 0 {
			return fmt.Errorf("config: interpret.questions requires a typesafe model")
		}
		for name, f := range c.Interpret.Schema {
			switch f.Type {
			case "string", "number", "boolean":
			default:
				return fmt.Errorf("config: schema field %q: unsupported type %q", name, f.Type)
			}
			if f.Type != "number" && (f.Minimum != nil || f.Maximum != nil) {
				return fmt.Errorf("config: schema field %q: minimum/maximum require type number", name)
			}
			if (f.Minimum != nil && (math.IsNaN(*f.Minimum) || math.IsInf(*f.Minimum, 0))) ||
				(f.Maximum != nil && (math.IsNaN(*f.Maximum) || math.IsInf(*f.Maximum, 0))) {
				return fmt.Errorf("config: schema field %q: minimum/maximum must be finite", name)
			}
			if f.Minimum != nil && f.Maximum != nil && *f.Minimum > *f.Maximum {
				return fmt.Errorf("config: schema field %q: minimum must not exceed maximum", name)
			}
		}
	case "typesafe":
		if mc.APIKeyEnv == "" {
			return fmt.Errorf("config: model %q: api_key_env is required for typesafe", c.Interpret.Model)
		}
		if c.Interpret.Prompt != "" || len(c.Interpret.Schema) != 0 {
			return fmt.Errorf("config: interpret.prompt/schema are not supported for typesafe; use questions")
		}
		if err := model.ValidateQuestions(c.Interpret.Questions); err != nil {
			return fmt.Errorf("config: interpret.questions: %w", err)
		}
	default:
		return fmt.Errorf("config: model %q: unsupported provider %q (openai-compatible, typesafe)", c.Interpret.Model, mc.Provider)
	}
	for i, f := range c.Filter {
		if err := f.Validate(); err != nil {
			return fmt.Errorf("config: filter %d: %w", i+1, err)
		}
	}

	validateThen := func(t policy.Then, where string) error {
		// A rule that sets several outcomes is almost certainly a YAML typo
		// (a leftover ignore under a new notify). Rather than picking a
		// winner, reject it: ambiguity in outcome selection is exactly the
		// kind of thing policy must never have.
		set := 0
		for _, b := range []bool{t.Notify != nil, t.Action != nil, t.Delegate != nil, t.Ignore} {
			if b {
				set++
			}
		}
		if set > 1 {
			return fmt.Errorf("config: %s: set at most one of notify, action, delegate, ignore", where)
		}
		if t.Notify != nil && t.Notify.Via != "stdout" {
			return fmt.Errorf("config: %s: notify.via %q not supported (v0.1: stdout)", where, t.Notify.Via)
		}
		if t.Action != nil {
			switch t.Action.Type {
			case "http":
				if t.Action.URL == "" {
					return fmt.Errorf("config: %s: action.url is required for type http", where)
				}
			case "emit":
				if t.Action.EventType == "" {
					return fmt.Errorf("config: %s: action.event_type is required for type emit", where)
				}
			default:
				return fmt.Errorf("config: %s: action.type %q not supported (v0.1: http, emit)", where, t.Action.Type)
			}
		}
		if t.Delegate != nil {
			if t.Delegate.Agent == "" {
				return fmt.Errorf("config: %s: delegate.agent is required", where)
			}
			// The reference is resolved now, at validation time, so a typo'd
			// agent name fails startup instead of surfacing as a mid-flight
			// "unknown agent" execution error on some future event.
			if _, ok := c.Agents[t.Delegate.Agent]; !ok {
				return fmt.Errorf("config: %s: delegate.agent %q not defined in agents", where, t.Delegate.Agent)
			}
		}
		if set == 0 && !t.Shadow {
			return fmt.Errorf("config: %s: must set notify, action, delegate, ignore: true, or shadow: true", where)
		}
		return nil
	}
	for name, a := range c.Agents {
		if a.Endpoint == "" {
			return fmt.Errorf("config: agent %q: endpoint is required", name)
		}
	}
	seenSources := map[string]bool{}
	for i := range c.Sources {
		s := &c.Sources[i]
		if s.Name == "" {
			return fmt.Errorf("config: source %d: name is required", i+1)
		}
		// Source names become Event.Source and cursor keys: uniqueness is
		// what keeps two pollers from silently sharing dedup identity.
		if seenSources[s.Name] {
			return fmt.Errorf("config: source %q: duplicate name", s.Name)
		}
		seenSources[s.Name] = true
		switch s.Type {
		case "http-poller":
			if s.URL == "" {
				return fmt.Errorf("config: source %q: url is required", s.Name)
			}
			if len(s.Units) != 0 || s.Priority != "" {
				return fmt.Errorf("config: source %q: units and priority require systemd-journal", s.Name)
			}
		case "systemd-journal":
			if s.URL != "" || s.BearerTokenEnv != "" || s.ItemPath != "" || s.CursorField != "" || s.SubjectField != "" || s.TimestampField != "" {
				return fmt.Errorf("config: source %q: HTTP fields are not supported for systemd-journal", s.Name)
			}
			if len(s.Units) == 0 || len(s.Units) > 32 {
				return fmt.Errorf("config: source %q: units must contain 1 to 32 exact system unit names", s.Name)
			}
			seen := map[string]bool{}
			for _, unit := range s.Units {
				if len(unit) > 255 || !journalUnitName.MatchString(unit) || strings.Contains(unit, "..") || seen[unit] {
					return fmt.Errorf("config: source %q: invalid or duplicate system unit name", s.Name)
				}
				seen[unit] = true
			}
			if _, ok := JournalPriority(s.Priority); !ok {
				return fmt.Errorf("config: source %q: priority must be emerg, alert, crit, err, warning, notice, info, or debug", s.Name)
			}
		default:
			return fmt.Errorf("config: source %q: type %q not supported (http-poller, systemd-journal)", s.Name, s.Type)
		}
		// The floor protects the polled target from a typo like `every: 1ms`
		// turning into a self-inflicted denial of service.
		if s.Every < time.Second {
			return fmt.Errorf("config: source %q: every must be at least 1s", s.Name)
		}
		if s.EventType == "" {
			return fmt.Errorf("config: source %q: event_type is required", s.Name)
		}
	}
	for i, r := range c.Policy.Rules {
		if len(r.If) == 0 {
			return fmt.Errorf("config: policy rule %d: empty if", i+1)
		}
		if err := validateThen(r.Then, fmt.Sprintf("policy rule %d", i+1)); err != nil {
			return err
		}
	}
	return validateThen(c.Policy.Default, "default")
}

// Package model talks to configured interpretation endpoints and returns
// validated structured results. Everything here treats model responses as
// untrusted: provider-specific clients validate the complete response before
// the runtime can persist it or pass it to policy. The caller decides what a
// bad result means — this package only reports it.
package model

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
	"time"
)

// Config describes one model endpoint. Secrets are referenced by env var
// name only (api_key_env) — never inlined — so config files stay safe to
// commit and inspect.
type Config struct {
	Provider  string `yaml:"provider"` // openai-compatible | typesafe
	BaseURL   string `yaml:"base_url"`
	APIKeyEnv string `yaml:"api_key_env"`
	Model     string `yaml:"model"`
}

// Field is the v0 schema subset: flat typed fields with optional enums and numeric bounds.
type Field struct {
	Type    string   `yaml:"type"` // string | number | boolean
	Enum    []any    `yaml:"enum"`
	Minimum *float64 `yaml:"minimum"`
	Maximum *float64 `yaml:"maximum"`
}

type Schema map[string]Field

type Client struct{}

const (
	maxAttempts    = 3 // total HTTP calls per interpretation, all failure modes combined
	requestTimeout = 60 * time.Second
	retryBackoff   = 250 * time.Millisecond // only between transport attempts; a briefly overloaded local model needs a moment
)

type InvalidOutputError struct{ Detail string }

func (e *InvalidOutputError) Error() string { return "invalid model output: " + e.Detail }

// Interpret preserves the original OpenAI-compatible call surface for small
// callers and tests. Runtime code uses InterpretWithQuestions so a TypeSafe
// interpretation can carry its configured primitives.
func (c *Client) Interpret(ctx context.Context, cfg Config, interpreter string, prompt string, schema Schema, eventJSON []byte) (result map[string]any, latencyMs int64, model string, err error) {
	return c.InterpretWithQuestions(ctx, cfg, interpreter, prompt, schema, nil, eventJSON)
}

// InterpretWithQuestions dispatches one event to the selected provider.
// Keeping this concrete avoids a provider framework: there are exactly two
// real protocols, and each validates its response before returning a Decision.
func (c *Client) InterpretWithQuestions(ctx context.Context, cfg Config, interpreter string, prompt string, schema Schema, questions Questions, eventJSON []byte) (result map[string]any, latencyMs int64, model string, err error) {
	switch cfg.Provider {
	case "openai-compatible":
		return c.interpretOpenAI(ctx, cfg, interpreter, prompt, schema, eventJSON)
	case "typesafe":
		return c.interpretTypeSafe(ctx, cfg, questions, eventJSON)
	default:
		return nil, 0, cfg.Model, fmt.Errorf("unsupported model provider %q", cfg.Provider)
	}
}

// interpretOpenAI sends the event to an OpenAI-compatible model. Error is
// *InvalidOutputError when output fails schema validation after one correction;
// other errors are endpoint failures. All retries share maxAttempts, and
// latency sums model calls but not backoff sleeps.
func (c *Client) interpretOpenAI(ctx context.Context, cfg Config, interpreter string, prompt string, schema Schema, eventJSON []byte) (result map[string]any, latencyMs int64, model string, err error) {
	model = cfg.Model
	sys := prompt + "\n\nRespond with a single JSON object with exactly these fields:\n" + schemaJSON(schema)
	req := chatRequest{
		Model:          cfg.Model,
		Messages:       []message{{"system", sys}, {"user", string(eventJSON)}},
		Temperature:    0,
		ResponseFormat: &responseFormat{Type: "json_schema", JSONSchema: &jsonSchemaFmt{Name: "decision", Strict: true, Schema: schemaMap(schema)}},
	}
	hc := &http.Client{Timeout: requestTimeout}

	var (
		transportErr  error
		invalidDetail string
		usedRetry     bool // one self-correction attempt, ever
	)
	// Every post consumes the same budget, including response_format fallback.
	// Once an endpoint rejects the format, keep it disabled for correction
	// and transport retries within this interpretation, not across clients.
	for calls := 0; calls < maxAttempts; calls++ {
		if calls > 0 {
			select {
			case <-ctx.Done():
				return nil, latencyMs, model, ctx.Err()
			case <-time.After(retryBackoff):
			}
		}
		start := time.Now()
		content, err := c.post(ctx, hc, cfg, req)
		latencyMs += time.Since(start).Milliseconds()
		if err != nil {
			transportErr = fmt.Errorf("model call (attempt %d): %w", calls+1, err)
			var se *statusError
			if errors.As(err, &se) && se.Code < 500 {
				if se.Code == http.StatusBadRequest && req.ResponseFormat != nil {
					req.ResponseFormat = nil
					continue
				}
				// Other 4xx failures, including a second 400 without the
				// format, cannot be repaired by another identical request.
				return nil, latencyMs, model, transportErr
			}
			continue // network error or 5xx: retry within the remaining budget
		}
		transportErr = nil
		res, verr := parseAndValidate(content, schema)
		if verr == nil {
			return res, latencyMs, model, nil
		}
		invalidDetail = verr.Error()
		if usedRetry {
			return nil, latencyMs, model, &InvalidOutputError{Detail: invalidDetail}
		}
		// One self-correction hop: show the model its failed output and the
		// validation error so small local models can fix themselves. This
		// path is expected to be routine and must stay bounded.
		usedRetry = true
		req.Messages = append(req.Messages,
			message{"assistant", content},
			message{"user", "Your previous output failed validation: " + verr.Error() + "\nRespond again with a JSON object matching the schema exactly."},
		)
	}
	if transportErr != nil {
		return nil, latencyMs, model, transportErr
	}
	return nil, latencyMs, model, &InvalidOutputError{Detail: invalidDetail}
}

type message struct {
	Role    string `json:"role"`
	Content string `json:"content"`
}

type responseFormat struct {
	Type       string         `json:"type"`
	JSONSchema *jsonSchemaFmt `json:"json_schema,omitempty"`
}

type jsonSchemaFmt struct {
	Name   string         `json:"name"`
	Strict bool           `json:"strict"`
	Schema map[string]any `json:"schema"`
}

type chatRequest struct {
	Model          string          `json:"model"`
	Messages       []message       `json:"messages"`
	Temperature    float64         `json:"temperature"`
	ResponseFormat *responseFormat `json:"response_format,omitempty"`
}

type chatResponse struct {
	Choices []struct {
		Message struct {
			Content string `json:"content"`
		} `json:"message"`
	} `json:"choices"`
}

// statusError distinguishes endpoint HTTP failures from transport failures.
// The distinction is load-bearing: a 400 to a schema-constrained request
// means the endpoint doesn't support response_format and is worth retrying
// without it, while a 500 is an outage that only counts against the retry
// budget.
type statusError struct {
	Code int
}

func (e *statusError) Error() string {
	return fmt.Sprintf("endpoint returned %d", e.Code)
}

func (c *Client) post(ctx context.Context, hc *http.Client, cfg Config, req chatRequest) (string, error) {
	body, _ := json.Marshal(req)
	httpReq, err := http.NewRequestWithContext(ctx, http.MethodPost, strings.TrimRight(cfg.BaseURL, "/")+"/chat/completions", bytes.NewReader(body))
	if err != nil {
		return "", err
	}
	httpReq.Header.Set("Content-Type", "application/json")
	if cfg.APIKeyEnv != "" {
		if key := os.Getenv(cfg.APIKeyEnv); key != "" {
			httpReq.Header.Set("Authorization", "Bearer "+key)
		}
	}
	resp, err := hc.Do(httpReq)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		// Error pages can echo authorization headers or private prompts.
		// Keep only the status: these errors reach SQLite, logs, and callers.
		// A bounded drain permits connection reuse without retaining content.
		io.Copy(io.Discard, io.LimitReader(resp.Body, 2048))
		return "", &statusError{Code: resp.StatusCode}
	}
	var cr chatResponse
	if err := json.NewDecoder(resp.Body).Decode(&cr); err != nil {
		return "", fmt.Errorf("decode response: %w", err)
	}
	if len(cr.Choices) == 0 {
		return "", fmt.Errorf("empty choices in response")
	}
	return cr.Choices[0].Message.Content, nil
}

// schemaJSON renders the schema as the instruction block for the prompt.
func schemaJSON(s Schema) string {
	b, _ := json.MarshalIndent(schemaMap(s), "", "  ")
	return string(b)
}

// schemaMap converts the flat Schema into a JSON-Schema object map for
// constrained decoding (llama.cpp grammars / vLLM guided JSON / etc.).
func schemaMap(s Schema) map[string]any {
	props := map[string]any{}
	required := []string{}
	for name, f := range s {
		p := map[string]any{"type": f.Type}
		if len(f.Enum) > 0 {
			p["enum"] = f.Enum
		}
		if f.Minimum != nil {
			p["minimum"] = *f.Minimum
		}
		if f.Maximum != nil {
			p["maximum"] = *f.Maximum
		}
		props[name] = p
		required = append(required, name)
	}
	return map[string]any{
		"type":                 "object",
		"properties":           props,
		"required":             required,
		"additionalProperties": false,
	}
}

// parseAndValidate extracts a JSON object from model output. Small local
// models routinely wrap JSON in markdown fences or lead with prose even when
// told not to, so we scan for the outermost braces instead of trusting the
// whole string to be JSON. If the braces contain garbage, Unmarshal catches it.
func parseAndValidate(content string, schema Schema) (map[string]any, error) {
	// Tolerate models that wrap JSON in fences or prose.
	start := strings.Index(content, "{")
	end := strings.LastIndex(content, "}")
	if start < 0 || end <= start {
		return nil, fmt.Errorf("no JSON object found in output")
	}
	var res map[string]any
	if err := json.Unmarshal([]byte(content[start:end+1]), &res); err != nil {
		return nil, fmt.Errorf("unparseable JSON: %v", err)
	}
	return res, validate(res, schema)
}

// validate checks a parsed result against the flat schema. It enforces
// exact shape — every field present, correct type, enum membership, no
// extras — because downstream policy conditions are silent when a field is
// missing, and a silently-missing field is indistinguishable from a
// deliberate route to the default outcome.
func validate(res map[string]any, schema Schema) error {
	for name, f := range schema {
		v, ok := res[name]
		if !ok {
			return fmt.Errorf("missing field %q", name)
		}
		switch f.Type {
		case "string":
			if _, ok := v.(string); !ok {
				return fmt.Errorf("field %q: want string", name)
			}
		case "number":
			n, ok := v.(float64)
			if !ok {
				return fmt.Errorf("field %q: want number", name)
			}
			if f.Minimum != nil && n < *f.Minimum {
				return fmt.Errorf("field %q: value %v below minimum %v", name, n, *f.Minimum)
			}
			if f.Maximum != nil && n > *f.Maximum {
				return fmt.Errorf("field %q: value %v above maximum %v", name, n, *f.Maximum)
			}
		case "boolean":
			if _, ok := v.(bool); !ok {
				return fmt.Errorf("field %q: want boolean", name)
			}
		default:
			return fmt.Errorf("schema field %q: unsupported type %q", name, f.Type)
		}
		if len(f.Enum) > 0 {
			found := false
			for _, e := range f.Enum {
				if fmt.Sprint(e) == fmt.Sprint(v) {
					found = true
					break
				}
			}
			if !found {
				return fmt.Errorf("field %q: value %v not in enum", name, v)
			}
		}
	}
	for name := range res {
		if _, ok := schema[name]; !ok {
			return fmt.Errorf("unexpected field %q", name)
		}
	}
	return nil
}

package model

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math"
	"net/http"
	"os"
	"strconv"
	"strings"
	"time"
)

// Questions is the configured set of independent System One judgments. The
// criteria shape follows TypeSafe's API: a map for Choice/Noul and a list for
// Score. It remains any at the YAML boundary because those wire shapes differ;
// ValidateQuestions normalizes and rejects every other shape before startup.
type Questions map[string]Question

type Question struct {
	Type         string `yaml:"type"`
	Instructions string `yaml:"instructions"`
	Criteria     any    `yaml:"criteria"`
}

// ValidateQuestions validates the public YAML contract and, importantly,
// reserves dots for policy traversal. A question or option containing a dot
// would make result.category.choice ambiguous at policy time.
func ValidateQuestions(questions Questions) error {
	if len(questions) == 0 {
		return fmt.Errorf("questions are required")
	}
	for id, q := range questions {
		if !safeQuestionID(id) {
			return fmt.Errorf("question %q: id must contain only letters, numbers, underscore, or hyphen", id)
		}
		if _, err := normalizeQuestion(q); err != nil {
			return fmt.Errorf("question %q: %w", id, err)
		}
	}
	return nil
}

func safeQuestionID(s string) bool {
	if s == "" {
		return false
	}
	for _, r := range s {
		if (r < 'a' || r > 'z') && (r < 'A' || r > 'Z') && (r < '0' || r > '9') && r != '_' && r != '-' {
			return false
		}
	}
	return true
}

type systemOneQuestion struct {
	Type         string `json:"type"`
	Instructions string `json:"instructions"`
	Criteria     any    `json:"criteria,omitempty"`
}

func normalizeQuestion(q Question) (systemOneQuestion, error) {
	if strings.TrimSpace(q.Instructions) == "" {
		return systemOneQuestion{}, fmt.Errorf("instructions are required")
	}
	out := systemOneQuestion{Type: q.Type, Instructions: q.Instructions}
	switch q.Type {
	case "choice":
		criteria, err := stringMap(q.Criteria)
		if err != nil || len(criteria) < 2 || len(criteria) > 255 {
			return out, fmt.Errorf("choice criteria must be a map of 2 to 255 string options")
		}
		for option, description := range criteria {
			if !safeQuestionID(option) || strings.TrimSpace(description) == "" {
				return out, fmt.Errorf("choice options must have path-safe names and non-empty string descriptions")
			}
		}
		out.Criteria = criteria
	case "noul":
		if q.Criteria == nil {
			return out, nil
		}
		criteria, err := stringMap(q.Criteria)
		if err != nil || len(criteria) != 2 || strings.TrimSpace(criteria["true"]) == "" || strings.TrimSpace(criteria["false"]) == "" {
			return out, fmt.Errorf("noul criteria must contain non-empty true and false strings")
		}
		out.Criteria = criteria
	case "score":
		criteria, err := stringList(q.Criteria)
		if err != nil || len(criteria) < 2 || len(criteria) > 10 {
			return out, fmt.Errorf("score criteria must be a list of 2 to 10 strings")
		}
		for _, level := range criteria {
			if strings.TrimSpace(level) == "" {
				return out, fmt.Errorf("score criteria must not contain empty levels")
			}
		}
		out.Criteria = criteria
	default:
		return out, fmt.Errorf("unsupported type %q (choice, noul, score)", q.Type)
	}
	return out, nil
}

func stringMap(v any) (map[string]string, error) {
	switch m := v.(type) {
	case map[string]string:
		return m, nil
	case map[string]any:
		out := make(map[string]string, len(m))
		for key, value := range m {
			s, ok := value.(string)
			if !ok {
				return nil, fmt.Errorf("%q is not a string", key)
			}
			out[key] = s
		}
		return out, nil
	case map[any]any:
		out := make(map[string]string, len(m))
		for key, value := range m {
			ks, ok := key.(string)
			if !ok {
				// YAML may decode unquoted true/false keys as booleans.
				if b, isBool := key.(bool); isBool {
					ks = strconv.FormatBool(b)
				} else {
					return nil, fmt.Errorf("criterion key is not a string")
				}
			}
			vs, ok := value.(string)
			if !ok {
				return nil, fmt.Errorf("%q is not a string", ks)
			}
			out[ks] = vs
		}
		return out, nil
	default:
		return nil, fmt.Errorf("criteria is not a map")
	}
}

func stringList(v any) ([]string, error) {
	switch list := v.(type) {
	case []string:
		return list, nil
	case []any:
		out := make([]string, len(list))
		for i, value := range list {
			s, ok := value.(string)
			if !ok {
				return nil, fmt.Errorf("level %d is not a string", i)
			}
			out[i] = s
		}
		return out, nil
	default:
		return nil, fmt.Errorf("criteria is not a list")
	}
}

type systemOneRequest struct {
	State     json.RawMessage              `json:"state"`
	Model     string                       `json:"model"`
	Questions map[string]systemOneQuestion `json:"questions"`
}

type systemOneResponse struct {
	Model   string                     `json:"model"`
	Answers map[string]json.RawMessage `json:"answers"`
	Usage   struct {
		InputTokens  int `json:"input_tokens"`
		OutputTokens int `json:"output_tokens"`
	} `json:"usage"`
}

type typeSafeStatusError struct {
	Code       int
	RetryAfter time.Duration
}

func (e *typeSafeStatusError) Error() string { return fmt.Sprintf("endpoint returned %d", e.Code) }

// interpretTypeSafe sends every configured question in one request. The API
// evaluates them independently, so splitting calls would only resend private
// event state and add cost. Unlike a generative model there is no correction
// prompt: a malformed 200 response is invalid, while transport/429/5xx errors
// consume the same bounded three-attempt budget used by the other provider.
func (c *Client) interpretTypeSafe(ctx context.Context, cfg Config, questions Questions, eventJSON []byte) (map[string]any, int64, string, error) {
	if err := ValidateQuestions(questions); err != nil {
		return nil, 0, cfg.Model, &InvalidOutputError{Detail: err.Error()}
	}
	normalized := make(map[string]systemOneQuestion, len(questions))
	for id, question := range questions {
		normalized[id], _ = normalizeQuestion(question)
	}
	req := systemOneRequest{State: json.RawMessage(eventJSON), Model: cfg.Model, Questions: normalized}
	hc := &http.Client{Timeout: requestTimeout}

	var latencyMs int64
	delay := retryBackoff
	for attempt := 0; attempt < maxAttempts; attempt++ {
		if attempt > 0 {
			select {
			case <-ctx.Done():
				return nil, latencyMs, cfg.Model, ctx.Err()
			case <-time.After(delay):
			}
			delay *= 2
		}
		started := time.Now()
		response, err := c.postSystemOne(ctx, hc, cfg, req)
		latencyMs += time.Since(started).Milliseconds()
		if err != nil {
			var status *typeSafeStatusError
			if errors.As(err, &status) && status.Code != http.StatusTooManyRequests && status.Code < 500 {
				return nil, latencyMs, cfg.Model, fmt.Errorf("model call (attempt %d): %w", attempt+1, err)
			}
			if status != nil && status.RetryAfter > delay {
				delay = status.RetryAfter
			}
			if delay > 5*time.Second {
				delay = 5 * time.Second
			}
			if attempt == maxAttempts-1 {
				return nil, latencyMs, cfg.Model, fmt.Errorf("model call (attempt %d): %w", attempt+1, err)
			}
			continue
		}
		result, modelID, err := validateSystemOneResponse(response, questions)
		if err != nil {
			return nil, latencyMs, cfg.Model, &InvalidOutputError{Detail: err.Error()}
		}
		return result, latencyMs, modelID, nil
	}
	panic("unreachable")
}

func (c *Client) postSystemOne(ctx context.Context, hc *http.Client, cfg Config, req systemOneRequest) ([]byte, error) {
	body, err := json.Marshal(req)
	if err != nil {
		return nil, fmt.Errorf("encode request: %w", err)
	}
	httpReq, err := http.NewRequestWithContext(ctx, http.MethodPost, strings.TrimRight(cfg.BaseURL, "/")+"/systemone", bytes.NewReader(body))
	if err != nil {
		return nil, err
	}
	httpReq.Header.Set("Content-Type", "application/json")
	if key := os.Getenv(cfg.APIKeyEnv); key != "" {
		httpReq.Header.Set("Authorization", "Bearer "+key)
	}
	resp, err := hc.Do(httpReq)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		io.Copy(io.Discard, io.LimitReader(resp.Body, 2048))
		return nil, &typeSafeStatusError{Code: resp.StatusCode, RetryAfter: parseRetryAfter(resp.Header.Get("Retry-After"))}
	}
	body, err = io.ReadAll(io.LimitReader(resp.Body, 4<<20))
	if err != nil {
		return nil, fmt.Errorf("read response: %w", err)
	}
	return body, nil
}

func parseRetryAfter(value string) time.Duration {
	if seconds, err := strconv.Atoi(strings.TrimSpace(value)); err == nil && seconds >= 0 {
		return time.Duration(seconds) * time.Second
	}
	if at, err := http.ParseTime(value); err == nil {
		if delay := time.Until(at); delay > 0 {
			return delay
		}
	}
	return 0
}

func validateSystemOneResponse(body []byte, questions Questions) (map[string]any, string, error) {
	var response systemOneResponse
	decoder := json.NewDecoder(bytes.NewReader(body))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&response); err != nil {
		return nil, "", fmt.Errorf("decode response: %w", err)
	}
	if err := decoder.Decode(new(any)); err != io.EOF {
		return nil, "", fmt.Errorf("decode response: expected one JSON object")
	}
	if response.Model == "" {
		return nil, "", fmt.Errorf("response model is required")
	}
	if len(response.Answers) != len(questions) {
		return nil, "", fmt.Errorf("answer count %d does not match question count %d", len(response.Answers), len(questions))
	}
	result := make(map[string]any, len(questions))
	for id, question := range questions {
		raw, ok := response.Answers[id]
		if !ok {
			return nil, "", fmt.Errorf("missing answer %q", id)
		}
		answer, err := validateSystemOneAnswer(raw, question)
		if err != nil {
			return nil, "", fmt.Errorf("answer %q: %w", id, err)
		}
		result[id] = answer
	}
	return result, response.Model, nil
}

func validateSystemOneAnswer(raw json.RawMessage, question Question) (map[string]any, error) {
	decode := func(dst any) error {
		decoder := json.NewDecoder(bytes.NewReader(raw))
		decoder.DisallowUnknownFields()
		if err := decoder.Decode(dst); err != nil {
			return err
		}
		if err := decoder.Decode(new(any)); err != io.EOF {
			return fmt.Errorf("expected one JSON object")
		}
		return nil
	}
	switch question.Type {
	case "noul":
		var answer struct {
			Type string   `json:"type"`
			Noul *float64 `json:"noul"`
		}
		if err := decode(&answer); err != nil {
			return nil, err
		}
		if answer.Type != "noul" || answer.Noul == nil || !unitProbability(*answer.Noul) {
			return nil, fmt.Errorf("invalid noul answer")
		}
		return map[string]any{"type": answer.Type, "noul": *answer.Noul}, nil
	case "choice":
		var answer struct {
			Type          string             `json:"type"`
			Choice        string             `json:"choice"`
			Probabilities map[string]float64 `json:"probabilities"`
			Confidence    *float64           `json:"confidence"`
		}
		if err := decode(&answer); err != nil {
			return nil, err
		}
		criteria, _ := stringMap(question.Criteria)
		if answer.Type != "choice" || answer.Confidence == nil || !unitProbability(*answer.Confidence) {
			return nil, fmt.Errorf("invalid choice answer")
		}
		if _, ok := criteria[answer.Choice]; !ok {
			return nil, fmt.Errorf("choice %q is not configured", answer.Choice)
		}
		if err := validateProbabilities(answer.Probabilities, mapKeys(criteria)); err != nil {
			return nil, err
		}
		for option, probability := range answer.Probabilities {
			if probability > answer.Probabilities[answer.Choice]+1e-9 {
				return nil, fmt.Errorf("choice %q is not the highest-probability option (got %q)", answer.Choice, option)
			}
		}
		return map[string]any{"type": answer.Type, "choice": answer.Choice, "probabilities": answer.Probabilities, "confidence": *answer.Confidence}, nil
	case "score":
		var answer struct {
			Type          string             `json:"type"`
			Score         *float64           `json:"score"`
			Legend        map[string]string  `json:"legend"`
			Probabilities map[string]float64 `json:"probabilities"`
			Confidence    *float64           `json:"confidence"`
		}
		if err := decode(&answer); err != nil {
			return nil, err
		}
		levels, _ := stringList(question.Criteria)
		if answer.Type != "score" || answer.Score == nil || answer.Confidence == nil || !unitProbability(*answer.Confidence) || math.IsNaN(*answer.Score) || math.IsInf(*answer.Score, 0) || *answer.Score < 0 || *answer.Score > float64(len(levels)-1) {
			return nil, fmt.Errorf("invalid score answer")
		}
		keys := make([]string, len(levels))
		for i, level := range levels {
			key := strconv.Itoa(i)
			keys[i] = key
			if answer.Legend[key] != level {
				return nil, fmt.Errorf("legend level %s does not match configured criteria", key)
			}
		}
		if len(answer.Legend) != len(levels) {
			return nil, fmt.Errorf("legend contains unexpected levels")
		}
		if err := validateProbabilities(answer.Probabilities, keys); err != nil {
			return nil, err
		}
		var expected float64
		for i := range levels {
			expected += float64(i) * answer.Probabilities[strconv.Itoa(i)]
		}
		if math.Abs(expected-*answer.Score) > 0.01 {
			return nil, fmt.Errorf("score %v does not match probability-weighted value %v", *answer.Score, expected)
		}
		return map[string]any{"type": answer.Type, "score": *answer.Score, "legend": answer.Legend, "probabilities": answer.Probabilities, "confidence": *answer.Confidence}, nil
	default:
		return nil, fmt.Errorf("unsupported question type %q", question.Type)
	}
}

func unitProbability(value float64) bool {
	return !math.IsNaN(value) && !math.IsInf(value, 0) && value >= 0 && value <= 1
}

func validateProbabilities(probabilities map[string]float64, keys []string) error {
	if len(probabilities) != len(keys) {
		return fmt.Errorf("probability keys do not match criteria")
	}
	var sum float64
	for _, key := range keys {
		value, ok := probabilities[key]
		if !ok || !unitProbability(value) {
			return fmt.Errorf("invalid probability for %q", key)
		}
		sum += value
	}
	if math.Abs(sum-1) > 0.01 {
		return fmt.Errorf("probabilities sum to %v, want 1", sum)
	}
	return nil
}

func mapKeys(m map[string]string) []string {
	keys := make([]string, 0, len(m))
	for key := range m {
		keys = append(keys, key)
	}
	return keys
}

// Package runtime is the mrmr loop: persist Event → filter → interpret →
// Decision → policy → Outcome → adapter, with a trace at every step. The
// filter stage is deterministic and may short-circuit: an excluded event
// produces no Decision and no model call.
// This package is the choreography; every stage's actual work lives in its
// own package.
// The one rule that shapes everything here: fail toward ignore. A model
// outage or a garbage result degrades mrmr into a no-op — the safe direction
// — and never into an action nobody authorized.
package runtime

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"strings"
	"text/template"
	"time"

	"github.com/heath0xff/mrmr/internal/event"
	"github.com/heath0xff/mrmr/internal/filter"
	"github.com/heath0xff/mrmr/internal/model"
	"github.com/heath0xff/mrmr/internal/policy"
	"github.com/heath0xff/mrmr/internal/storage"
)

// Runtime is the assembled pipeline. It is immutable after construction:
// the config that built it is the config it runs, which is what lets
// in-flight events finish under the rules they started with.
type Runtime struct {
	DB        *storage.DB
	Client    *model.Client
	ModelCfg  model.Config
	ModelKey  string // name in config, recorded on decisions
	Prompt    string
	Schema    model.Schema
	Questions model.Questions
	Policy    policy.Policy
	Filters   filter.List
	// AgentEndpoints maps a policy delegate.agent name to its HTTP endpoint.
	// Resolved at startup from config so policy rules never carry URLs.
	AgentEndpoints map[string]string
	// HTTP is the client for action/delegate side effects. Nil means a
	// default 10s timeout — outbound effects must be bounded, never hang
	// the synchronous ingest path.
	HTTP *http.Client
}

// maxDepth caps emit-event recursion: a causal chain longer than this is a
// loop, and loops get recorded and ignored, not executed.
const maxDepth = 10

// TraceStep is one observable moment in an event's journey. It is an alias,
// not a distinct type: the trace is persisted next to the event it explains,
// so the shape belongs to the domain package that storage also speaks, and
// the runtime is merely where the steps are produced.
type TraceStep = event.TraceStep

// Response is what the caller (HTTP handler) receives: the event id, the
// decision (if any), the outcome, and the full trace. It doubles as the
// stdout log line for milestone 1.
type Response struct {
	EventID   string          `json:"event_id"`
	Duplicate bool            `json:"duplicate,omitempty"`
	Decision  *event.Decision `json:"decision,omitempty"`
	Outcome   string          `json:"outcome,omitempty"`
	Trace     []TraceStep     `json:"trace"`
}

func step(t *[]TraceStep, stage, msg string) {
	*t = append(*t, TraceStep{At: time.Now().UTC(), Stage: stage, Msg: msg})
}

// Ingest is the whole pipeline for one event, synchronously. It never
// returns an error for a "bad" decision or outcome — a schema-invalid model
// or a down endpoint is normal operation, recorded in the decision and trace
// — only for persistence failures, which are the caller's (HTTP handler's)
// — only for persistence failures on writes that happen before any outcome
// is decided (the event row, the decision row). Once the outcome is chosen,
// the fate is known: later failures (execution row, trace) are logged, not
// propagated, because a 500 would claim "fate unknown" about a decided
// outcome and a source's retry would dedup-drop into nothing.
func (r *Runtime) Ingest(ctx context.Context, e event.Event) (*Response, error) {
	t := &[]TraceStep{}
	resp, err := r.ingest(ctx, e, t)
	if err != nil {
		return nil, err
	}
	// The trace is persisted once, here, rather than at each of ingest's
	// exits — one write, and every path is covered by construction.
	//
	// A duplicate is the exception: it never inserted an events row under
	// this id, so the trace's foreign key would have nothing to point at,
	// and there is nothing to inspect anyway — the original event's trace
	// already tells that story. A trace write failure is logged and the
	// response returned normally: the event, decision, and execution rows
	// are all durable and the outcome has fired, so the request succeeded
	// — only the durable copy of the trace is lost, and the in-memory
	// trace still goes out with the response.
	if !resp.Duplicate {
		if serr := r.DB.InsertTrace(e.ID, *t); serr != nil {
			log.Printf("mrmr: persist trace for %s failed (trace only in response): %v", e.ID, serr)
		}
	}
	return resp, nil
}

// ingest runs the pipeline and appends to the trace as it goes. It is
// separate from Ingest so that trace persistence has exactly one call site.
func (r *Runtime) ingest(ctx context.Context, e event.Event, t *[]TraceStep) (*Response, error) {
	step(t, "receive", fmt.Sprintf("type=%s source=%s", e.Type, e.Source))

	rec, err := r.DB.InsertEvent(e)
	if err != nil {
		return nil, fmt.Errorf("persist event: %w", err)
	}
	if rec.Duplicate {
		step(t, "duplicate", "dropped: (source, dedup_key) already seen")
		return &Response{EventID: e.ID, Duplicate: true, Trace: *t}, nil
	}
	step(t, "persist", "event stored")

	// Recursion guard for mrmr-emitted events. The event is durable and
	// traceable, but past the depth cap it is forced to ignore: a flow pair
	// emitting into each other must surface as ignore rows here, not as an
	// infinite model-calling loop.
	if e.Depth > maxDepth {
		step(t, "depth", fmt.Sprintf("causal depth %d exceeds max %d; recorded but forced to ignore", e.Depth, maxDepth))
		r.recordExecution(e.ID, "", "ignore", "", "ok", "max causal depth exceeded")
		step(t, "outcome", "executed ignore")
		return &Response{EventID: e.ID, Outcome: "ignore", Trace: *t}, nil
	}

	// Filters run after the event is durable and before any model
	// call: they are the cost gate. An excluded event produces no
	// Decision (the model never ran, and a Decision records model
	// judgment) but does produce an Execution row: the audit trail
	// must show where the event stopped. The adapter is empty because
	// a filter is a gate, not an Adapter under the project's domain
	// boundary; the filter trace stage names the stop point.
	if len(r.Filters) > 0 {
		passed, reason := r.Filters.Evaluate(e)
		if !passed {
			step(t, "filter", "excluded: "+reason)
			r.recordExecution(e.ID, "", "ignore", "", "filtered", "")
			step(t, "outcome", "executed ignore")
			return &Response{EventID: e.ID, Outcome: "ignore", Trace: *t}, nil
		}
		step(t, "filter", fmt.Sprintf("%d checks passed", len(r.Filters)))
	}

	dec := &event.Decision{ID: event.NewID("dec_"), EventID: e.ID, Interpreter: r.ModelKey, Model: r.ModelCfg.Model}

	eventJSON, _ := json.Marshal(e)
	result, latency, modelID, err := r.Client.InterpretWithQuestions(ctx, r.ModelCfg, r.ModelKey, r.Prompt, r.Schema, r.Questions, eventJSON)
	dec.Model = modelID
	dec.LatencyMs = latency

	if err != nil {
		if inv, ok := err.(*model.InvalidOutputError); ok {
			dec.Status = "invalid"
			dec.Error = inv.Error()
			step(t, "interpret", "schema-invalid after retry")
		} else {
			dec.Status = "errored"
			dec.Error = err.Error()
			step(t, "interpret", "model error: "+err.Error())
		}
	} else {
		dec.Status = "ok"
		dec.Result = result
		if b, jerr := json.Marshal(result); jerr == nil {
			step(t, "interpret", fmt.Sprintf("model=%s latency_ms=%d result=%s", modelID, latency, b))
		}
	}
	if serr := r.DB.InsertDecision(*dec); serr != nil {
		return nil, fmt.Errorf("persist decision: %w", serr)
	}

	// Fail toward ignore: invalid or errored decisions never reach policy.
	// A model that is down or wrong must not be able to trigger actions —
	// policy evaluates judgment, and there is no judgment to evaluate.
	var then policy.Then
	if dec.Status == "ok" {
		var ruleIdx int
		then, ruleIdx = r.Policy.Evaluate(dec.Result) // assignment, not := — the outer then must be set here
		if ruleIdx < 0 {
			step(t, "policy", "default → "+then.Outcome())
		} else {
			step(t, "policy", fmt.Sprintf("rule %d → %s", ruleIdx+1, then.Outcome()))
		}
	} else {
		then = policy.Then{Ignore: true}
		step(t, "policy", "routed to ignore ("+dec.Status+" decision)")
	}

	// Shadow records the outcome as if it had fired but executes nothing —
	// how a new flow earns trust before going live. Promotion is later a
	// config change, not a rewrite.
	execErr := ""
	if then.Shadow {
		step(t, "outcome", "shadow: "+then.Outcome()+" recorded but not executed")
	} else {
		execErr = r.execute(ctx, then, dec, e, t)
	}
	if execErr != "" {
		step(t, "outcome", "error: "+execErr)
	} else if !then.Shadow {
		step(t, "outcome", "executed "+then.Outcome())
	}
	status := "ok"
	switch {
	case execErr != "":
		status = "error"
	case then.Shadow:
		status = "shadow"
	}
	// This is the one execution write on a path where a side effect may
	// have already fired, so it must never fail the request: the outcome
	// is decided and the response still reports it. The audit gap (no
	// execution row) is real but a 500 would not repair it — the source's
	// retry would dedup-drop, losing the row permanently.
	r.recordExecution(e.ID, dec.ID, then.Outcome(), adapterFor(then), status, execErr)

	return &Response{EventID: e.ID, Decision: dec, Outcome: then.Outcome(), Trace: *t}, nil
}

// recordExecution persists an execution row, degrading to a log entry on
// failure. Every caller sits after the event row is durable and the outcome
// is decided, so a write failure must not fail the request — a 500 would
// claim "fate unknown" about a decided outcome and the source's retry would
// dedup-drop, losing the row permanently anyway.
func (r *Runtime) recordExecution(eventID, decisionID, outcome, adapter, status, execErr string) {
	if serr := r.DB.InsertExecution(event.NewID("exe_"), eventID, decisionID, outcome, adapter, status, execErr); serr != nil {
		log.Printf("mrmr: persist execution for %s failed: %v", eventID, serr)
	}
}

func adapterFor(t policy.Then) string {
	switch {
	case t.Notify != nil:
		return t.Notify.Via
	case t.Action != nil:
		return t.Action.Type
	case t.Delegate != nil:
		return t.Delegate.Agent
	}
	return ""
}

// execute performs the outcome's side effect and returns "" on success.
// Ignore is a success — most events should end here; suppressing noise is
// half the point of ambient AI. Emit recursion is synchronous by design:
// it is depth-capped, so no goroutines, no queue, nothing to leak.
func (r *Runtime) execute(ctx context.Context, t policy.Then, dec *event.Decision, parent event.Event, tr *[]TraceStep) string {
	switch {
	case t.Notify != nil:
		if t.Notify.Via != "stdout" {
			return fmt.Sprintf("unsupported notify via %q", t.Notify.Via) // config validation should prevent this
		}
		fmt.Println(renderMessage(t.Notify.Message, dec, parent))
		return ""

	case t.Action != nil:
		switch t.Action.Type {
		case "http":
			method := t.Action.Method
			if method == "" {
				method = http.MethodPost
			}
			// A default action body is JSON, not the human-readable notify
			// envelope. Reusing that envelope prefixes an event ID and sends
			// invalid JSON to an endpoint promised application/json.
			var body string
			if t.Action.Body == "" {
				payload, err := json.Marshal(dec.Result)
				if err != nil {
					return fmt.Sprintf("encode action body: %v", err)
				}
				body = string(payload)
			} else {
				body = renderMessage(t.Action.Body, dec, parent)
			}
			return r.do(ctx, method, t.Action.URL, body)
		case "emit":
			// The decision result becomes the child's data — the child flow's
			// interpreter judges meaning, it does not re-parse the parent's
			// decision row. ponytail: (source, source_event_id) = (mrmr,
			// parent id) means one emit per parent; multiple emit rules on one
			// flow would dedup-collide. Split flows if that's ever needed.
			child := event.Event{
				ID:        event.NewID("evt_"),
				Type:      t.Action.EventType,
				Source:    "mrmr",
				Timestamp: time.Now().UTC(),
				Data:      dec.Result,
				Metadata:  map[string]any{"source_event_id": parent.ID},
				Depth:     parent.Depth + 1,
			}
			step(tr, "emit", "emitted "+child.ID+" type="+child.Type+" depth="+fmt.Sprint(child.Depth))
			resp, err := r.Ingest(ctx, child)
			if err != nil {
				return fmt.Sprintf("emit: %v", err)
			}
			step(tr, "emit", "child outcome "+resp.Outcome)
			return ""
		}
		return fmt.Sprintf("unsupported action type %q", t.Action.Type) // config validation should prevent this

	case t.Delegate != nil:
		endpoint, ok := r.AgentEndpoints[t.Delegate.Agent]
		if !ok {
			return fmt.Sprintf("unknown agent %q", t.Delegate.Agent) // config validation should prevent this
		}
		// Generic HTTP agent contract: one POST, JSON payload, 2xx means
		// accepted. The agent's work is its own business; mrmr records that
		// it delegated, to whom, and why.
		payload, _ := json.Marshal(struct {
			EventID  string         `json:"event_id"`
			Decision map[string]any `json:"decision"`
			Prompt   string         `json:"prompt"`
		}{dec.EventID, dec.Result, t.Delegate.Prompt})
		return r.do(ctx, http.MethodPost, endpoint, string(payload))
	}
	return "" // ignore is a success
}

// do sends one bounded HTTP side effect and returns "" on a 2xx. The body
// is drained (bounded) so the connection is reusable; response content is
// not interpreted — actions are fire-and-record, not request/response.
func (r *Runtime) do(ctx context.Context, method, url, body string) string {
	req, err := http.NewRequestWithContext(ctx, method, url, strings.NewReader(body))
	if err != nil {
		return fmt.Sprintf("build request: %v", err)
	}
	if body != "" {
		req.Header.Set("Content-Type", "application/json")
	}
	resp, err := r.httpClient().Do(req)
	if err != nil {
		return fmt.Sprintf("http %s %s: %v", method, url, err)
	}
	defer resp.Body.Close()
	io.Copy(io.Discard, io.LimitReader(resp.Body, 1<<16))
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		return fmt.Sprintf("http %s %s: status %d", method, url, resp.StatusCode)
	}
	return ""
}

func (r *Runtime) httpClient() *http.Client {
	if r.HTTP != nil {
		return r.HTTP
	}
	return &http.Client{Timeout: 10 * time.Second}
}

// renderMessage applies the notify template over the decision result.
// An empty template renders the full result JSON so a bare `notify: {via: x}`
// is still useful. Template errors degrade to a bracketed note rather than
// dropping the notification — a notification with a hint of what went wrong
// beats silence.
func renderMessage(tmpl string, dec *event.Decision, e event.Event) string {
	if tmpl == "" {
		b, _ := json.Marshal(dec.Result)
		return fmt.Sprintf("[%s] %s", dec.EventID, b)
	}
	t, err := template.New("notify").Parse(tmpl)
	if err != nil {
		return fmt.Sprintf("[%s] (bad notify template: %v)", dec.EventID, err)
	}
	// Use lower-case map keys so templates follow the JSON/YAML vocabulary,
	// not Go field names. Supplying the whole normalized Event lets
	// non-generative interpreters produce useful notifications without
	// copying source text into their Decision.
	eventData := map[string]any{
		"id": e.ID, "type": e.Type, "source": e.Source, "subject": e.Subject,
		"timestamp": e.Timestamp, "data": e.Data, "metadata": e.Metadata, "depth": e.Depth,
	}
	var sb strings.Builder
	if err := t.Execute(&sb, map[string]any{"result": dec.Result, "event": eventData}); err != nil {
		return fmt.Sprintf("[%s] (template error: %v)", dec.EventID, err)
	}
	return sb.String()
}

// Package storage is mrmr's durable state: SQLite. This is deliberately
// the only package that knows a database exists. Migrations are explicit,
// additive, and applied in a transaction each — never silently destructive,
// because a runtime whose decisions can't be audited is a runtime whose
// decisions can't be trusted.
package storage

import (
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"time"

	_ "modernc.org/sqlite"

	"github.com/heath0xff/mrmr/internal/event"
)

// DB wraps the SQLite handle. A single connection is used because SQLite
// is serialized anyway; the events table doubles as the queue in later
// milestones, so writes funnel through one point.
type DB struct{ *sql.DB }

type EventRecord struct {
	Event     event.Event
	Duplicate bool
}

type EventLabel struct {
	EventID         string    `json:"event_id"`
	Category        string    `json:"category"`
	RequiresAction  bool      `json:"requires_action"`
	ExpectedOutcome string    `json:"expected_outcome"`
	LabeledAt       time.Time `json:"labeled_at"`
}

type ReviewEvent struct {
	Event    event.Event     `json:"event"`
	Decision *event.Decision `json:"decision,omitempty"`
	Outcome  string          `json:"outcome,omitempty"`
	Label    *EventLabel     `json:"label,omitempty"`
}

type LabeledEvent struct {
	Event event.Event `json:"event"`
	Label EventLabel  `json:"label"`
}

// Execution is one recorded outcome attempt for an event: what the runtime
// decided to do, which adapter did it, and how that ended. DecisionID is
// empty for outcomes reached without model judgment — a filter exclusion or
// a depth-capped emit — which is itself the answer to "why was there no
// decision here?".
type Execution struct {
	ID         string    `json:"id"`
	EventID    string    `json:"event_id"`
	DecisionID string    `json:"decision_id,omitempty"`
	Outcome    string    `json:"outcome"`
	Adapter    string    `json:"adapter,omitempty"`
	Status     string    `json:"status"`
	Error      string    `json:"error,omitempty"`
	CreatedAt  time.Time `json:"created_at"`
}

// Inspection is everything the runtime durably knows about one event, which
// is the whole point of `mrmr inspect`: an outcome nobody can explain after
// the fact is an outcome nobody can trust. Decisions and Executions are
// slices rather than single values because the schema permits more than one
// of each per event; the current pipeline writes one, and reporting what is
// actually stored beats encoding that assumption in the reader.
type Inspection struct {
	Event      event.Event       `json:"event"`
	Decisions  []event.Decision  `json:"decisions,omitempty"`
	Executions []Execution       `json:"executions,omitempty"`
	Trace      []event.TraceStep `json:"trace,omitempty"`
	Label      *EventLabel       `json:"label,omitempty"`
}

// Open opens (creating if needed) the SQLite database with WAL mode
// and applies pending migrations.
func Open(path string) (*DB, error) {
	dsn := path + "?_pragma=journal_mode(WAL)&_pragma=busy_timeout(5000)&_pragma=foreign_keys(1)"
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("open sqlite %s: %w", path, err)
	}
	db.SetMaxOpenConns(1) // ponytail: single writer; SQLite is serialized anyway. Callers must not hold an open rows iterator across another DB call — it will deadlock on this one connection.
	d := &DB{db}
	if err := d.migrate(); err != nil {
		db.Close()
		return nil, err
	}
	return d, nil
}

// migrations run in order; each is a forward-only transaction. Add new
// ones by appending — never edit an applied migration, since existing
// deployments have already recorded its version.
var migrations = []string{`
CREATE TABLE events (
	id         TEXT PRIMARY KEY,
	type       TEXT NOT NULL,
	source     TEXT NOT NULL,
	subject    TEXT NOT NULL DEFAULT '',
	event_time TEXT NOT NULL,
	ingest_time TEXT NOT NULL,
	data       TEXT,
	metadata   TEXT,
	dedup_key  TEXT NOT NULL,
	UNIQUE(source, dedup_key)
);
CREATE INDEX idx_events_time ON events(event_time);
`,
	`
CREATE TABLE decisions (
	id          TEXT PRIMARY KEY,
	event_id    TEXT NOT NULL REFERENCES events(id),
	interpreter TEXT NOT NULL,
	model       TEXT NOT NULL,
	status      TEXT NOT NULL,
	result      TEXT,
	latency_ms  INTEGER NOT NULL,
	error       TEXT,
	created_at  TEXT NOT NULL
);
CREATE INDEX idx_decisions_event ON decisions(event_id);
`,
	`
CREATE TABLE executions (
	id          TEXT PRIMARY KEY,
	event_id    TEXT NOT NULL REFERENCES events(id),
	decision_id TEXT REFERENCES decisions(id),
	outcome     TEXT NOT NULL,
	adapter     TEXT,
	status      TEXT NOT NULL,
	error       TEXT,
	created_at  TEXT NOT NULL
);
CREATE INDEX idx_executions_event ON executions(event_id);
`,
	`
CREATE TABLE event_labels (
	event_id          TEXT PRIMARY KEY REFERENCES events(id),
	category          TEXT NOT NULL,
	requires_action   INTEGER NOT NULL CHECK (requires_action IN (0, 1)),
	expected_outcome  TEXT NOT NULL,
	labeled_at        TEXT NOT NULL
);
CREATE INDEX idx_event_labels_time ON event_labels(labeled_at);
`,
	`
CREATE TABLE event_traces (
	event_id TEXT NOT NULL REFERENCES events(id),
	seq      INTEGER NOT NULL,
	at       TEXT NOT NULL,
	stage    TEXT NOT NULL,
	msg      TEXT NOT NULL DEFAULT '',
	PRIMARY KEY (event_id, seq)
);
`,
	`
CREATE TABLE source_cursors (
	name       TEXT PRIMARY KEY,
	cursor     TEXT NOT NULL,
	updated_at TEXT NOT NULL
);
`,
}

func (d *DB) migrate() error {
	if _, err := d.Exec(`CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL)`); err != nil {
		return fmt.Errorf("create schema_migrations: %w", err)
	}
	var cur int
	if err := d.QueryRow(`SELECT COALESCE(MAX(version), 0) FROM schema_migrations`).Scan(&cur); err != nil {
		return fmt.Errorf("read schema version: %w", err)
	}
	for i, m := range migrations[cur:] {
		v := cur + i + 1
		tx, err := d.Begin()
		if err != nil {
			return err
		}
		if _, err := tx.Exec(m); err != nil {
			tx.Rollback()
			return fmt.Errorf("apply migration %d: %w", v, err)
		}
		if _, err := tx.Exec(`INSERT INTO schema_migrations (version, applied_at) VALUES (?, ?)`, v, now()); err != nil {
			tx.Rollback()
			return fmt.Errorf("record migration %d: %w", v, err)
		}
		if err := tx.Commit(); err != nil {
			return err
		}
	}
	return nil
}

func now() string { return time.Now().UTC().Format(time.RFC3339Nano) }

// InsertEvent persists an event. Dedup key: metadata.source_event_id when
// present, otherwise a hash of the payload — delivery is at-least-once
// (webhook retries, poller overlap), so the same thing happening twice must
// be recognized as one event. Duplicates are reported, not silently
// swallowed: the trace says "duplicate" and the caller decides what that
// means.
func (d *DB) InsertEvent(e event.Event) (*EventRecord, error) {
	data, _ := json.Marshal(e.Data)
	meta, _ := json.Marshal(e.Metadata)
	dedup := event.SourceEventID(e.Metadata["source_event_id"])
	if dedup == "" {
		h := sha256.New()
		fmt.Fprint(h, e.Type, "\x00", e.Subject, "\x00", string(data))
		dedup = hex.EncodeToString(h.Sum(nil))
	}

	res, err := d.Exec(`INSERT INTO events (id, type, source, subject, event_time, ingest_time, data, metadata, dedup_key)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
		ON CONFLICT(source, dedup_key) DO NOTHING`,
		e.ID, e.Type, e.Source, e.Subject, e.Timestamp.Format(time.RFC3339Nano), now(), data, meta, dedup)
	if err != nil {
		return nil, fmt.Errorf("insert event %s: %w", e.ID, err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return nil, fmt.Errorf("insert event %s: %w", e.ID, err)
	}
	if n == 0 {
		return &EventRecord{Event: e, Duplicate: true}, nil
	}
	return &EventRecord{Event: e}, nil
}

func (d *DB) InsertDecision(dec event.Decision) error {
	result, _ := json.Marshal(dec.Result)
	_, err := d.Exec(`INSERT INTO decisions (id, event_id, interpreter, model, status, result, latency_ms, error, created_at)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		dec.ID, dec.EventID, dec.Interpreter, dec.Model, dec.Status, result, dec.LatencyMs, dec.Error, now())
	if err != nil {
		return fmt.Errorf("insert decision %s: %w", dec.ID, err)
	}
	return nil
}

func (d *DB) InsertExecution(id, eventID, decisionID, outcome, adapter, status, errMsg string) error {
	// decisionID may be empty for outcomes that produce no Decision
	// (filter-excluded events). The column is a foreign key, so empty
	// maps to NULL: an empty string would be a dangling reference.
	var decID any
	if decisionID != "" {
		decID = decisionID
	}
	_, err := d.Exec(`INSERT INTO executions (id, event_id, decision_id, outcome, adapter, status, error, created_at)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
		id, eventID, decID, outcome, adapter, status, errMsg, now())
	if err != nil {
		return fmt.Errorf("insert execution %s: %w", id, err)
	}
	return nil
}

// Trace persistence and the single-event inspection query. The trace is
// written once, after the pipeline has finished with an event: the steps
// describe work that already happened, so there is nothing to gain from
// writing them incrementally and something to lose — a second write per
// stage on the synchronous ingest path.
package storage

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"time"

	"github.com/heath0xff/mrmr/internal/event"
)

// InsertTrace persists an event's pipeline trace in one transaction, so an
// inspected trace is either the whole story or absent — a half-written
// trace would read as "the runtime stopped at policy" and be a lie.
//
// Steps are stored with their arrival order (seq) and read back by it
// rather than by timestamp: steps within one event can share a clock tick,
// and the sequence is what actually happened.
func (d *DB) InsertTrace(eventID string, steps []event.TraceStep) error {
	if len(steps) == 0 {
		return nil
	}
	tx, err := d.Begin()
	if err != nil {
		return fmt.Errorf("insert trace %s: %w", eventID, err)
	}
	defer tx.Rollback() // no-op once committed; covers every error return below

	stmt, err := tx.Prepare(`INSERT INTO event_traces (event_id, seq, at, stage, msg) VALUES (?, ?, ?, ?, ?)`)
	if err != nil {
		return fmt.Errorf("insert trace %s: %w", eventID, err)
	}
	defer stmt.Close()
	for i, s := range steps {
		if _, err := stmt.Exec(eventID, i, s.At.UTC().Format(time.RFC3339Nano), s.Stage, s.Msg); err != nil {
			return fmt.Errorf("insert trace %s step %d: %w", eventID, i, err)
		}
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("insert trace %s: %w", eventID, err)
	}
	return nil
}

// EventTrace returns one event's trace in pipeline order.
func (d *DB) EventTrace(eventID string) ([]event.TraceStep, error) {
	rows, err := d.Query(`SELECT at, stage, msg FROM event_traces WHERE event_id = ? ORDER BY seq`, eventID)
	if err != nil {
		return nil, fmt.Errorf("read trace %s: %w", eventID, err)
	}
	defer rows.Close()

	var steps []event.TraceStep
	for rows.Next() {
		var at, stage, msg string
		if err := rows.Scan(&at, &stage, &msg); err != nil {
			return nil, fmt.Errorf("scan trace %s: %w", eventID, err)
		}
		ts, err := time.Parse(time.RFC3339Nano, at)
		if err != nil {
			return nil, fmt.Errorf("decode trace %s step time: %w", eventID, err)
		}
		steps = append(steps, event.TraceStep{At: ts, Stage: stage, Msg: msg})
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("read trace %s: %w", eventID, err)
	}
	return steps, nil
}

// Inspect assembles everything stored about one event. It reads across four
// tables without a transaction: the pipeline is finished with an event by
// the time anyone inspects it, so there is no writer to race with, and a
// read transaction on the single shared connection would block ingest for
// no benefit.
func (d *DB) Inspect(eventID string) (*Inspection, error) {
	var (
		id, typ, source, subject, eventTime string
		dataJSON, metadataJSON              sql.NullString
	)
	err := d.QueryRow(`SELECT id, type, source, subject, event_time, data, metadata FROM events WHERE id = ?`, eventID).
		Scan(&id, &typ, &source, &subject, &eventTime, &dataJSON, &metadataJSON)
	if err == sql.ErrNoRows {
		return nil, fmt.Errorf("event %s not found", eventID)
	}
	if err != nil {
		return nil, fmt.Errorf("read event %s: %w", eventID, err)
	}
	e, err := decodeStoredEvent(id, typ, source, subject, eventTime, dataJSON, metadataJSON)
	if err != nil {
		return nil, err
	}
	ins := &Inspection{Event: e}

	if ins.Decisions, err = d.eventDecisions(eventID); err != nil {
		return nil, err
	}
	if ins.Executions, err = d.eventExecutions(eventID); err != nil {
		return nil, err
	}
	if ins.Trace, err = d.EventTrace(eventID); err != nil {
		return nil, err
	}
	if ins.Label, err = d.eventLabel(eventID); err != nil {
		return nil, err
	}
	return ins, nil
}

func (d *DB) eventDecisions(eventID string) ([]event.Decision, error) {
	rows, err := d.Query(`SELECT id, interpreter, model, status, result, latency_ms, error
		FROM decisions WHERE event_id = ? ORDER BY created_at, id`, eventID)
	if err != nil {
		return nil, fmt.Errorf("read decisions for %s: %w", eventID, err)
	}
	defer rows.Close()

	var out []event.Decision
	for rows.Next() {
		dec := event.Decision{EventID: eventID}
		var resultJSON, decErr sql.NullString
		if err := rows.Scan(&dec.ID, &dec.Interpreter, &dec.Model, &dec.Status, &resultJSON, &dec.LatencyMs, &decErr); err != nil {
			return nil, fmt.Errorf("scan decision for %s: %w", eventID, err)
		}
		dec.Error = decErr.String
		if resultJSON.Valid && resultJSON.String != "null" {
			if err := json.Unmarshal([]byte(resultJSON.String), &dec.Result); err != nil {
				return nil, fmt.Errorf("decode decision %s result: %w", dec.ID, err)
			}
		}
		out = append(out, dec)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("read decisions for %s: %w", eventID, err)
	}
	return out, nil
}

func (d *DB) eventExecutions(eventID string) ([]Execution, error) {
	rows, err := d.Query(`SELECT id, decision_id, outcome, adapter, status, error, created_at
		FROM executions WHERE event_id = ? ORDER BY created_at, id`, eventID)
	if err != nil {
		return nil, fmt.Errorf("read executions for %s: %w", eventID, err)
	}
	defer rows.Close()

	var out []Execution
	for rows.Next() {
		x := Execution{EventID: eventID}
		var decisionID, adapter, execErr sql.NullString
		var createdAt string
		if err := rows.Scan(&x.ID, &decisionID, &x.Outcome, &adapter, &x.Status, &execErr, &createdAt); err != nil {
			return nil, fmt.Errorf("scan execution for %s: %w", eventID, err)
		}
		x.DecisionID, x.Adapter, x.Error = decisionID.String, adapter.String, execErr.String
		at, err := time.Parse(time.RFC3339Nano, createdAt)
		if err != nil {
			return nil, fmt.Errorf("decode execution %s time: %w", x.ID, err)
		}
		x.CreatedAt = at
		out = append(out, x)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("read executions for %s: %w", eventID, err)
	}
	return out, nil
}

func (d *DB) eventLabel(eventID string) (*EventLabel, error) {
	var (
		category, expectedOutcome, labeledAt string
		requiresAction                       bool
	)
	err := d.QueryRow(`SELECT category, requires_action, expected_outcome, labeled_at
		FROM event_labels WHERE event_id = ?`, eventID).
		Scan(&category, &requiresAction, &expectedOutcome, &labeledAt)
	if err == sql.ErrNoRows {
		return nil, nil // unlabeled is the common case, not an error
	}
	if err != nil {
		return nil, fmt.Errorf("read label for %s: %w", eventID, err)
	}
	at, err := time.Parse(time.RFC3339Nano, labeledAt)
	if err != nil {
		return nil, fmt.Errorf("decode label for event %s: %w", eventID, err)
	}
	return &EventLabel{
		EventID: eventID, Category: category, RequiresAction: requiresAction,
		ExpectedOutcome: expectedOutcome, LabeledAt: at,
	}, nil
}

// Package event defines the records that flow through mrmr's pipeline: the
// Event (what happened, normalized), the Decision (what the model thought it
// meant), and the TraceStep (why the runtime did what it did). These types
// are intentionally boring and dependency-free — every stage of the runtime
// handles them, so any cleverness here would be paid for everywhere. data
// and metadata are opaque maps: the core makes no assumptions about what a
// source puts in them, because assuming is how source-specific logic leaks
// into the runtime.
package event

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"time"
)

// Event is the normalized record of something that happened. Sources are
// dumb by design: they detect and emit, they never interpret. The runtime
// stamps ID and Timestamp at ingestion — a source's clock is not trusted,
// though a source may carry its original time inside data or metadata if
// the event itself needs it.
type Event struct {
	ID        string         `json:"id"`
	Type      string         `json:"type"`
	Source    string         `json:"source"`
	Subject   string         `json:"subject,omitempty"`
	Timestamp time.Time      `json:"timestamp"` // event time, UTC
	Data      map[string]any `json:"data,omitempty"`
	Metadata  map[string]any `json:"metadata,omitempty"`
	// Depth is the causal hop count for events mrmr emitted itself
	// (emit-event actions, delegated-agent completions). Externally sourced
	// events are 0; each emit increments. The runtime forces ignore past its
	// max so a flow pair that emits into each other cannot recurse forever.
	Depth int `json:"depth,omitempty"`
}

// Decision is the validated result of interpreting an Event. Status is the
// axis the rest of the runtime cares about: "ok" decisions reach policy;
// "invalid" (schema failure after retry) and "errored" (endpoint failure)
// both route to ignore. Decisions persist even when they fail, because "the
// model was down at 3am" is a question worth answering from the audit trail.
type Decision struct {
	ID          string         `json:"id"`
	EventID     string         `json:"event_id"`
	Interpreter string         `json:"interpreter"` // model config name
	Model       string         `json:"model"`       // actual model id sent to endpoint
	Status      string         `json:"status"`
	Result      map[string]any `json:"result,omitempty"`
	LatencyMs   int64          `json:"latency_ms"`
	Error       string         `json:"error,omitempty"`
}

// TraceStep is one observable moment in an Event's journey through the
// pipeline: receive, persist, filter, interpret, policy, outcome. The trace
// is mrmr's answer to "why did this happen?" — it must be possible to
// explain any outcome by reading nothing but the trace, which is why the
// trace is durable rather than only returned to whoever posted the event.
//
// A step carries the validated Decision result when that is what the stage
// produced, but never a prompt and never a raw model response: those are
// opt-in debug capture, never normal audit data.
type TraceStep struct {
	At    time.Time `json:"at"`
	Stage string    `json:"stage"`
	Msg   string    `json:"msg,omitempty"`
}

// SourceEventID accepts only non-empty strings and JSON numbers as stable
// source identities. Null and compound values are not IDs: formatting them
// with fmt.Sprint would make unrelated events share keys such as "<nil>".
// An empty result lets storage fall back to the payload hash; a source that
// requires a cursor must instead skip the record and retain its checkpoint.
func SourceEventID(v any) string {
	switch n := v.(type) {
	case string:
		return n
	case json.Number, int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64, float32, float64:
		// Marshal validates json.Number and rejects NaN/Inf for internal
		// callers without rounding exact JSON or integer values to floats.
		if b, err := json.Marshal(n); err == nil {
			return string(b)
		}
	}
	return ""
}

// NewID returns a sortable unique id: prefix + hex(unix-millis + random).
// ponytail: hand-rolled instead of a ULID dep; swap if cross-system ordering matters.
func NewID(prefix string) string {
	var b [10]byte
	ms := time.Now().UnixMilli()
	for i := 0; i < 6; i++ {
		b[i] = byte(ms >> (8 * (5 - i)))
	}
	if _, err := rand.Read(b[6:]); err != nil {
		panic(fmt.Sprintf("new id: %v", err))
	}
	return prefix + hex.EncodeToString(b[:])
}

// Package policy evaluates deterministic first-match-wins rules against a
// decision result. This is where mrmr's core invariant lives: the model
// recommends, the runtime decides. Everything here is pure evaluation —
// no I/O, no time, no randomness — so a given (rules, result) pair always
// produces the same outcome, which is what makes policy inspectable and
// trustworthy. Condition semantics are deliberately minimal (ANDed
// conditions, literal equality or a handful of operators, first match wins,
// no OR or nesting); anything richer is a later addition, not a v0 gap.
package policy

import (
	"fmt"
	"strconv"
	"strings"
)

// Notify describes a notification outcome. Via names the adapter; v0.1
// ships only stdout. Message is a Go template executed over the decision
// result so flows can surface the model's own summary.
type Notify struct {
	Via     string `yaml:"via"`
	Message string `yaml:"message"` // Go template over {result: ...}; empty = summary default
}

// Action is a bounded deterministic action. Type http sends an HTTP request
// (Method defaults to POST; Body is a Go template over the decision, default
// the full result JSON). Type emit re-ingests a new Event into the runtime
// (EventType names it; the decision result becomes its data) — the recursion
// guard lives in the runtime, not here.
type Action struct {
	Type      string `yaml:"type"`
	Method    string `yaml:"method"`
	URL       string `yaml:"url"`
	Body      string `yaml:"body"`
	EventType string `yaml:"event_type"` // emit only
}

// Delegate hands the event to a more capable agent via a generic HTTP
// endpoint. Agent names an entry in the config's `agents:` map; the runtime
// resolves it to an endpoint, so policy never carries URLs.
type Delegate struct {
	Agent  string `yaml:"agent"`
	Prompt string `yaml:"prompt"`
}

// Then is the selected outcome for an event. At most one of Notify, Action,
// Delegate, Ignore is set; config validation enforces that, and the runtime
// trusts it. Shadow is an orthogonal modifier: the outcome is decided and
// recorded exactly as it would fire, but no side effect leaves the runtime —
// that is how a new flow earns trust before going live. Shadow alone (no
// outcome) means ignore.
type Then struct {
	Notify   *Notify   `yaml:"notify"`
	Action   *Action   `yaml:"action"`
	Delegate *Delegate `yaml:"delegate"`
	Ignore   bool      `yaml:"ignore"`
	Shadow   bool      `yaml:"shadow"`
}

func (t Then) Outcome() string {
	switch {
	case t.Action != nil:
		return "act"
	case t.Delegate != nil:
		return "delegate"
	case t.Notify != nil:
		return "notify"
	default:
		return "ignore"
	}
}

// Rule is one policy line: ANDed conditions and the outcome they select.
type Rule struct {
	If   map[string]any `yaml:"if"` // ANDed; value is literal or operator string
	Then Then           `yaml:"then"`
}

// Policy is the ordered rule list plus the fall-through default. Order is
// significant: rules evaluate top to bottom and the first match wins, so a
// policy file reads like the author's priority order.
type Policy struct {
	Rules   []Rule `yaml:"policy"`
	Default Then   `yaml:"default"`
}

// Evaluate returns the outcome of the first rule whose conditions all match,
// or the default. The second return value is the matched rule's index into
// Rules (0-based), or -1 when the default applied — the trace needs to say
// *which* rule fired, not just what it did, or "why did this happen?" is
// half-answered. A condition naming a field the result doesn't have simply
// doesn't match — missing data must fall through to less aggressive
// outcomes, never block them.
func (p Policy) Evaluate(result map[string]any) (Then, int) {
	for i, r := range p.Rules {
		if matchesAll(r.If, result) {
			return r.Then, i
		}
	}
	return p.Default, -1
}

func matchesAll(conds map[string]any, result map[string]any) bool {
	for key, want := range conds {
		path := strings.TrimPrefix(key, "result.")
		got, ok := lookup(result, path)
		if !ok || !match(want, got) {
			return false
		}
	}
	return true
}

// lookup follows dot-separated object fields. Flat results keep their
// existing behavior, while typed interpreters can expose raw nested answers
// such as category.choice without flattening away probabilities.
func lookup(result map[string]any, path string) (any, bool) {
	var current any = result
	for _, part := range strings.Split(path, ".") {
		object, ok := current.(map[string]any)
		if !ok {
			return nil, false
		}
		current, ok = object[part]
		if !ok {
			return nil, false
		}
	}
	return current, true
}

// match compares a condition value against the actual result value. A
// string condition is either an operator expression ("> 0.8") or a literal
// for equality; anything else (numbers, booleans) is a literal. Comparison
// is by fmt.Sprint so YAML scalars and JSON values line up without a
// type-coercion matrix.
func match(want any, got any) bool {
	if w, ok := want.(string); ok {
		if op, operand, isOp := parseOperator(w); isOp {
			return compareOp(op, operand, got)
		}
	}
	return fmt.Sprint(want) == fmt.Sprint(got)
}

var ops = []string{">=", "<=", "!=", ">", "<"}

// parseOperator recognizes "> x", ">= x", "< x", "<= x", "!= x".
func parseOperator(s string) (op, operand string, ok bool) {
	s = strings.TrimSpace(s)
	for _, o := range ops {
		if strings.HasPrefix(s, o) {
			return o, strings.TrimSpace(s[len(o):]), true
		}
	}
	return "", "", false
}

// compareOp applies an operator. Numeric comparison requires both sides to
// parse as numbers; ordering operators on non-numbers are false rather than
// an error, which keeps evaluation pure and total. "!" is the one operator
// that also makes sense for strings.
func compareOp(op, operand string, got any) bool {
	g, err1 := strconv.ParseFloat(fmt.Sprint(got), 64)
	w, err2 := strconv.ParseFloat(operand, 64)
	numeric := err1 == nil && err2 == nil
	switch op {
	case "!=":
		if numeric {
			return g != w
		}
		return fmt.Sprint(got) != operand
	case ">":
		return numeric && g > w
	case ">=":
		return numeric && g >= w
	case "<":
		return numeric && g < w
	case "<=":
		return numeric && g <= w
	}
	return false
}

package main

import (
	"bufio"
	"bytes"
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"time"

	"github.com/heath0xff/mrmr/internal/config"
	"github.com/heath0xff/mrmr/internal/event"
	"github.com/heath0xff/mrmr/internal/model"
)

type evalCase struct {
	Name     string      `json:"name"`
	Event    event.Event `json:"event"`
	Expected struct {
		Category       string `json:"category"`
		RequiresAction *bool  `json:"requires_action"`
		Outcome        string `json:"outcome"`
	} `json:"expected"`
}

type evalSummary struct {
	Total             int     `json:"total"`
	ValidDecisions    int     `json:"valid_decisions"`
	CategoryCorrect   int     `json:"category_correct"`
	CategoryAccuracy  float64 `json:"category_accuracy"`
	ActionCorrect     int     `json:"requires_action_correct"`
	ActionAccuracy    float64 `json:"requires_action_accuracy"`
	OutcomeCorrect    int     `json:"outcome_correct"`
	OutcomeAccuracy   float64 `json:"outcome_accuracy"`
	ExpectedNonIgnore int     `json:"expected_non_ignore"`
	FalseIgnores      int     `json:"false_ignores"`
	FalseIgnoreRate   float64 `json:"false_ignore_rate"`
}

func eval(args []string) error {
	fs := flag.NewFlagSet("mrmr eval", flag.ContinueOnError)
	configPath := fs.String("config", "mrmr.yaml", "path to config file")
	datasetPath := fs.String("dataset", "testdata/generated-eval.jsonl", "path to labeled JSONL dataset")
	if err := fs.Parse(args); err != nil {
		return err
	}

	cfg, err := config.Load(*configPath)
	if err != nil {
		return err
	}
	switch cfg.Models[cfg.Interpret.Model].Provider {
	case "openai-compatible":
		if f, ok := cfg.Interpret.Schema["category"]; !ok || f.Type != "string" {
			return fmt.Errorf("eval requires string interpret.schema field %q", "category")
		}
		if f, ok := cfg.Interpret.Schema["requires_action"]; !ok || f.Type != "boolean" {
			return fmt.Errorf("eval requires boolean interpret.schema field %q", "requires_action")
		}
	case "typesafe":
		if q, ok := cfg.Interpret.Questions["category"]; !ok || q.Type != "choice" {
			return fmt.Errorf("eval requires choice interpret.questions entry %q", "category")
		}
		if q, ok := cfg.Interpret.Questions["requires_action"]; !ok || q.Type != "noul" {
			return fmt.Errorf("eval requires noul interpret.questions entry %q", "requires_action")
		}
	}
	cases, err := loadEvalCases(*datasetPath)
	if err != nil {
		return err
	}

	summary := evaluate(context.Background(), cfg, cases, os.Stderr)
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	return enc.Encode(summary)
}

func loadEvalCases(path string) ([]evalCase, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("open dataset %s: %w", path, err)
	}
	defer f.Close()

	var cases []evalCase
	s := bufio.NewScanner(f)
	s.Buffer(make([]byte, 64*1024), 1<<20)
	for line := 1; s.Scan(); line++ {
		if len(s.Bytes()) == 0 {
			continue
		}
		var tc evalCase
		// Exported numeric identities must survive evaluation as written,
		// not round through float64 before reaching the model.
		dec := json.NewDecoder(bytes.NewReader(s.Bytes()))
		dec.UseNumber()
		if err := dec.Decode(&tc); err != nil {
			return nil, fmt.Errorf("parse dataset %s line %d: %w", path, line, err)
		}
		if err := dec.Decode(new(any)); err != io.EOF {
			return nil, fmt.Errorf("parse dataset %s line %d: expected one JSON object", path, line)
		}
		if tc.Name == "" || tc.Event.Type == "" || tc.Event.Source == "" || tc.Expected.Category == "" || tc.Expected.RequiresAction == nil {
			return nil, fmt.Errorf("parse dataset %s line %d: name, event type/source, category, and requires_action are required", path, line)
		}
		if tc.Expected.Outcome != "ignore" && tc.Expected.Outcome != "notify" {
			return nil, fmt.Errorf("parse dataset %s line %d: outcome must be ignore or notify", path, line)
		}
		cases = append(cases, tc)
	}
	if err := s.Err(); err != nil {
		return nil, fmt.Errorf("read dataset %s: %w", path, err)
	}
	if len(cases) == 0 {
		return nil, fmt.Errorf("dataset %s is empty", path)
	}
	return cases, nil
}

func evaluate(ctx context.Context, cfg *config.Config, cases []evalCase, progress io.Writer) evalSummary {
	summary := evalSummary{Total: len(cases)}
	client := &model.Client{}
	for i, tc := range cases {
		e := tc.Event
		// Generated fixtures may omit identity/time; keep their defaults
		// deterministic without rewriting the evidence in real events.
		if e.ID == "" {
			e.ID = fmt.Sprintf("eval_%03d", i+1)
		}
		if e.Timestamp.IsZero() {
			e.Timestamp = time.Date(2026, time.January, 1, 12, 0, 0, 0, time.UTC)
		}
		payload, _ := json.Marshal(e)
		result, _, _, err := client.InterpretWithQuestions(ctx, cfg.Models[cfg.Interpret.Model], cfg.Interpret.Model, cfg.Interpret.Prompt, cfg.Interpret.Schema, cfg.Interpret.Questions, payload)

		category, requiresAction, outcome := "", false, "ignore"
		if err == nil {
			summary.ValidDecisions++
			category = evaluatedCategory(result)
			requiresAction = evaluatedRequiresAction(result)
			then, _ := cfg.Policy.Evaluate(result)
			outcome = then.Outcome()
		}

		categoryOK := err == nil && category == tc.Expected.Category
		actionOK := err == nil && requiresAction == *tc.Expected.RequiresAction
		outcomeOK := err == nil && outcome == tc.Expected.Outcome
		if categoryOK {
			summary.CategoryCorrect++
		}
		if actionOK {
			summary.ActionCorrect++
		}
		if outcomeOK {
			summary.OutcomeCorrect++
		}
		if tc.Expected.Outcome != "ignore" {
			summary.ExpectedNonIgnore++
			if outcome == "ignore" {
				summary.FalseIgnores++
			}
		}

		if err != nil {
			fmt.Fprintf(progress, "[%d/%d] ERROR %s: %v\n", i+1, len(cases), tc.Name, err)
		} else if categoryOK && actionOK && outcomeOK {
			fmt.Fprintf(progress, "[%d/%d] PASS  %s\n", i+1, len(cases), tc.Name)
		} else {
			fmt.Fprintf(progress, "[%d/%d] FAIL  %s: got category=%s requires_action=%t outcome=%s\n", i+1, len(cases), tc.Name, category, requiresAction, outcome)
		}
	}

	summary.CategoryAccuracy = ratio(summary.CategoryCorrect, summary.Total)
	summary.ActionAccuracy = ratio(summary.ActionCorrect, summary.Total)
	summary.OutcomeAccuracy = ratio(summary.OutcomeCorrect, summary.Total)
	summary.FalseIgnoreRate = ratio(summary.FalseIgnores, summary.ExpectedNonIgnore)
	return summary
}

// The evaluation dataset predates provider-specific result shapes. Preserve
// its labels while reading either a flat OpenAI-compatible result or the raw
// typed TypeSafe answer. A Noul's natural yes/no boundary is 0.5; policy may
// and usually should use a stricter threshold for consequential outcomes.
func evaluatedCategory(result map[string]any) string {
	if value, ok := result["category"].(string); ok {
		return value
	}
	if answer, ok := result["category"].(map[string]any); ok {
		value, _ := answer["choice"].(string)
		return value
	}
	return ""
}

func evaluatedRequiresAction(result map[string]any) bool {
	if value, ok := result["requires_action"].(bool); ok {
		return value
	}
	if answer, ok := result["requires_action"].(map[string]any); ok {
		value, _ := answer["noul"].(float64)
		return value >= 0.5
	}
	return false
}

func ratio(n, total int) float64 {
	if total == 0 {
		return 0
	}
	return float64(n) / float64(total)
}

#!/usr/bin/env python3
"""A loopback-only d1 CPU server for mrmr's existing System One client.

This is a serving recipe, not another runtime or provider framework. It accepts
text/JSON state only, never fetches URLs, and leaves response validation and all
policy authority in mrmr. No prompts, events, tokens, or answers are logged.
"""

import argparse
import hmac
import importlib
import json
import os
from pathlib import Path
import re
from http.server import BaseHTTPRequestHandler, HTTPServer

REVISION = "da1fe36a861f24690f27f622dca1d8688503d113"
MODEL = f"LiquidAI/d1-3B@{REVISION}"
MAX_BODY = 16 * 1024
# A CPU dogfood ceiling, not the model's advertised 32K context. Counting each
# question's full prompt overcounts the shared state, deliberately conservatively.
MAX_TOKENS = 1024
ID = re.compile(r"[A-Za-z0-9_-]+\Z")


def model_id(int8=False):
    # Quantization changes probabilities. Never report the fp32 identity for an
    # int8 decision: stored traces must identify the variant actually evaluated.
    return MODEL + (":cpu-int8-channel" if int8 else ":cpu-fp32")


def reject_constant(_):
    raise ValueError("non-finite JSON number")


def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate JSON key")
        result[key] = value
    return result


def validate_request(value, expected_model):
    """Reject malformed input before invoking upstream custom model code.

    These checks mirror mrmr's question subset, plus serving resource limits.
    The HTTP boundary needs them even when the usual caller already validates.
    """
    if not isinstance(value, dict) or set(value) != {"model", "state", "questions"}:
        raise ValueError("expected model, state, and questions")
    if value["model"] != expected_model:
        raise ValueError("model does not match loaded variant")
    questions = value["questions"]
    if not isinstance(questions, dict) or not 1 <= len(questions) <= 8:
        raise ValueError("expected 1 to 8 questions")
    for name, question in questions.items():
        if not ID.fullmatch(name) or not isinstance(question, dict):
            raise ValueError("invalid question")
        if not {"type", "instructions"} <= set(question) <= {"type", "instructions", "criteria"}:
            raise ValueError("invalid question fields")
        instructions = question["instructions"]
        if not isinstance(instructions, str) or not instructions.strip():
            raise ValueError("instructions are required")
        kind, criteria = question["type"], question.get("criteria")
        if kind == "noul" and criteria is None:
            continue
        if kind in ("choice", "noul"):
            if not isinstance(criteria, dict):
                raise ValueError("criteria must be an object")
            if kind == "choice" and not 2 <= len(criteria) <= 255:
                raise ValueError("choice needs 2 to 255 options")
            if kind == "noul" and set(criteria) != {"true", "false"}:
                raise ValueError("noul needs true and false criteria")
            if any(not ID.fullmatch(key) for key in criteria):
                raise ValueError("invalid criterion name")
            descriptions = criteria.values()
        elif kind == "score":
            if not isinstance(criteria, list) or not 2 <= len(criteria) <= 10:
                raise ValueError("score needs 2 to 10 levels")
            descriptions = criteria
        else:
            raise ValueError("unsupported question type")
        if any(not isinstance(text, str) or not text.strip() for text in descriptions):
            raise ValueError("criteria need nonempty descriptions")
    return value


def load_decider(checkpoint, threads, int8=False):
    # Downloads are an explicit setup step. Loading by local path also pins the
    # tokenizer that upstream lazily loads without forwarding a Hub revision.
    # Offline mode prevents request data from triggering any Hub/network access.
    os.environ["HF_HUB_OFFLINE"] = "1"
    os.environ["HF_HUB_DISABLE_TELEMETRY"] = "1"
    os.environ["TOKENIZERS_PARALLELISM"] = "false"
    import torch
    from transformers import AutoModel

    torch.set_num_threads(threads)
    torch.set_num_interop_threads(1)
    model = AutoModel.from_pretrained(
        str(checkpoint), trust_remote_code=True, local_files_only=True,
        dtype=torch.float32,
    ).eval()
    if int8:
        # Experimental: per-channel language-model weights, with the output head
        # left in fp32. Whole-model default int8 flipped a synthetic yes/no answer.
        # This variant also shifts probabilities and needs its own quality gate.
        from torch.ao.quantization import quantize_dynamic, per_channel_dynamic_qconfig
        quantize_dynamic(
            model.model.language_model,
            {torch.nn.Linear: per_channel_dynamic_qconfig}, inplace=True,
        )
    # Use the pinned model's own prompt renderer to enforce the token ceiling;
    # estimating from characters would undercount many Unicode inputs.
    prompt = importlib.import_module(model.__class__.__module__.rsplit(".", 1)[0] + ".prompt")
    engine = model.engine

    def decide(state, questions):
        tokens = sum(engine.tokens(state, [prompt.as_question(q)]) for q in questions.values())
        if tokens > MAX_TOKENS:
            raise ValueError("CPU request token limit exceeded")
        return model.system_one(state, questions)

    return decide


class DecisionServer(HTTPServer):
    # ponytail: one request at a time, one small listen backlog. Add bounded
    # admission/workers only if real throughput requires it; never share this
    # mutable model across unbounded request threads.
    request_queue_size = 1

    def __init__(self, address, decide, token, identity):
        self.decide, self.token, self.identity = decide, token, identity
        super().__init__(address, Handler)

    def get_request(self):
        connection, address = super().get_request()
        connection.settimeout(5)  # Slow/incomplete HTTP bodies cannot park the server forever.
        return connection, address

    def handle_error(self, request, client_address):
        # BaseServer's traceback can include model exceptions containing state.
        print("d1: request failed", flush=True)


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *_):
        pass  # Even URLs and headers are caller-controlled and potentially sensitive.

    def reply(self, status, body):
        encoded = json.dumps(body, allow_nan=False).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(encoded)))
        self.send_header("Connection", "close")
        self.end_headers()
        self.wfile.write(encoded)
        self.close_connection = True

    def authorized(self):
        values = self.headers.get_all("Authorization", [])
        expected = ("Bearer " + self.server.token).encode()
        if len(values) != 1 or not hmac.compare_digest(values[0].encode(), expected):
            self.reply(401, {"error": "unauthorized"})
            return False
        return True

    def do_GET(self):
        if self.authorized():
            if self.path == "/health":
                self.reply(200, {"model": self.server.identity, "status": "ready"})
            else:
                self.reply(404, {"error": "not found"})

    def do_POST(self):
        if not self.authorized():
            return
        if self.path != "/v1/systemone":
            self.reply(404, {"error": "not found"})
            return
        try:
            lengths = self.headers.get_all("Content-Length", [])
            if len(lengths) != 1 or "Transfer-Encoding" in self.headers:
                raise ValueError("one content length required")
            size = int(lengths[0])
            if not 0 < size <= MAX_BODY:
                self.reply(413, {"error": "body limit exceeded"})
                return
            if self.headers.get_content_type() != "application/json":
                self.reply(415, {"error": "application/json required"})
                return
            body = self.rfile.read(size)
            if len(body) != size:
                raise ValueError("incomplete body")
            value = json.loads(body, parse_constant=reject_constant, object_pairs_hook=unique_object)
            # Also reject overflowing JSON numbers (1e999), which parse_constant
            # does not see, before passing any state to the model.
            json.dumps(value, allow_nan=False)
            validate_request(value, self.server.identity)
        except (ValueError, UnicodeError, RecursionError, TimeoutError):
            self.reply(400, {"error": "invalid request"})
            return
        try:
            result = self.server.decide(value["state"], value["questions"])
            self.reply(200, {**result, "model": self.server.identity})
        except ValueError:
            self.reply(400, {"error": "request rejected by model"})
        except Exception:
            # mrmr receives a bounded failure and routes to ignore. Never echo
            # upstream exceptions: they can contain private state or prompts.
            self.reply(500, {"error": "inference failed"})


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--checkpoint", type=Path, required=True)
    parser.add_argument("--port", type=int, default=8091)
    parser.add_argument("--threads", type=int, default=4)
    parser.add_argument("--int8", action="store_true", help="experimental; changes probabilities")
    args = parser.parse_args()
    token = os.environ.get("MRMR_D1_API_KEY", "")
    if len(token) < 32 or not token.isascii() or any(c.isspace() for c in token):
        parser.error("MRMR_D1_API_KEY must contain at least 32 non-whitespace ASCII characters")
    if not args.checkpoint.is_dir() or not 1 <= args.threads <= 22 or not 1 <= args.port <= 65535:
        parser.error("invalid checkpoint, thread count, or port")
    decide = load_decider(args.checkpoint.resolve(), args.threads, args.int8)
    # No public-bind switch: remote clients use an SSH tunnel until an explicit
    # authenticated network deployment has been reviewed.
    with DecisionServer(("127.0.0.1", args.port), decide, token, model_id(args.int8)) as server:
        print(f"d1 ready on loopback:{args.port} ({server.identity})", flush=True)
        try:
            server.serve_forever()
        except KeyboardInterrupt:
            pass


if __name__ == "__main__":
    main()

// These tests pin the whole mrmr loop end to end against a mock
// OpenAI-compatible endpoint and a real SQLite database. The invariants
// that matter: a decision must be persisted for every interpreted
// non-duplicate event, invalid or errored interpretation must never reach
// policy (fail toward ignore), and duplicates and filter-excluded events
// must short-circuit before the model is called.
package runtime

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"sync/atomic"
	"testing"
	"time"

	"github.com/heath0xff/mrmr/internal/event"
	"github.com/heath0xff/mrmr/internal/filter"
	"github.com/heath0xff/mrmr/internal/model"
	"github.com/heath0xff/mrmr/internal/policy"
	"github.com/heath0xff/mrmr/internal/storage"
)

// fail500 marks a model server response as an internal server error
// instead of content, letting one canned-sequence server cover both the
// content and the transport-failure cases.
const fail500 = "\x00http500"

func testEvent(sourceEventID string) event.Event {
	e := event.Event{
		ID:        event.NewID("evt_"),
		Type:      "commit.pushed",
		Source:    "github",
		Subject:   "mrmr",
		Timestamp: time.Now().UTC(),
		Data:      map[string]any{"msg": "fix bug"},
	}
	if sourceEventID != "" {
		e.Metadata = map[string]any{"source_event_id": sourceEventID}
	}
	return e
}

// modelServer serves canned assistant contents in request order, repeating
// the last one if the client asks more times than expected. The call count
// doubles as an assertion hook: duplicates must never increment it.
func modelServer(t *testing.T, contents ...string) (url string, calls *atomic.Int32) {
	t.Helper()
	var n atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		i := int(n.Add(1)) - 1
		content := contents[len(contents)-1]
		if i < len(contents) {
			content = contents[i]
		}
		if content == fail500 {
			w.WriteHeader(http.StatusInternalServerError)
			fmt.Fprint(w, "model down")
			return
		}
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]any{
			"choices": []any{map[string]any{"message": map[string]any{"content": content}}},
		})
	}))
	t.Cleanup(srv.Close)
	return srv.URL, &n
}

func newTestRuntime(t *testing.T, modelURL string) *Runtime {
	t.Helper()
	db, err := storage.Open(filepath.Join(t.TempDir(), "runtime.db"))
	if err != nil {
		t.Fatalf("open storage: %v", err)
	}
	t.Cleanup(func() { db.Close() })

	// Minimal interpretation contract: classify and score the event, with
	// the enum so bad categories become schema violations, and a single
	// threshold rule routing high-importance events to stdout.
	return &Runtime{
		DB:     db,
		Client: &model.Client{},
		ModelCfg: model.Config{
			Provider: "openai-compatible",
			BaseURL:  modelURL,
			Model:    "mock-model",
		},
		ModelKey: "mock",
		Prompt:   "classify this event",
		Schema: model.Schema{
			"category":   {Type: "string", Enum: []any{"important", "unimportant"}},
			"importance": {Type: "number"},
		},
		Policy: policy.Policy{
			Rules: []policy.Rule{{
				If:   map[string]any{"result.importance": "> 0.8"},
				Then: policy.Then{Notify: &policy.Notify{Via: "stdout"}},
			}},
			Default: policy.Then{Ignore: true},
		},
	}
}

func stages(resp *Response) []string {
	out := make([]string, len(resp.Trace))
	for i, s := range resp.Trace {
		out[i] = s.Stage
	}
	return out
}

func hasStages(t *testing.T, resp *Response, want ...string) {
	t.Helper()
	got := stages(resp)
	if len(got) != len(want) {
		t.Fatalf("trace stages = %v, want %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("trace stages = %v, want %v", got, want)
		}
	}
}

func TestIngestImportantEventNotifies(t *testing.T) {
	url, _ := modelServer(t, `{"category":"important","importance":0.95}`)
	rt := newTestRuntime(t, url)

	resp, err := rt.Ingest(context.Background(), testEvent("gh-1"))
	if err != nil {
		t.Fatalf("Ingest: %v", err)
	}
	if resp.Outcome != "notify" {
		t.Errorf("outcome = %q, want notify", resp.Outcome)
	}
	if resp.Decision == nil || resp.Decision.Status != "ok" {
		t.Fatalf("decision = %+v, want status ok", resp.Decision)
	}
	if resp.Decision.Result["importance"] != 0.95 {
		t.Errorf("decision result = %v, want the model's validated result", resp.Decision.Result)
	}
	// The full pipeline must be traceable in order: what was received,
	// stored, interpreted, matched, and executed.
	hasStages(t, resp, "receive", "persist", "interpret", "policy", "outcome")
}

