		t.Errorf("outcome = %q, want notify (the side effect fired)", resp.Outcome)
	}
}

// These tests pin the model client's contract with OpenAI-compatible
// endpoints: schema-validated structured output despite unreliable local
// models. The invariant that matters most is that *InvalidOutputError is
// distinguishable from transport failure — the runtime routes invalid
// output to a retry-with-feedback path and transport failure to an errored
// decision, so conflating them would break the fail-toward-ignore story.
package model

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"testing"
)

func testConfig(baseURL string) Config {
	return Config{Provider: "openai-compatible", BaseURL: baseURL, Model: "mock-model"}
}

func testSchema() Schema {
	min, max := 0.0, 1.0
	return Schema{
		"category":   {Type: "string", Enum: []any{"important", "unimportant"}},
		"importance": {Type: "number", Minimum: &min, Maximum: &max},
	}
}

// chatBody renders a minimal chat completion response carrying the given
// assistant content. Local model servers vary wildly in response shape;
// this is the one shape the client actually depends on.
func chatBody(content string) map[string]any {
	return map[string]any{
		"choices": []any{
			map[string]any{"message": map[string]any{"content": content}},
		},
	}
}

// contentServer serves the given assistant contents in request order,
// repeating the last one if the client asks more times than expected.
// Each HTTP request decodes to exactly one model attempt, which makes the
// sequence the observable behavior under test.
func contentServer(t *testing.T, contents ...string) (*httptest.Server, *int) {
	t.Helper()
	calls := 0
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		i := calls
		calls++
		content := contents[len(contents)-1]
		if i < len(contents) {
			content = contents[i]
		}
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(chatBody(content))
	}))
	t.Cleanup(srv.Close)
	return srv, &calls
}

func TestInterpretHappyPath(t *testing.T) {
	srv, calls := contentServer(t, `{"category":"important","importance":0.95}`)
	c := &Client{}
	res, _, model, err := c.Interpret(context.Background(), testConfig(srv.URL), "mock", "classify", testSchema(), []byte(`{}`))
	if err != nil {
		t.Fatalf("Interpret: %v", err)
	}
	if res["category"] != "important" || res["importance"] != 0.95 {
		t.Errorf("result = %v, want category=important importance=0.95", res)
	}
	if model != "mock-model" {
		t.Errorf("model = %q, want mock-model", model)
	}
	if *calls != 1 {
		t.Errorf("endpoint called %d times, want 1 (valid output must not retry)", *calls)
	}
}

func TestInterpretFencedOrProseWrappedJSON(t *testing.T) {
	// Local models routinely wrap JSON in markdown fences or chatter.
	// The client must extract the object rather than fail the parse,
	// otherwise every chatty model looks like a schema violation.
	wrapped := "Sure! Here's my analysis:\n```json\n{\"category\":\"unimportant\",\"importance\":0.1}\n```\nHope that helps."
	srv, _ := contentServer(t, wrapped)
	c := &Client{}
	res, _, _, err := c.Interpret(context.Background(), testConfig(srv.URL), "mock", "classify", testSchema(), []byte(`{}`))
	if err != nil {
		t.Fatalf("Interpret with fenced content: %v", err)
	}
	if res["category"] != "unimportant" || res["importance"] != 0.1 {
		t.Errorf("result = %v, want fenced JSON parsed", res)
	}
}

func TestInterpretInvalidThenCorrectedRetry(t *testing.T) {
	// The self-correction path: the first output fails validation and the
	// client replays the conversation with the validation error appended,
	// giving the model one chance to fix itself. The retry request must
	// carry the failed assistant turn so the endpoint can see what to fix.
	var retryHadAssistantTurn bool
	calls := 0
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var req chatRequest
		json.NewDecoder(r.Body).Decode(&req)
		i := calls
		calls++
		if i == 0 {
			json.NewEncoder(w).Encode(chatBody(`{"category":"not-a-category","importance":"high"}`))
			return
		}
		retryHadAssistantTurn = len(req.Messages) == 4 && req.Messages[2].Role == "assistant"
		json.NewEncoder(w).Encode(chatBody(`{"category":"important","importance":0.9}`))
	}))
	t.Cleanup(srv.Close)

	c := &Client{}
	res, _, _, err := c.Interpret(context.Background(), testConfig(srv.URL), "mock", "classify", testSchema(), []byte(`{}`))
	if err != nil {
		t.Fatalf("Interpret after corrected retry: %v", err)
	}
	if res["category"] != "important" {
		t.Errorf("result = %v, want corrected retry output", res)
	}
	if calls != 2 {
		t.Errorf("endpoint called %d times, want 2 (initial + corrected retry)", calls)
	}
	if !retryHadAssistantTurn {
		t.Error("retry request must include the invalid assistant turn for self-correction")
	}
}

func TestInterpretInvalidTwiceReturnsInvalidOutputError(t *testing.T) {
	// After the corrected retry also fails, the client must give up with
	// *InvalidOutputError — not keep retrying, and not a generic error,
	// since the runtime distinguishes invalid from errored decisions.
	srv, calls := contentServer(t, `{"category":"urgent","importance":0.9}`, `still not json`)
	c := &Client{}
	_, _, _, err := c.Interpret(context.Background(), testConfig(srv.URL), "mock", "classify", testSchema(), []byte(`{}`))
	var inv *InvalidOutputError
	if !errors.As(err, &inv) {
		t.Fatalf("err = %v, want *InvalidOutputError", err)
	}
	if *calls != 2 {
		t.Errorf("endpoint called %d times, want 2 (initial + one retry)", *calls)
	}
}

func TestInterpretResponseFormatFallback(t *testing.T) {
	// Some OpenAI-compatible endpoints reject the response_format
	// parameter with a 400. The client detects that specific failure and
	// retries the same request without response_format, falling back to
	// validation alone to enforce the schema.
	calls := 0
	var lastRequestHadFormat *bool
	hadFormat := false
	lastRequestHadFormat = &hadFormat
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var req chatRequest
		json.NewDecoder(r.Body).Decode(&req)
		calls++
		if req.ResponseFormat != nil {
			*lastRequestHadFormat = true
			w.WriteHeader(http.StatusBadRequest)
			fmt.Fprint(w, "response_format is not supported")
			return
		}
		*lastRequestHadFormat = false
		json.NewEncoder(w).Encode(chatBody(`{"category":"important","importance":0.85}`))
	}))
	t.Cleanup(srv.Close)

	c := &Client{}
	res, _, _, err := c.Interpret(context.Background(), testConfig(srv.URL), "mock", "classify", testSchema(), []byte(`{}`))
	if err != nil {
		t.Fatalf("Interpret with response_format-rejecting endpoint: %v", err)
	}
	if res["category"] != "important" {
		t.Errorf("result = %v, want fallback (no response_format) result", res)
	}
	if calls != 2 || *lastRequestHadFormat {
		t.Errorf("calls=%d lastHadFormat=%v, want 2 calls with final request omitting response_format", calls, *lastRequestHadFormat)
	}
}

// The budget counts wire requests, not calls to a helper that can retry.
// Mixed failures also prove that format fallback stays disabled and does
// not steal the one allowed schema correction from the remaining budget.
func TestInterpretSharedHTTPBudget(t *testing.T) {
	for _, tc := range []struct {
		name    string
		steps   []int // 0 = schema-invalid content; 200 = valid content
		wantErr bool
	}{
		{"fallback then outage", []int{400, 500, 500}, true},
		{"fallback then correction", []int{400, 0, 200}, false},
		{"fallback then invalid twice", []int{400, 0, 0}, true},
		{"outage then fallback", []int{500, 400, 200}, false},
		{"second 400 stops", []int{400, 400}, true},
		{"fallback at budget end", []int{500, 500, 400}, true},
		{"outage during correction", []int{0, 500, 200}, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			calls, rejectedFormat := 0, false
			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				var req chatRequest
				if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
					t.Error(err)
				}
				if rejectedFormat && req.ResponseFormat != nil {
					t.Error("rejected response_format was sent again")
				}
				calls++
				if calls > len(tc.steps) {
					t.Error("unexpected extra HTTP request")
					w.WriteHeader(500)
					return
				}
				code := tc.steps[calls-1]
				switch code {
				case 0:
					json.NewEncoder(w).Encode(chatBody(`{"category":"invalid","importance":0.9}`))
				case 200:
					json.NewEncoder(w).Encode(chatBody(`{"category":"important","importance":0.9}`))
				default:
					rejectedFormat = rejectedFormat || (code == 400 && req.ResponseFormat != nil)
					w.WriteHeader(code)
				}
			}))
			defer srv.Close()
			_, _, _, err := (&Client{}).Interpret(context.Background(), testConfig(srv.URL), "mock", "classify", testSchema(), []byte(`{}`))
			if (err != nil) != tc.wantErr || calls != len(tc.steps) || calls > maxAttempts {
				t.Fatalf("calls=%d err=%v, want %d calls, error=%v", calls, err, len(tc.steps), tc.wantErr)
			}
		})
	}
}

func TestInterpretTransportFailureAfterRetries(t *testing.T) {
	// A hard-down endpoint must surface a transport error (not
	// InvalidOutputError) after the bounded attempt count, with no
	// unbounded retry loop. Attempts are spaced by retryBackoff, so this
	// test costs two backoff periods.
	calls := 0
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls++
		w.WriteHeader(http.StatusInternalServerError)
		fmt.Fprint(w, "boom")
	}))
	t.Cleanup(srv.Close)

	c := &Client{}
	_, _, _, err := c.Interpret(context.Background(), testConfig(srv.URL), "mock", "classify", testSchema(), []byte(`{}`))
	if err == nil {
		t.Fatal("expected transport error, got nil")
	}
	var inv *InvalidOutputError
	if errors.As(err, &inv) {
		t.Fatalf("transport failure must not be reported as *InvalidOutputError, got %v", err)
	}
	if calls != maxAttempts {
		t.Errorf("endpoint called %d times, want %d (bounded attempts)", calls, maxAttempts)
	}
}

func TestInterpretNonRetryable4xxReturnsImmediately(t *testing.T) {
	// A 401 (bad key) or 404 (bad model name) will never succeed on retry;
	// burning the attempt budget on them just triples the noise per event.
	// Only network errors and 5xx consume the retry budget.
	calls := 0
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls++
		w.WriteHeader(http.StatusUnauthorized)
		fmt.Fprint(w, "bad key")
	}))
	t.Cleanup(srv.Close)

	c := &Client{}
	_, _, _, err := c.Interpret(context.Background(), testConfig(srv.URL), "mock", "classify", testSchema(), []byte(`{}`))
	if err == nil {
		t.Fatal("expected error for 401")
	}
	if calls != 1 {
		t.Errorf("endpoint called %d times, want 1 (non-retryable)", calls)
	}
}

func TestValidate(t *testing.T) {
	min, max := 0.0, 1.0
	schema := Schema{
		"category":   {Type: "string", Enum: []any{"important", "unimportant"}},
		"importance": {Type: "number", Minimum: &min, Maximum: &max},
		"flag":       {Type: "boolean"},
	}
	tests := []struct {
		name    string
		res     map[string]any
		wantErr string // empty = expect success
	}{
		{
			name: "valid",
			res:  map[string]any{"category": "important", "importance": 0.9, "flag": true},
		},
		{
			name:    "wrong type: string where number",
			res:     map[string]any{"category": "important", "importance": "0.9", "flag": true},
			wantErr: `field "importance": want number`,
		},
		{
			name:    "wrong type: number where string",
			res:     map[string]any{"category": 7, "importance": 0.9, "flag": true},
			wantErr: `field "category": want string`,
		},
		{
			name:    "number below minimum",
			res:     map[string]any{"category": "important", "importance": -0.1, "flag": true},
			wantErr: `field "importance": value -0.1 below minimum 0`,
		},
		{
			name:    "number above maximum",
			res:     map[string]any{"category": "important", "importance": 8.0, "flag": true},
			wantErr: `field "importance": value 8 above maximum 1`,
		},
		{
			name:    "wrong type: string where boolean",
			res:     map[string]any{"category": "important", "importance": 0.9, "flag": "true"},
			wantErr: `field "flag": want boolean`,
		},
		{
			name:    "missing field",
			res:     map[string]any{"importance": 0.9, "flag": true},
			wantErr: `missing field "category"`,
		},
		{
			name:    "enum violation",
			res:     map[string]any{"category": "urgent", "importance": 0.9, "flag": true},
			wantErr: `field "category": value urgent not in enum`,
		},
		{
			name:    "unexpected extra field",
			res:     map[string]any{"category": "important", "importance": 0.9, "flag": true, "extra": "nope"},
			wantErr: `unexpected field "extra"`,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := validate(tt.res, schema)
			if tt.wantErr == "" {
				if err != nil {
					t.Errorf("validate(%v) = %v, want nil", tt.res, err)
				}
				return
			}
			if err == nil || err.Error() != tt.wantErr {
				t.Errorf("validate(%v) = %v, want error %q", tt.res, err, tt.wantErr)
			}
		})
	}
}

func TestSchemaMapIncludesNumberBounds(t *testing.T) {
	importance := schemaMap(testSchema())["properties"].(map[string]any)["importance"].(map[string]any)
	if importance["minimum"] != 0.0 || importance["maximum"] != 1.0 {
		t.Errorf("importance schema = %v, want minimum=0 maximum=1", importance)
	}
}

package model

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync/atomic"
	"testing"
)

func testTypeSafeQuestions() Questions {
	return Questions{
		"category": {
			Type: "choice", Instructions: "Which category best describes `data.message`?",
			Criteria: map[string]any{"incident": "Broken now", "noise": "Routine noise"},
		},
		"requires_action": {
			Type: "noul", Instructions: "Does this require operator action?",
			Criteria: map[string]any{"true": "Action is needed", "false": "No action is needed"},
		},
		"severity": {
			Type: "score", Instructions: "How severe is this event?",
			Criteria: []any{"No impact", "Degraded with a workaround", "Blocking without a workaround"},
		},
	}
}

func typeSafeResponse() map[string]any {
	return map[string]any{
		"model": "jev-1.13.0",
		"answers": map[string]any{
			"category": map[string]any{
				"type": "choice", "choice": "incident", "confidence": 0.9,
				"probabilities": map[string]any{"incident": 0.95, "noise": 0.05},
			},
			"requires_action": map[string]any{"type": "noul", "noul": 0.88},
			"severity": map[string]any{
				"type": "score", "score": 1.7, "confidence": 0.6,
				"legend": map[string]any{
					"0": "No impact", "1": "Degraded with a workaround", "2": "Blocking without a workaround",
				},
				"probabilities": map[string]any{"0": 0.0, "1": 0.3, "2": 0.7},
			},
		},
		"usage": map[string]any{"input_tokens": 100, "output_tokens": 20},
	}
}

func TestInterpretTypeSafeHappyPath(t *testing.T) {
	const key = "test-typesafe-key"
	t.Setenv("TYPESAFE_TEST_KEY", key)
	var observed struct {
		State     map[string]any               `json:"state"`
		Model     string                       `json:"model"`
		Questions map[string]systemOneQuestion `json:"questions"`
	}
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/systemone" || r.Header.Get("Authorization") != "Bearer "+key {
			t.Errorf("request path/auth = %q/%q", r.URL.Path, r.Header.Get("Authorization"))
		}
		decoder := json.NewDecoder(r.Body)
		decoder.UseNumber()
		if err := decoder.Decode(&observed); err != nil {
			t.Error(err)
		}
		json.NewEncoder(w).Encode(typeSafeResponse())
	}))
	defer srv.Close()

	cfg := Config{Provider: "typesafe", BaseURL: srv.URL, APIKeyEnv: "TYPESAFE_TEST_KEY", Model: "jev-latest"}
	eventJSON := []byte(`{"data":{"message":"API down","id":9007199254740993}}`)
	result, _, modelID, err := (&Client{}).InterpretWithQuestions(context.Background(), cfg, "jev", "", nil, testTypeSafeQuestions(), eventJSON)
	if err != nil {
		t.Fatal(err)
	}
	if modelID != "jev-1.13.0" || observed.Model != "jev-latest" || len(observed.Questions) != 3 {
		t.Fatalf("model/result request = %q/%q questions=%d", modelID, observed.Model, len(observed.Questions))
	}
	data := observed.State["data"].(map[string]any)
	if data["id"] != json.Number("9007199254740993") {
		t.Fatalf("state numeric identity = %v, want exact JSON number", data["id"])
	}
	category := result["category"].(map[string]any)
	action := result["requires_action"].(map[string]any)
	if category["choice"] != "incident" || category["confidence"] != 0.9 || action["noul"] != 0.88 {
		t.Fatalf("validated result = %#v", result)
	}
}

func TestInterpretTypeSafeRejectsMalformedTypedAnswer(t *testing.T) {
	response := typeSafeResponse()
	response["answers"].(map[string]any)["category"].(map[string]any)["probabilities"] = map[string]any{"incident": 0.2, "noise": 0.2}
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		json.NewEncoder(w).Encode(response)
	}))
	defer srv.Close()

	cfg := Config{Provider: "typesafe", BaseURL: srv.URL, Model: "jev-latest"}
	_, _, _, err := (&Client{}).InterpretWithQuestions(context.Background(), cfg, "jev", "", nil, testTypeSafeQuestions(), []byte(`{}`))
	var invalid *InvalidOutputError
	if !errors.As(err, &invalid) || !strings.Contains(err.Error(), "sum") {
		t.Fatalf("err = %v, want invalid probability distribution", err)
	}
}

func TestInterpretTypeSafeRetriesRateLimitWithoutLeakingBody(t *testing.T) {
	var calls atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if calls.Add(1) < 3 {
			w.Header().Set("Retry-After", "0")
			w.WriteHeader(http.StatusTooManyRequests)
			fmt.Fprint(w, "private reflected request")
			return
		}
		json.NewEncoder(w).Encode(typeSafeResponse())
	}))
	defer srv.Close()

	cfg := Config{Provider: "typesafe", BaseURL: srv.URL, Model: "jev-latest"}
	result, _, _, err := (&Client{}).InterpretWithQuestions(context.Background(), cfg, "jev", "", nil, testTypeSafeQuestions(), []byte(`{}`))
	if err != nil || calls.Load() != 3 || result["category"] == nil {
		t.Fatalf("calls=%d result=%v err=%v", calls.Load(), result, err)
	}
}

func TestValidateQuestions(t *testing.T) {
	for _, tc := range []struct {
		name      string
		questions Questions
		wantErr   bool
	}{
		{"valid", testTypeSafeQuestions(), false},
		{"empty", nil, true},
		{"dot in id", Questions{"bad.id": {Type: "noul", Instructions: "Is it bad?"}}, true},
		{"choice needs options", Questions{"category": {Type: "choice", Instructions: "Which?", Criteria: map[string]any{"only": "one"}}}, true},
		{"noul criteria complete", Questions{"action": {Type: "noul", Instructions: "Act?", Criteria: map[string]any{"true": "yes"}}}, true},
		{"score needs levels", Questions{"severity": {Type: "score", Instructions: "Severity?", Criteria: []any{"only one"}}}, true},
		{"unknown type", Questions{"x": {Type: "freeform", Instructions: "Write"}}, true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if err := ValidateQuestions(tc.questions); (err != nil) != tc.wantErr {
				t.Fatalf("ValidateQuestions() = %v, want error=%v", err, tc.wantErr)
			}
		})
	}
}

// These tests pin the config loader's contract: an invalid config must
// never validate, defaults must apply exactly where documented, and strict
// decoding must reject unknown keys rather than silently ignore a typo
// like `api_keyenv:`. Config is the only place mrmr's behavior is
// described, so every way it can be wrong has to fail loudly here before
// the runtime ever trusts it.
package config

import (
	"math"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/heath0xff/mrmr/internal/event"
	"github.com/heath0xff/mrmr/internal/filter"
	"github.com/heath0xff/mrmr/internal/model"
	"github.com/heath0xff/mrmr/internal/policy"
)

// validConfig is the smallest configuration Validate accepts. Every error
// case mutates exactly one field so a failure points at the rule under
// test, not at a broken fixture.
func validConfig() *Config {
	return &Config{
		Models: map[string]model.Config{
			"m": {Provider: "openai-compatible", BaseURL: "http://localhost:1/v1", Model: "mock"},
		},
		Filter: filter.List{{Field: "source", Op: filter.OpNeq, Value: "noise-bot"}},
		Interpret: Interpret{
			Model:  "m",
			Prompt: "classify this event",
			Schema: model.Schema{
				"category":   {Type: "string"},
				"importance": {Type: "number"},
			},
		},
		Policy: policy.Policy{
			Rules: []policy.Rule{{
				If:   map[string]any{"result.importance": "> 0.8"},
				Then: policy.Then{Notify: &policy.Notify{Via: "stdout"}},
			}},
			Default: policy.Then{Ignore: true},
		},
		Agents: map[string]Agent{"triage": {Endpoint: "http://localhost:9000/tasks"}},
	}
}

func TestValidateErrors(t *testing.T) {
	tests := []struct {
		name   string
		mutate func(*Config)
		want   string // substring of the expected error
	}{
		{
			name:   "missing interpret.model",
			mutate: func(c *Config) { c.Interpret.Model = "" },
			want:   "interpret.model is required",
		},
		{
			name:   "interpret.model not defined in models",
			mutate: func(c *Config) { c.Interpret.Model = "nope" },
			want:   `interpret.model "nope" not defined in models`,
		},
		{
			name: "unsupported provider",
			mutate: func(c *Config) {
				m := c.Models["m"]
				m.Provider = "anthropic"
				c.Models["m"] = m
			},
			want: `unsupported provider "anthropic"`,
		},
		{
			name: "missing base_url",
			mutate: func(c *Config) {
				m := c.Models["m"]
				m.BaseURL = ""
				c.Models["m"] = m
			},
			want: "base_url is required",
		},
		{
			name:   "missing prompt",
			mutate: func(c *Config) { c.Interpret.Prompt = "" },
			want:   "interpret.prompt is required",
		},
		{
			name:   "empty schema",
			mutate: func(c *Config) { c.Interpret.Schema = nil },
			want:   "interpret.schema is required",
		},
		{
			name:   "schema field with unsupported type",
			mutate: func(c *Config) { c.Interpret.Schema["category"] = model.Field{Type: "array"} },
			want:   `schema field "category": unsupported type "array"`,
		},
		{
			name: "bounds on non-number field",
			mutate: func(c *Config) {
				min := 0.0
				c.Interpret.Schema["category"] = model.Field{Type: "string", Minimum: &min}
			},
			want: `schema field "category": minimum/maximum require type number`,
		},
		{
			name: "non-finite bound",
			mutate: func(c *Config) {
				min := math.NaN()
				c.Interpret.Schema["importance"] = model.Field{Type: "number", Minimum: &min}
			},
			want: `schema field "importance": minimum/maximum must be finite`,
		},
		{
			name: "minimum exceeds maximum",
			mutate: func(c *Config) {
				min, max := 2.0, 1.0
				c.Interpret.Schema["importance"] = model.Field{Type: "number", Minimum: &min, Maximum: &max}
			},
			want: `schema field "importance": minimum must not exceed maximum`,
		},
		{
			name:   "policy rule with empty if",
			mutate: func(c *Config) { c.Policy.Rules[0].If = nil },
			want:   "policy rule 1: empty if",
		},
		{
			name: "rule with unsupported notify.via",
			mutate: func(c *Config) {
				c.Policy.Rules[0].Then = policy.Then{Notify: &policy.Notify{Via: "email"}}
			},
			want: `notify.via "email" not supported`,
		},
		{
			name: "default with unsupported notify.via",
			mutate: func(c *Config) {
				c.Policy.Default = policy.Then{Notify: &policy.Notify{Via: "sms"}}
			},
			want: `default: notify.via "sms" not supported`,
		},
		{
			name: "rule with neither outcome nor shadow",
			mutate: func(c *Config) {
				c.Policy.Rules[0].Then = policy.Then{}
			},
			want: "policy rule 1: must set notify, action, delegate, ignore: true, or shadow: true",
		},
		{
			name: "rule with both notify and ignore",
			mutate: func(c *Config) {
				c.Policy.Rules[0].Then = policy.Then{Notify: &policy.Notify{Via: "stdout"}, Ignore: true}
			},
			want: "policy rule 1: set at most one of notify, action, delegate, ignore",
		},
		{
			name: "rule with unsupported action type",
			mutate: func(c *Config) {
				c.Policy.Rules[0].Then = policy.Then{Action: &policy.Action{Type: "exec", URL: "http://x"}}
			},
			want: `policy rule 1: action.type "exec" not supported`,
		},
		{
			name: "rule with http action and no url",
			mutate: func(c *Config) {
				c.Policy.Rules[0].Then = policy.Then{Action: &policy.Action{Type: "http"}}
			},
			want: "policy rule 1: action.url is required for type http",
		},
		{
			name: "rule with emit action and no event_type",
			mutate: func(c *Config) {
				c.Policy.Rules[0].Then = policy.Then{Action: &policy.Action{Type: "emit"}}
			},
			want: "policy rule 1: action.event_type is required for type emit",
		},
		{
			name: "rule delegating to an unknown agent",
			mutate: func(c *Config) {
				c.Policy.Rules[0].Then = policy.Then{Delegate: &policy.Delegate{Agent: "nope"}}
			},
			want: `policy rule 1: delegate.agent "nope" not defined in agents`,
		},
		{
			name: "agent without endpoint",
			mutate: func(c *Config) {
				c.Agents["triage"] = Agent{}
			},
			want: `config: agent "triage": endpoint is required`,
		},
		{
			name: "default with both notify and ignore",
			mutate: func(c *Config) {
				c.Policy.Default = policy.Then{Notify: &policy.Notify{Via: "stdout"}, Ignore: true}
			},
			want: "default: set at most one of notify, action, delegate, ignore",
		},
		{
			name: "default with neither outcome nor shadow",
			mutate: func(c *Config) {
				c.Policy.Default = policy.Then{}
			},
			want: "default: must set notify, action, delegate, ignore: true, or shadow: true",
		},
		{
			name:   "filter with unknown op",
			mutate: func(c *Config) { c.Filter[0].Op = "lt" },
			want:   `op "lt" not supported`,
		},
		{
			name:   "filter with unknown field root",
			mutate: func(c *Config) { c.Filter[0].Field = "foo.bar" },
			want:   `unknown root "foo"`,
		},
		{
			name:   "filter with bare data root",
			mutate: func(c *Config) { c.Filter[0].Field = "data" },
			want:   "data requires a sub-path",
		},
		{
			name:   "filter with sub-path under scalar root",
			mutate: func(c *Config) { c.Filter[0].Field = "type.x" },
			want:   "type has no sub-paths",
		},
		{
			name:   "filter with missing value",
			mutate: func(c *Config) { c.Filter[0].Value = nil },
			want:   "value is required",
		},
		{
			name:   "filter with empty field",
			mutate: func(c *Config) { c.Filter[0].Field = "" },
			want:   "field is required",
		},
		{
			name:   "filter with double event prefix",
			mutate: func(c *Config) { c.Filter[0].Field = "event.event.data.author" },
			want:   `unknown root "event"`,
		},
		{
			name:   "filter with list value",
			mutate: func(c *Config) { c.Filter[0].Value = []any{"a", "b"} },
			want:   "value must be a string, number, or boolean",
		},
		{
			name:   "filter with map value",
			mutate: func(c *Config) { c.Filter[0].Value = map[string]any{"a": "b"} },
			want:   "value must be a string, number, or boolean",
		},
		{
			name:   "filter with NaN value",
			mutate: func(c *Config) { c.Filter[0].Value = math.NaN() },
			want:   "value must be a string, number, or boolean",
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			c := validConfig()
			tt.mutate(c)
			err := c.Validate()
			if err == nil {
				t.Fatal("Validate() = nil, want error")
			}
			if !strings.Contains(err.Error(), tt.want) {
				t.Errorf("Validate() error = %q, want containing %q", err.Error(), tt.want)
			}
		})
	}
}

// TestValidateAcceptsBothFieldPathForms pins the two documented
// spellings of a filter field: IMPLEMENTATION.md section 3 uses
// data.author and the flow example uses event.data.author. Both must
// validate, or a documented example fails strict config validation.
func TestValidateAcceptsBothFieldPathForms(t *testing.T) {
	for _, field := range []string{"data.author", "event.data.author"} {
		c := validConfig()
		c.Filter = filter.List{{Field: field, Op: filter.OpNeq, Value: "x"}}
		if err := c.Validate(); err != nil {
			t.Fatalf("Validate() for %q = %v, want nil", field, err)
		}
	}
}

// TestExampleConfigQuickstartEventPassesFilters pins the quickstart
// contract: the README event has no data.author, and the fail-closed
// missing-field rule would stop it before interpretation if the
// shipped example filtered on an optional field. The example filters
// on a required root instead, so the quickstart must pass.
func TestExampleConfigQuickstartEventPassesFilters(t *testing.T) {
	cfg, err := Load(filepath.Join("..", "..", "mrmr.example.yaml"))
	if err != nil {
		t.Fatalf("Load example config: %v", err)
	}
	if len(cfg.Filter) == 0 {
		t.Fatal("example config has no filter: nothing to check")
	}
	e := event.Event{
		Type:   "test.message",
		Source: "curl",
		Data:   map[string]any{"message": "The production API has returned 500 errors for five minutes."},
	}
	if ok, reason := cfg.Filter.Evaluate(e); !ok {
		t.Fatalf("quickstart event fails the example filters: %s", reason)
	}
}

