func TestLoadTypeSafeConfig(t *testing.T) {
	path := writeConfig(t, `
models:
  jev:
    provider: typesafe
    base_url: https://api.typesafe.ai/v1
    api_key_env: TYPESAFE_API_KEY
    model: jev-1.13.0
interpret:
  model: jev
  questions:
    category:
      type: choice
      instructions: Which category best describes this event?
      criteria:
        incident: Something is broken now.
        noise: Routine activity.
    requires_action:
      type: noul
      instructions: Does this event require operator action?
      criteria:
        true: Action is needed.
        false: No action is needed.
    severity:
      type: score
      instructions: How severe is this event?
      criteria: [No impact, Degraded with a workaround, Blocking]
policy:
  - if:
      result.category.choice: incident
      result.category.confidence: ">= 0.8"
      result.requires_action.noul: ">= 0.8"
    then:
      notify:
        via: stdout
default:
  ignore: true
`)
	cfg, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	if cfg.Models["jev"].Provider != "typesafe" || len(cfg.Interpret.Questions) != 3 {
		t.Fatalf("loaded TypeSafe config = %+v", cfg)
	}
	if _, err := Load(filepath.Join("..", "..", "recipes", "homelab-journal", "mrmr.typesafe.example.yaml")); err != nil {
		t.Fatalf("load TypeSafe journal recipe: %v", err)
	}
	// Local d1 uses the same wire contract; a new serving recipe must not
	// accidentally require a new provider or relax configuration validation.
	if _, err := Load(filepath.Join("..", "..", "recipes", "local-d1", "mrmr.example.yaml")); err != nil {
		t.Fatalf("load local d1 recipe: %v", err)
	}
}

func TestValidateTypeSafeContract(t *testing.T) {
	base := func() *Config {
		c := validConfig()
		c.Models["m"] = model.Config{Provider: "typesafe", BaseURL: "https://api.typesafe.ai/v1", APIKeyEnv: "TYPESAFE_API_KEY", Model: "jev-1.13.0"}
		c.Interpret.Prompt, c.Interpret.Schema = "", nil
		c.Interpret.Questions = model.Questions{"category": {
			Type: "choice", Instructions: "Which category?",
			Criteria: map[string]any{"incident": "Broken", "noise": "Routine"},
		}}
		return c
	}
	if err := base().Validate(); err != nil {
		t.Fatalf("valid TypeSafe config: %v", err)
	}
	for _, tc := range []struct {
		name string
		edit func(*Config)
		want string
	}{
		{"missing key env", func(c *Config) { m := c.Models["m"]; m.APIKeyEnv = ""; c.Models["m"] = m }, "api_key_env is required"},
		{"prompt not allowed", func(c *Config) { c.Interpret.Prompt = "classify" }, "prompt/schema are not supported"},
		{"questions required", func(c *Config) { c.Interpret.Questions = nil }, "questions are required"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			c := base()
			tc.edit(c)
			if err := c.Validate(); err == nil || !strings.Contains(err.Error(), tc.want) {
				t.Fatalf("Validate() = %v, want containing %q", err, tc.want)
			}
		})
	}
}

// writeConfig persists YAML text to a temp file so every Load test gets an
// isolated file; no test writes inside the repo.
func writeConfig(t *testing.T, content string) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "mrmr.yaml")
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatalf("write config: %v", err)
	}
	return path
}

// minimalYAML omits server.addr and db.path so the defaults case and the
// error-case mutations all start from the same textual baseline.
const minimalYAML = `
models:
  m:
    provider: openai-compatible
    base_url: http://localhost:1/v1
    model: mock
interpret:
  model: m
  prompt: classify this event
  schema:
    category:
      type: string
policy:
  - if:
      result.category: incident
    then:
      notify:
        via: stdout
default:
  ignore: true
`

func TestLoadExampleConfig(t *testing.T) {
	// The shipped example must always load: it is the first thing a new
	// user runs, so any drift between it and Validate is a bug in one of them.
	cfg, err := Load("../../mrmr.example.yaml")
	if err != nil {
		t.Fatalf("Load(mrmr.example.yaml): %v", err)
	}
	if cfg.Server.Addr != ":4242" || cfg.DB.Path != "mrmr.db" {
		t.Errorf("example addr/db = %q/%q, want :4242/mrmr.db", cfg.Server.Addr, cfg.DB.Path)
	}
	if cfg.Interpret.Model != "fast-local" {
		t.Errorf("interpret.model = %q, want fast-local", cfg.Interpret.Model)
	}
	importance := cfg.Interpret.Schema["importance"]
	if importance.Minimum == nil || *importance.Minimum != 0 || importance.Maximum == nil || *importance.Maximum != 1 {
		t.Errorf("importance bounds = %v/%v, want 0/1", importance.Minimum, importance.Maximum)
	}

	// The shipped example must route an incident with confidence above the
	// configured threshold to notify, and an incident below it to default
	// ignore. Pin both sides of the boundary in the file users copy.
	if then, _ := cfg.Policy.Evaluate(map[string]any{"category": "incident", "confidence": 0.86}); then.Outcome() != "notify" {
		t.Errorf("incident 0.86 = %s, want notify above the threshold", then.Outcome())
	}
	if then, _ := cfg.Policy.Evaluate(map[string]any{"category": "incident", "confidence": 0.84}); then.Outcome() != "ignore" {
		t.Errorf("incident 0.84 = %s, want ignore below the threshold", then.Outcome())
	}
	if len(cfg.Agents) != 1 || cfg.Agents["triage"].Endpoint != "http://localhost:9000/tasks" {
		t.Errorf("example agents = %v, want one triage agent", cfg.Agents)
	}
}

func TestLoadDefaultsWhenOmitted(t *testing.T) {
	cfg, err := Load(writeConfig(t, minimalYAML))
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if cfg.Server.Addr != ":4242" {
		t.Errorf("server.addr = %q, want default :4242", cfg.Server.Addr)
	}
	if cfg.DB.Path != "mrmr.db" {
		t.Errorf("db.path = %q, want default mrmr.db", cfg.DB.Path)
	}
}

func TestLoadStrictUnknownKeys(t *testing.T) {
	tests := []struct {
		name string
		yaml string
		want string
	}{
		{
			// `api_keyenv` is the exact typo that would silently disable
			// auth header injection if unknown keys were ignored.
			name: "misspelled api_key_env in model",
			yaml: `
models:
  m:
    provider: openai-compatible
    base_url: http://localhost:1/v1
    model: mock
    api_keyenv: MRMR_MODEL_API_KEY
interpret:
  model: m
  prompt: p
  schema:
    category:
      type: string
policy: []
default:
  ignore: true
`,
			want: "api_keyenv",
		},
		{
			name: "stray top-level key",
			yaml: minimalYAML + "\nfoo: bar\n",
			want: "foo",
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := Load(writeConfig(t, tt.yaml))
			if err == nil {
				t.Fatalf("Load = nil, want error for unknown key")
			}
			if !strings.Contains(err.Error(), tt.want) {
				t.Errorf("Load error = %q, want it naming the unknown key %q", err.Error(), tt.want)
			}
		})
	}
}

