// TestValidateSourceErrors covers the source list: names are required and
// unique (they become Event.Source and cursor keys), the type is gated, and
// the interval floor protects the polled target.
func TestValidateSourceErrors(t *testing.T) {
	valid := Source{
		Name: "feed", Type: "http-poller", URL: "http://localhost/feed",
		Every: time.Minute, CursorField: "id", EventType: "feed.item.published",
	}
	tests := []struct {
		name   string
		mutate func(*Source)
		want   string
	}{
		{
			name:   "missing name",
			mutate: func(s *Source) { s.Name = "" },
			want:   "source 1: name is required",
		},
		{
			name:   "unsupported type",
			mutate: func(s *Source) { s.Type = "mcp-poller" },
			want:   `source "feed": type "mcp-poller" not supported`,
		},
		{
			name:   "missing url",
			mutate: func(s *Source) { s.URL = "" },
			want:   `source "feed": url is required`,
		},
		{
			name:   "interval below the floor",
			mutate: func(s *Source) { s.Every = 500 * time.Millisecond },
			want:   `source "feed": every must be at least 1s`,
		},
		{
			name:   "missing event_type",
			mutate: func(s *Source) { s.EventType = "" },
			want:   `source "feed": event_type is required`,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			c := validConfig()
			s := valid
			tt.mutate(&s)
			c.Sources = []Source{s}
			err := c.Validate()
			if err == nil {
				t.Fatal("Validate() = nil, want error")
			}
			if !strings.Contains(err.Error(), tt.want) {
				t.Errorf("Validate() error = %q, want containing %q", err.Error(), tt.want)
			}
		})
	}

	// Duplicate names fail even when both sources are otherwise valid.
	c := validConfig()
	c.Sources = []Source{valid, valid}
	if err := c.Validate(); err == nil || !strings.Contains(err.Error(), `duplicate name`) {
		t.Errorf("Validate() = %v, want duplicate name error", err)
	}
}

func TestJournalSourceConfig(t *testing.T) {
	// Load the actual user-facing recipe, not just a similar test fixture.
	recipe, err := Load(filepath.Join("..", "..", "recipes", "homelab-journal", "mrmr.example.yaml"))
	if err != nil {
		t.Fatal(err)
	}
	for _, rule := range recipe.Policy.Rules {
		if !rule.Then.Shadow {
			t.Fatal("journal dogfood recipe must not execute effects")
		}
	}
	if !recipe.Policy.Default.Ignore {
		t.Fatal("journal recipe default must ignore")
	}
	text := minimalYAML + `
sources:
  - name: services
    type: systemd-journal
    every: 30s
    units: [plexmediaserver.service, lfm25.service]
    priority: warning
    event_type: system.service.warning
`
	cfg, err := Load(writeConfig(t, text))
	if err != nil {
		t.Fatal(err)
	}
	if cfg.Sources[0].Every != 30*time.Second || len(cfg.Sources[0].Units) != 2 {
		t.Fatal("documented journal source did not load")
	}
	for _, tc := range []struct {
		name string
		edit func(*Source)
	}{
		{"no units", func(s *Source) { s.Units = nil }},
		{"wildcard", func(s *Source) { s.Units = []string{"*.service"} }},
		{"option", func(s *Source) { s.Units = []string{"--user.service"} }},
		{"path", func(s *Source) { s.Units = []string{"../foo.service"} }},
		{"duplicate", func(s *Source) { s.Units = []string{"foo.service", "foo.service"} }},
		{"missing priority", func(s *Source) { s.Priority = "" }},
		{"priority range", func(s *Source) { s.Priority = "info..debug" }},
		{"http fields", func(s *Source) { s.URL = "http://localhost/feed" }},
		{"no interval", func(s *Source) { s.Every = 0 }},
		{"no event type", func(s *Source) { s.EventType = "" }},
		{"journal fields on HTTP", func(s *Source) { s.Type = "http-poller"; s.URL = "http://localhost/feed" }},
	} {
		t.Run(tc.name, func(t *testing.T) {
			c := *cfg
			c.Sources = []Source{cfg.Sources[0]}
			tc.edit(&c.Sources[0])
			if err := c.Validate(); err == nil {
				t.Fatal("want invalid source error")
			}
		})
	}
}

// TestLoadSourceYAML pins the wire format, including the duration string
// parsing ("every: 2m"), so the documented example keeps loading.
func TestLoadSourceYAML(t *testing.T) {
	yamlText := minimalYAML + `
sources:
  - name: blog
    type: http-poller
    url: "http://localhost/feed.json?after={{ .cursor }}"
    every: 2m
    item_path: items
    cursor_field: id
    subject_field: title
    event_type: rss.item.published
`
	path := writeConfig(t, yamlText)
	cfg, err := Load(path)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if len(cfg.Sources) != 1 {
		t.Fatalf("sources = %d, want 1", len(cfg.Sources))
	}
	s := cfg.Sources[0]
	if s.Name != "blog" || s.Every != 2*time.Minute || s.ItemPath != "items" ||
		s.CursorField != "id" || s.SubjectField != "title" || s.EventType != "rss.item.published" {
		t.Errorf("source = %+v, want the documented example", s)
	}
}

package storage

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"github.com/heath0xff/mrmr/internal/event"
)

// LabelEvent records the human judgment for an event. Relabeling replaces the
// prior judgment so the export always contains one current answer per event.
func (d *DB) LabelEvent(eventID, category string, requiresAction bool, expectedOutcome string) (*EventLabel, error) {
	category = strings.TrimSpace(category)
	if category == "" {
		return nil, fmt.Errorf("category is required")
	}
	if expectedOutcome != "ignore" && expectedOutcome != "notify" {
		return nil, fmt.Errorf("expected outcome must be ignore or notify")
	}
	var exists int
	if err := d.QueryRow(`SELECT 1 FROM events WHERE id = ?`, eventID).Scan(&exists); err != nil {
		if err == sql.ErrNoRows {
			return nil, fmt.Errorf("event %s not found", eventID)
		}
		return nil, fmt.Errorf("find event %s: %w", eventID, err)
	}

	label := &EventLabel{
		EventID:         eventID,
		Category:        category,
		RequiresAction:  requiresAction,
		ExpectedOutcome: expectedOutcome,
		LabeledAt:       time.Now().UTC(),
	}
	_, err := d.Exec(`INSERT INTO event_labels (event_id, category, requires_action, expected_outcome, labeled_at)
		VALUES (?, ?, ?, ?, ?)
		ON CONFLICT(event_id) DO UPDATE SET
			category = excluded.category,
			requires_action = excluded.requires_action,
			expected_outcome = excluded.expected_outcome,
			labeled_at = excluded.labeled_at`,
		label.EventID, label.Category, label.RequiresAction, label.ExpectedOutcome, label.LabeledAt.Format(time.RFC3339Nano))
	if err != nil {
		return nil, fmt.Errorf("label event %s: %w", eventID, err)
	}
	return label, nil
}

// ListEvents returns recent events with their latest decision, execution, and
// optional human label. It is the backing query for the local review queue.
func (d *DB) ListEvents(limit int, unlabeledOnly bool) ([]ReviewEvent, error) {
	if limit <= 0 {
		return nil, fmt.Errorf("limit must be positive")
	}
	where := ""
	if unlabeledOnly {
		where = "WHERE l.event_id IS NULL"
	}
	rows, err := d.Query(`
SELECT e.id, e.type, e.source, e.subject, e.event_time, e.data, e.metadata,
       d.id, d.interpreter, d.model, d.status, d.result, d.latency_ms, d.error,
       x.outcome,
       l.category, l.requires_action, l.expected_outcome, l.labeled_at
FROM events e
LEFT JOIN decisions d ON d.id = (
	SELECT id FROM decisions WHERE event_id = e.id ORDER BY created_at DESC LIMIT 1
)
LEFT JOIN executions x ON x.id = (
	SELECT id FROM executions WHERE event_id = e.id ORDER BY created_at DESC LIMIT 1
)
LEFT JOIN event_labels l ON l.event_id = e.id
`+where+`
ORDER BY e.ingest_time DESC
LIMIT ?`, limit)
	if err != nil {
		return nil, fmt.Errorf("list events: %w", err)
	}
	defer rows.Close()

	var events []ReviewEvent
	for rows.Next() {
		var (
			id, typ, source, subject, eventTime string
			dataJSON, metadataJSON              sql.NullString
			decisionID, interpreter, modelName  sql.NullString
			decisionStatus, resultJSON          sql.NullString
			latency                             sql.NullInt64
			decisionErr, outcome                sql.NullString
			category, expectedOutcome           sql.NullString
			requiresAction                      sql.NullInt64
			labeledAt                           sql.NullString
		)
		if err := rows.Scan(
			&id, &typ, &source, &subject, &eventTime, &dataJSON, &metadataJSON,
			&decisionID, &interpreter, &modelName, &decisionStatus, &resultJSON, &latency, &decisionErr,
			&outcome, &category, &requiresAction, &expectedOutcome, &labeledAt,
		); err != nil {
			return nil, fmt.Errorf("scan event: %w", err)
		}
		e, err := decodeStoredEvent(id, typ, source, subject, eventTime, dataJSON, metadataJSON)
		if err != nil {
			return nil, err
		}
		review := ReviewEvent{Event: e, Outcome: outcome.String}
		if decisionID.Valid {
			dec := &event.Decision{
				ID: decisionID.String, EventID: id, Interpreter: interpreter.String,
				Model: modelName.String, Status: decisionStatus.String,
				LatencyMs: latency.Int64, Error: decisionErr.String,
			}
			if resultJSON.Valid && resultJSON.String != "null" {
				if err := json.Unmarshal([]byte(resultJSON.String), &dec.Result); err != nil {
					return nil, fmt.Errorf("decode decision %s result: %w", dec.ID, err)
				}
			}
			review.Decision = dec
		}
		if category.Valid {
			at, err := time.Parse(time.RFC3339Nano, labeledAt.String)
			if err != nil {
				return nil, fmt.Errorf("decode label for event %s: %w", id, err)
			}
			review.Label = &EventLabel{
				EventID: id, Category: category.String, RequiresAction: requiresAction.Int64 != 0,
				ExpectedOutcome: expectedOutcome.String, LabeledAt: at,
			}
		}
		events = append(events, review)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("list events: %w", err)
	}
	return events, nil
}

// LabeledEvents returns every labeled event in stable ingestion order for
// deterministic JSONL exports.
func (d *DB) LabeledEvents() ([]LabeledEvent, error) {
	rows, err := d.Query(`
SELECT e.id, e.type, e.source, e.subject, e.event_time, e.data, e.metadata,
       l.category, l.requires_action, l.expected_outcome, l.labeled_at
FROM event_labels l
JOIN events e ON e.id = l.event_id
ORDER BY e.ingest_time, e.id`)
	if err != nil {
		return nil, fmt.Errorf("list labeled events: %w", err)
	}
	defer rows.Close()

	var events []LabeledEvent
	for rows.Next() {
		var (
			id, typ, source, subject, eventTime string
			dataJSON, metadataJSON              sql.NullString
			category, expectedOutcome           string
			requiresAction                      bool
			labeledAt                           string
		)
		if err := rows.Scan(&id, &typ, &source, &subject, &eventTime, &dataJSON, &metadataJSON,
			&category, &requiresAction, &expectedOutcome, &labeledAt); err != nil {
			return nil, fmt.Errorf("scan labeled event: %w", err)
		}
		e, err := decodeStoredEvent(id, typ, source, subject, eventTime, dataJSON, metadataJSON)
		if err != nil {
			return nil, err
		}
		at, err := time.Parse(time.RFC3339Nano, labeledAt)
		if err != nil {
			return nil, fmt.Errorf("decode label for event %s: %w", id, err)
		}
		events = append(events, LabeledEvent{Event: e, Label: EventLabel{
			EventID: id, Category: category, RequiresAction: requiresAction,
			ExpectedOutcome: expectedOutcome, LabeledAt: at,
		}})
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("list labeled events: %w", err)
	}
	return events, nil
}

func decodeStoredEvent(id, typ, source, subject, eventTime string, dataJSON, metadataJSON sql.NullString) (event.Event, error) {
	at, err := time.Parse(time.RFC3339Nano, eventTime)
	if err != nil {
		return event.Event{}, fmt.Errorf("decode event %s time: %w", id, err)
	}
	e := event.Event{ID: id, Type: typ, Source: source, Subject: subject, Timestamp: at}
	// Inspection and dataset export must not re-round identities that
	// ingestion preserved. Decisions keep their separate schema decoding.
	if dataJSON.Valid && dataJSON.String != "null" {
		dec := json.NewDecoder(strings.NewReader(dataJSON.String))
		dec.UseNumber()
		if err := dec.Decode(&e.Data); err != nil {
			return event.Event{}, fmt.Errorf("decode event %s data: %w", id, err)
		}
	}
	if metadataJSON.Valid && metadataJSON.String != "null" {
		dec := json.NewDecoder(strings.NewReader(metadataJSON.String))
		dec.UseNumber()
		if err := dec.Decode(&e.Metadata); err != nil {
			return event.Event{}, fmt.Errorf("decode event %s metadata: %w", id, err)
		}
	}
	return e, nil
}

// Command mrmr is the single binary for the mrmr runtime. `run` loads a YAML
// config, opens SQLite, and serves POST /api/events. Each request is
// processed synchronously: the event is persisted; duplicates short-circuit
// there with a "duplicate" marker; and the rest run deterministic filters,
// model interpretation, policy, and outcome in order, with filter-excluded
// events stopping before the model call. The HTTP response is the trace of
// everything that happened. Synchronous processing is the point: it makes
// the runtime's behavior explainable end to end and keeps the invariants
// simple (no queue, no worker goroutines, no lost requests) at the cost of
// latency, which is fine for ambient event volumes.
package main

import (
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"os/signal"
	"sync"
	"syscall"
	"time"

	"github.com/heath0xff/mrmr/internal/config"
	"github.com/heath0xff/mrmr/internal/event"
	"github.com/heath0xff/mrmr/internal/model"
	"github.com/heath0xff/mrmr/internal/runtime"
	"github.com/heath0xff/mrmr/internal/source"
	"github.com/heath0xff/mrmr/internal/storage"
)

func main() {
	log.SetFlags(log.LstdFlags | log.LUTC)

	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "usage: mrmr <run|eval|events|label|dataset|inspect|auth> [options]")
		os.Exit(2)
	}

	switch os.Args[1] {
	case "auth":
		if err := authCommand(os.Args[2:]); err != nil {
			log.Fatal(err)
		}
	case "run":
		if err := run(os.Args[2:]); err != nil {
			log.Fatal(err)
		}
	case "eval":
		if err := eval(os.Args[2:]); err != nil {
			log.Fatal(err)
		}
	case "events":
		if err := events(os.Args[2:]); err != nil {
			log.Fatal(err)
		}
	case "label":
		if err := label(os.Args[2:]); err != nil {
			log.Fatal(err)
		}
	case "dataset":
		if err := dataset(os.Args[2:]); err != nil {
			log.Fatal(err)
		}
	case "inspect":
		if err := inspect(os.Args[2:]); err != nil {
			log.Fatal(err)
		}
	case "-h", "--help", "help":
		fmt.Println("usage: mrmr <run|eval|events|label|dataset|inspect|auth> [options]")
	default:
		log.Fatalf("unknown subcommand %q", os.Args[1])
	}
}

// run boots the server and blocks until SIGINT/SIGTERM. Shutdown is graceful
// because an in-flight event is mid-pipeline: killing it between the event
// persist and the decision persist would leave a half-processed event with
// no way to tell from outside whether anything was lost.
func run(args []string) error {
	fs := flag.NewFlagSet("mrmr run", flag.ContinueOnError)
	configPath := fs.String("config", "mrmr.yaml", "path to config file")
	if err := fs.Parse(args); err != nil {
		return err
	}

	cfg, err := config.Load(*configPath)
	if err != nil {
		return err
	}

	db, err := storage.Open(cfg.DB.Path)
	if err != nil {
		return err
	}
	defer db.Close()

	rt := &runtime.Runtime{
		DB:        db,
		Client:    &model.Client{},
		ModelCfg:  cfg.Models[cfg.Interpret.Model],
		ModelKey:  cfg.Interpret.Model,
		Prompt:    cfg.Interpret.Prompt,
		Schema:    cfg.Interpret.Schema,
		Questions: cfg.Interpret.Questions,
		Policy:    cfg.Policy,
		Filters:   cfg.Filter,
	}
	// Resolve delegation endpoints once at startup; policy rules reference
	// agents by name only.
	rt.AgentEndpoints = make(map[string]string, len(cfg.Agents))
	for name, a := range cfg.Agents {
		rt.AgentEndpoints[name] = a.Endpoint
	}

	mux := http.NewServeMux()
	mux.HandleFunc("POST /api/events", eventsHandler(rt))

	srv := &http.Server{Addr: cfg.Server.Addr, Handler: mux}

	// Cancel the context on SIGINT/SIGTERM so Shutdown has a deadline and a
	// second signal still hard-exits. Pollers share this context: shutdown
	// cancels in-flight fetches and stops the tick loops.
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	// Prepare every source before starting any: an inaccessible journal or
	// missing token must not leave earlier sources ingesting on failed boot.
	runners, err := prepareSources(ctx, cfg.Sources, db)
	if err != nil {
		return err
	}
	listener, err := net.Listen("tcp", cfg.Server.Addr)
	if err != nil {
		return fmt.Errorf("listen: %w", err)
	}
	defer listener.Close()
	defer srv.Close()

	// Every exit path cancels and joins sources before closing SQLite,
	// including a server failure. Each adapter bounds its own I/O lifetime.
	var sources sync.WaitGroup
	defer func() {
		stop()
		sources.Wait()
	}()
	for _, runSource := range runners {
		sources.Add(1)
		go func() {
			defer sources.Done()
			runSource(ctx, rt)
		}()
	}

	errCh := make(chan error, 1)
	go func() { errCh <- srv.Serve(listener) }()

	log.Printf("mrmr listening on %s (db: %s, model: %s, sources: %d)", cfg.Server.Addr, cfg.DB.Path, cfg.Interpret.Model, len(cfg.Sources))

	select {
	case err := <-errCh:
		return err
	case <-ctx.Done():
	}

	// Bound shutdown so a hung request can't wedge the process; the pipeline
	// itself also respects ctx via the request context.
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil {
		return fmt.Errorf("shutdown: %w", err)
	}
	return nil
}

// Method values keep the two real source adapters explicit without a plugin
// registry. Construction can check local prerequisites but never starts a
// polling goroutine; ownership transfers to run only after every check passes.
func prepareSources(ctx context.Context, configs []config.Source, db *storage.DB) ([]func(context.Context, *runtime.Runtime), error) {
	var runners []func(context.Context, *runtime.Runtime)
	for _, sc := range configs {
		switch sc.Type {
		case "http-poller":
			p, err := source.NewHTTPPoller(sc)
			if err != nil {
				return nil, err
			}
			runners = append(runners, p.Run)
		case "systemd-journal":
			j, err := source.NewJournal(ctx, sc, db)
			if err != nil {
				return nil, err
			}
			runners = append(runners, j.Run)
		default:
			return nil, fmt.Errorf("source %q: unknown type %q", sc.Name, sc.Type)
		}
	}
	return runners, nil
}

// eventsRequest is the wire shape for POST /api/events. Only type and source
// are required; data and metadata are opaque maps passed through to the event.
type eventsRequest struct {
	Type     string         `json:"type"`
	Source   string         `json:"source"`
	Subject  string         `json:"subject,omitempty"`
	Data     map[string]any `json:"data,omitempty"`
	Metadata map[string]any `json:"metadata,omitempty"`
}

// eventsHandler returns the POST /api/events handler. Ingest is
// synchronous: by the time the 200 goes out, the event's fate is final:
// a duplicate, a filter exclusion before any model call, or an executed
// policy outcome. Ingest errors are persistence
// failures and map to 500; everything the model does wrong is already
// captured in the decision and trace, not in the HTTP status.
func eventsHandler(rt *runtime.Runtime) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// This is the runtime's only external ingress, so bodies are bounded:
		// a normalized event is small, and one oversized POST must not be able
		// to eat memory. 1 MiB is generous headroom over any real event.
		r.Body = http.MaxBytesReader(w, r.Body, 1<<20)
		var req eventsRequest
		// IDs and payload numbers must remain exact before deduplication;
		// float64 aliases distinct integers above 2^53.
		dec := json.NewDecoder(r.Body)
		dec.UseNumber()
		if err := dec.Decode(&req); err != nil {
			writeError(w, http.StatusBadRequest, "malformed JSON body: "+err.Error())
			return
		}
		if req.Type == "" || req.Source == "" {
			writeError(w, http.StatusBadRequest, "both \"type\" and \"source\" are required")
			return
		}

		e := event.Event{
			ID:        event.NewID("evt_"),
			Type:      req.Type,
			Source:    req.Source,
			Subject:   req.Subject,
			Timestamp: time.Now().UTC(),
			Data:      req.Data,
			Metadata:  req.Metadata,
		}

		resp, err := rt.Ingest(r.Context(), e)
		if err != nil {
			// Persistence failed, which means the event's fate is unknown
			// to the caller; 500 (not 4xx) so clients may retry.
			log.Printf("ingest %s failed: %v", e.ID, err)
			writeError(w, http.StatusInternalServerError, "ingest failed")
			return
		}

		// One line per event so stdout doubles as a processing log. This is
		// the whole observability story for milestone 1: the response JSON
		// contains the decision and the full trace.
		b, err := json.Marshal(resp)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "encode response: "+err.Error())
			return
		}
		fmt.Println(string(b))

		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		w.Write(b)
	}
}

// writeError responds with the {"error": ...} envelope. Errors never carry
// internal detail beyond what the trace already exposes.
func writeError(w http.ResponseWriter, code int, msg string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	json.NewEncoder(w).Encode(map[string]string{"error": msg})
}

// Package source hosts source adapters: the code that watches the outside
// world and emits normalized Events. v0.1's only ingress was POST /api/events;
// HTTP polling and the Linux system-journal reader add pull-based ingestion.
// A source is deliberately dumb: it fetches, normalizes items into
// Events, and hands each one to the ordinary Ingest pipeline — it never
// interprets, filters, or routes.
//
// Concurrency contract: one goroutine per source, owned by Run, bounded by
// the context, exited when the context is canceled. Polls within one source
// are strictly serial, so cursor state needs no locking beyond SQLite's.
package source

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"
	"time"

	"github.com/heath0xff/mrmr/internal/config"
	"github.com/heath0xff/mrmr/internal/event"
	"github.com/heath0xff/mrmr/internal/runtime"
	"github.com/heath0xff/mrmr/internal/storage"
)

// HTTPPoller polls a JSON endpoint on an interval and ingests each record
// as an Event. Every fetched item is offered to Ingest and dedup drops what
// was already persisted. The cursor controls which records incremental APIs
// return next, so an incomplete batch must retain its old watermark: dedup
// can suppress repeats, but cannot recover a record the API no longer sends.
type HTTPPoller struct {
	cfg    config.Source
	urlTpl *template.Template
	client *http.Client
	// bearer is resolved once from the environment at construction; it is
	// never persisted, logged, or copied anywhere but the request header.
	bearer string
}

// NewHTTPPoller validates and prepares a poller. The bearer token is read
// from the environment once, here: it must exist at startup (fail loudly)
// and must never be persisted or logged.
func NewHTTPPoller(cfg config.Source) (*HTTPPoller, error) {
	tpl, err := template.New("url").Parse(cfg.URL)
	if err != nil {
		return nil, fmt.Errorf("source %s: bad url template: %w", cfg.Name, err)
	}
	bearer, err := bearerFromEnv(cfg.BearerTokenEnv)
	if err != nil {
		return nil, fmt.Errorf("source %s: %w", cfg.Name, err)
	}
	return &HTTPPoller{
		cfg:    cfg,
		urlTpl: tpl,
		// Outbound polls must be bounded: a hung target must not stall the
		// poll loop's single goroutine forever.
		client: &http.Client{Timeout: 15 * time.Second},
		bearer: bearer,
	}, nil
}

// Run polls until ctx is canceled. The first poll is immediate so a fresh
// config produces data without waiting one interval.
func (p *HTTPPoller) Run(ctx context.Context, rt *runtime.Runtime) {
	ticker := time.NewTicker(p.cfg.Every)
	defer ticker.Stop()

	p.poll(ctx, rt)
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			p.poll(ctx, rt)
		}
	}
}

// poll is one fetch-normalize-ingest cycle. Every error path is a log line,
// never a crash: a broken feed must not take down the runtime, and the next
// tick retries anyway.
func (p *HTTPPoller) poll(ctx context.Context, rt *runtime.Runtime) {
	// If the fetch itself is canceled by shutdown, nothing was ingested and
	// the cursor is unchanged — safe to abandon mid-flight.
	items, err := p.fetch(ctx, rt.DB)
	if err != nil {
		log.Printf("mrmr: poll %s: fetch failed: %v", p.cfg.Name, err)
		return
	}

	var ingested, dups, cursorAdvanced int
	complete := true
	newCursor := ""
	for i, item := range items {
		if ctx.Err() != nil {
			return // shutdown: remaining items wait for the next poll
		}
		obj, ok := item.(map[string]any)
		if !ok {
			complete = false
			log.Printf("mrmr: poll %s: item %d is not an object, skipped", p.cfg.Name, i)
			continue
		}
		e, err := p.normalize(obj)
		if err != nil {
			complete = false
			log.Printf("mrmr: poll %s: item %d: %v", p.cfg.Name, i, err)
			continue
		}
		resp, err := rt.Ingest(ctx, e)
		if err != nil {
			complete = false
			log.Printf("mrmr: poll %s: ingest %s failed: %v", p.cfg.Name, e.ID, err)
			continue
		}
		if c := cursorValue(obj, p.cfg.CursorField); c > newCursor {
			// ponytail: string max; cursor-based APIs must use lexically ordered IDs.
			newCursor = c
		}
		if resp.Duplicate {
			dups++
		} else {
			ingested++
		}
	}

	// There is no safe partial watermark for an unordered batch: even a
	// successful record can sort past a failed one. Keep ingesting valid
	// records, but retry the old window if any item failed or was malformed.
	// A permanently malformed item therefore holds the cursor until the
	// source is corrected. Check cancellation here too: the last Ingest can
	// record a canceled model call as ignore without returning an error.
	// This protects fetching, not recovery of already-persisted partial work.
	if complete && ctx.Err() == nil && newCursor != "" && newCursor != p.cursor(rt.DB) {
		if err := rt.DB.SetCursor(p.cfg.Name, newCursor); err != nil {
			log.Printf("mrmr: poll %s: persist cursor failed: %v", p.cfg.Name, err)
		} else {
			cursorAdvanced = 1
		}
	}
	log.Printf("mrmr: poll %s: %d items: %d new, %d duplicate, cursor=%s",
		p.cfg.Name, len(items), ingested, dups, map[bool]string{true: newCursor, false: "unchanged"}[cursorAdvanced == 1])
}

// fetch retrieves and extracts the item array. The cursor is substituted
// into the URL template when present so cursor-based APIs page correctly;
// plain feeds ignore it.
func (p *HTTPPoller) fetch(ctx context.Context, db *storage.DB) ([]any, error) {
	var urlBuf bytes.Buffer
	if err := p.urlTpl.Execute(&urlBuf, map[string]any{"cursor": p.cursor(db)}); err != nil {
		return nil, fmt.Errorf("render url: %w", err)
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, urlBuf.String(), nil)
	if err != nil {
		return nil, err
	}
	if p.bearer != "" {
		req.Header.Set("Authorization", "Bearer "+p.bearer)
	}
	resp, err := p.client.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	// Feeds are small; 4 MiB caps a hostile or misconfigured target.
	body, err := io.ReadAll(io.LimitReader(resp.Body, 4<<20))
	if err != nil {
		return nil, err
	}
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		return nil, fmt.Errorf("status %d", resp.StatusCode)
	}

	var doc any
	// Preserve numeric cursor identities and payloads before deduplication.
	// Adjacent 64-bit IDs can collapse to the same float64 otherwise.
	dec := json.NewDecoder(bytes.NewReader(body))
	dec.UseNumber()
	if err := dec.Decode(&doc); err != nil {
		return nil, fmt.Errorf("decode JSON: %w", err)
	}
	if err := dec.Decode(new(any)); err != io.EOF {
		return nil, fmt.Errorf("decode JSON: expected one value")
	}
	items := doc
	if p.cfg.ItemPath != "" {
		items = doc
		for _, part := range strings.Split(p.cfg.ItemPath, ".") {
			m, ok := items.(map[string]any)
			if !ok {
				return nil, fmt.Errorf("item_path %q: %s is not an object", p.cfg.ItemPath, part)
			}
			items = m[part]
		}
	}
	list, ok := items.([]any)
	if !ok {
		if items == nil {
			return nil, nil // absent path is an empty poll, not an error
		}
		return nil, fmt.Errorf("item_path %q did not resolve to an array", p.cfg.ItemPath)
	}
	return list, nil
}

// normalize turns one fetched record into an Event. The whole record becomes
// data — the core makes no assumptions about source payloads, and dropping
// fields here would silently erase exactly the context the interpreter needs.
// The cursor field doubles as source_event_id, which is what makes dedup work.
func (p *HTTPPoller) normalize(item map[string]any) (event.Event, error) {
	e := event.Event{
		ID:        event.NewID("evt_"),
		Type:      p.cfg.EventType,
		Source:    p.cfg.Name,
		Timestamp: time.Now().UTC(),
		Data:      item,
	}
	if p.cfg.SubjectField != "" {
		if v, ok := item[p.cfg.SubjectField]; ok {
			e.Subject = fmt.Sprint(v)
		}
	}
	if p.cfg.TimestampField != "" {
		if v, ok := item[p.cfg.TimestampField].(string); ok {
			if ts, perr := time.Parse(time.RFC3339, v); perr == nil {
				e.Timestamp = ts.UTC()
			}
			// Unparseable timestamps keep "now": a wrong-but-present event
			// beats a dropped one for ambient feeds.
		}
	}
	if p.cfg.CursorField != "" {
		if c := cursorValue(item, p.cfg.CursorField); c != "" {
			e.Metadata = map[string]any{"source_event_id": c}
		} else {
			return e, fmt.Errorf("cursor_field %q missing or invalid; item cannot be deduplicated", p.cfg.CursorField)
		}
	}
	return e, nil
}

func cursorValue(item map[string]any, field string) string {
	if field == "" {
		return ""
	}
	// Share the storage identity rule: null/objects/arrays must not turn
	// into synthetic IDs that collapse unrelated records or advance cursors.
	return event.SourceEventID(item[field])
}

// cursor reads the persisted watermark. An unknown source is a fresh poller:
// empty cursor, and the URL template renders without one.
func (p *HTTPPoller) cursor(db *storage.DB) string {
	c, err := db.Cursor(p.cfg.Name)
	if err != nil {
		log.Printf("mrmr: poll %s: read cursor: %v", p.cfg.Name, err)
	}
	return c
}

// bearerFromEnv resolves the bearer_token_env reference at startup.
func bearerFromEnv(name string) (string, error) {
	if name == "" {
		return "", nil
	}
	v, ok := os.LookupEnv(name)
	if !ok || v == "" {
		return "", fmt.Errorf("env %s (bearer_token_env) is not set", name)
	}
	return v, nil
}

package source

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"os"
	"os/exec"
	"runtime"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"

	"github.com/heath0xff/mrmr/internal/config"
	"github.com/heath0xff/mrmr/internal/event"
	mruntime "github.com/heath0xff/mrmr/internal/runtime"
	"github.com/heath0xff/mrmr/internal/storage"
)

const journalBatchSize = 100

// Journal reads the local system journal only. It owns no background process:
// each bounded journalctl call is reaped before interpretation begins. Run's
// caller owns the single polling goroutine and cancels it on every exit path.
// No command, arguments, permissions, or cursor ever come from a model.
type Journal struct {
	cfg    config.Source
	path   string
	bootID string
}

// NewJournal checks platform, executable, journal access, and resume position
// before the daemon activates ANY sources. Reading the unfiltered system tail
// distinguishes an empty unit selection from an inaccessible journal. We do
// not suppress journalctl's permission warnings, even on a successful exit.
func NewJournal(ctx context.Context, cfg config.Source, db *storage.DB) (*Journal, error) {
	if runtime.GOOS != "linux" {
		return nil, fmt.Errorf("source %q: systemd-journal requires Linux", cfg.Name)
	}
	path, err := exec.LookPath("journalctl")
	if err != nil {
		return nil, fmt.Errorf("source %q: journalctl is required; install the systemd journal tools", cfg.Name)
	}
	boot, err := os.ReadFile("/proc/sys/kernel/random/boot_id")
	if err != nil {
		return nil, fmt.Errorf("source %q: read Linux boot identity: %w", cfg.Name, err)
	}
	j := &Journal{cfg: cfg, path: path, bootID: strings.ReplaceAll(strings.TrimSpace(string(boot)), "-", "")}
	if err := j.prepare(ctx, db); err != nil {
		return nil, fmt.Errorf("source %q: %w", cfg.Name, err)
	}
	return j, nil
}

func (j *Journal) prepare(ctx context.Context, db *storage.DB) error {
	cursor, err := db.Cursor(j.cfg.Name)
	if err != nil {
		return err
	}
	if cursor != "" {
		_, err := j.batch(ctx, cursor)
		return err
	}
	// First activation starts at the current global tail, not the latest
	// matching warning: an old warning must not turn into a fresh incident.
	// Only the cursor is requested; historical message text is unnecessary.
	records, err := j.read(ctx, "__CURSOR", "--lines=1")
	if err != nil {
		return err
	}
	if len(records) != 1 {
		return fmt.Errorf("no readable system journal entries; verify journald is running and this account has system journal read access")
	}
	cursor, err = records[0].cursor()
	if err != nil {
		return err
	}
	// Probe forward-scan support on fresh installations too, not only when
	// an existing checkpoint happens to exercise --lines=+N during startup.
	if _, err := j.batch(ctx, cursor); err != nil {
		return err
	}
	if ctx.Err() != nil {
		return ctx.Err()
	}
	return db.SetCursor(j.cfg.Name, cursor)
}

func (j *Journal) Run(ctx context.Context, rt *mruntime.Runtime) {
	ticker := time.NewTicker(j.cfg.Every)
	defer ticker.Stop()
	for {
		if ctx.Err() != nil {
			return
		}
		if err := j.poll(ctx, rt); err != nil && ctx.Err() == nil {
			log.Printf("mrmr: journal %s: %v", j.cfg.Name, err)
		}
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
	}
}

func (j *Journal) poll(ctx context.Context, rt *mruntime.Runtime) error {
	cursor, err := rt.DB.Cursor(j.cfg.Name)
	if err != nil {
		return err
	}
	if cursor == "" {
		return fmt.Errorf("journal checkpoint missing; restart to establish a new tail")
	}
	records, err := j.batch(ctx, cursor)
	if err != nil {
		return err
	}
	for _, record := range records {
		if ctx.Err() != nil {
			return ctx.Err()
		}
		cursor, err = record.cursor()
		if err != nil {
			return err
		}
		e, selected, err := j.normalize(record, cursor)
		if err != nil {
			return err
		}
		if selected {
			if _, err := rt.Ingest(ctx, e); err != nil {
				// Preserve the old batch checkpoint. Already stored events
				// dedup on the next poll; runtime partial-work recovery is a
				// separate limitation, not something this cursor can repair.
				return fmt.Errorf("ingest journal event: %w", err)
			}
		}
	}
	if ctx.Err() != nil {
		return ctx.Err()
	}
	if len(records) == 0 {
		return nil
	}
	// Unselected records advance too: a quiet source must not retain an
	// ancient warning's cursor until vacuum removes it. Nothing from those
	// records is persisted except the final opaque journal position.
	return rt.DB.SetCursor(j.cfg.Name, cursor)
}

func (j *Journal) batch(ctx context.Context, cursor string) ([]journalRecord, error) {
	// journalctl can seek to a nearby record when a cursor was vacuumed.
	// Include the checkpoint and require an exact match before consuming
	// anything. --lines=+N reads the OLDEST next records, unlike -n N which
	// could jump to the tail and lose a backlog larger than one batch.
	// ponytail: scan 100 system records/tick and filter below; this preserves
	// exact checkpoint verification and progress through quiet selections.
	// Add indexed unit queries only if measured journal volume needs them.
	records, err := j.read(ctx, "__CURSOR,__REALTIME_TIMESTAMP,_SYSTEMD_UNIT,UNIT,_PID,PRIORITY,MESSAGE",
		"--cursor="+cursor, "--lines=+"+strconv.Itoa(journalBatchSize+1))
	if err != nil {
		return nil, err
	}
	if len(records) == 0 || records[0].text("__CURSOR") != cursor {
		return nil, fmt.Errorf("journal checkpoint unavailable (possibly rotated or vacuumed); refusing to skip records; use a new source name only if you intend to restart at the current tail")
	}
	return records[1:], nil
}

// journalRecord keeps fields untrusted. Journald may encode binary values or
// repeated fields as arrays and oversized values as null; neither should be
// coerced into a unit identity, severity, or executable argument.
type journalRecord map[string]json.RawMessage

func (r journalRecord) text(key string) string {
	var s string
	_ = json.Unmarshal(r[key], &s)
	return s
}

func (r journalRecord) cursor() (string, error) {
	c := r.text("__CURSOR")
	if len(c) == 0 || len(c) > 4096 || bytes.ContainsAny([]byte(c), "\x00\r\n") {
		return "", fmt.Errorf("journal record has an invalid cursor")
	}
	return c, nil
}

func (j *Journal) normalize(r journalRecord, cursor string) (event.Event, bool, error) {
	// A broad unit choice must not turn our own notifications/diagnostics
	// into new model work. Journald's trusted PID cannot be set by a client.
	// Include boot identity: a persisted backlog may contain an unrelated
	// process with this PID from a previous boot.
	if j.bootID != "" && r.text("_BOOT_ID") == j.bootID && r.text("_PID") == strconv.Itoa(os.Getpid()) {
		return event.Event{}, false, nil
	}
	unit := r.text("_SYSTEMD_UNIT")
	// Service state transitions are emitted by the system manager, not the
	// service itself. Accept its UNIT field only from trusted PID 1; never
	// treat a user unit's similarly named message as a system service event.
	if r.text("_PID") == "1" && r.text("UNIT") != "" {
		unit = r.text("UNIT")
	}
	allowed := false
	for _, configured := range j.cfg.Units {
		allowed = allowed || unit == configured
	}
	priority, err := strconv.Atoi(r.text("PRIORITY"))
	threshold, valid := config.JournalPriority(j.cfg.Priority)
	if !allowed || !valid || err != nil || priority < 0 || priority > threshold {
		return event.Event{}, false, nil
	}
	micros, err := strconv.ParseInt(r.text("__REALTIME_TIMESTAMP"), 10, 64)
	if err != nil || micros <= 0 {
		return event.Event{}, false, fmt.Errorf("selected journal record has an invalid timestamp")
	}
	message := r.text("MESSAGE")
	data := map[string]any{"unit": unit, "priority": priority, "message": message}
	// Default journalctl JSON omits large fields and represents binary ones
	// as arrays. Record the omission rather than pretending an empty message
	// was complete. Never request --all, which removes that upstream bound.
	if message == "" {
		data["message_omitted"] = true
	}
	if len(message) > 4096 {
		message = message[:4096]
		for !utf8.ValidString(message) {
			message = message[:len(message)-1]
		}
		data["message"] = message
		data["message_truncated"] = true
	}
	return event.Event{
		ID: event.NewID("evt_"), Type: j.cfg.EventType, Source: j.cfg.Name,
		Subject: unit, Timestamp: time.UnixMicro(micros).UTC(), Data: data,
		Metadata: map[string]any{"source_event_id": cursor},
	}, true, nil
}

// read bounds both child lifetime and output. No shell, pager, follow mode,
// or user-supplied command flags are involved. Even stderr is private: it can
// contain paths or log material, so failures return fixed actionable errors.
func (j *Journal) read(ctx context.Context, fields string, args ...string) ([]journalRecord, error) {
	ctx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	argv := append([]string{"--system", "--no-pager", "--output=json", "--output-fields=" + fields}, args...)
	cmd := exec.CommandContext(ctx, j.path, argv...)
	cmd.WaitDelay = time.Second
	out, stderr := journalOutput{limit: 4 << 20}, journalOutput{limit: 4096}
	cmd.Stdout, cmd.Stderr = &out, &stderr
	err := cmd.Run()
	if ctx.Err() != nil {
		return nil, ctx.Err()
	}
	if err != nil || stderr.buf.Len() != 0 {
		return nil, fmt.Errorf("journalctl failed or warned; verify system journal read access (often the systemd-journal or adm group), journal health, and support for --lines=+N; do not run mrmr as root")
	}
	dec := json.NewDecoder(&out.buf)
	var records []journalRecord
	for {
		var record journalRecord
		if err := dec.Decode(&record); err == io.EOF {
			return records, nil
		} else if err != nil || record == nil {
			return nil, fmt.Errorf("journalctl returned invalid JSON records")
		}
		records = append(records, record)
		if len(records) > journalBatchSize+1 {
			return nil, fmt.Errorf("journalctl exceeded the record limit")
		}
	}
}

// Do not embed bytes.Buffer: its promoted ReadFrom would let io.Copy bypass
// Write and defeat the memory bound when exec copies the child's output.
type journalOutput struct {
	buf   bytes.Buffer
	limit int
}

func (b *journalOutput) Write(p []byte) (int, error) {
	if len(p) > b.limit-b.buf.Len() {
		return 0, fmt.Errorf("journalctl output limit exceeded")
	}
	return b.buf.Write(p)
}

// These tests pin storage's durability and dedup contracts. Dedup is the
// runtime's exactly-once guarantee: a redelivered webhook must not produce
// a second decision, so the (source, dedup_key) uniqueness — via
// source_event_id or payload hash — is behavior users depend on, not an
// implementation detail. Migration idempotence matters because every
// process restart reopens the same database file.
package storage

import (
	"encoding/json"
	"path/filepath"
	"testing"
	"time"

	"github.com/heath0xff/mrmr/internal/event"
)

func testEvent(sourceEventID string, data map[string]any) event.Event {
	e := event.Event{
		ID:        event.NewID("evt_"),
		Type:      "commit.pushed",
		Source:    "github",
		Subject:   "mrmr",
		Timestamp: time.Now().UTC(),
		Data:      data,
	}
	if sourceEventID != "" {
		e.Metadata = map[string]any{"source_event_id": sourceEventID}
	}
	return e
}

func openTestDB(t *testing.T) *DB {
	t.Helper()
	d, err := Open(filepath.Join(t.TempDir(), "test.db"))
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	t.Cleanup(func() { d.Close() })
	return d
}

func TestInsertEventDuplicateBySourceEventID(t *testing.T) {
	d := openTestDB(t)
	first := testEvent("gh-123", map[string]any{"sha": "abc"})
	rec, err := d.InsertEvent(first)
	if err != nil {
		t.Fatalf("insert first: %v", err)
	}
	if rec.Duplicate {
		t.Error("first insert must not be a duplicate")
	}

	// A second event carrying the same source_event_id — as a webhook
	// redelivery would — is the same upstream occurrence even though the
	// mrmr-side event ID differs.
	second := testEvent("gh-123", map[string]any{"sha": "abc"})
	rec, err = d.InsertEvent(second)
	if err != nil {
		t.Fatalf("insert second: %v", err)
	}
	if !rec.Duplicate {
		t.Error("same source_event_id must be detected as duplicate")
	}
}

func TestInsertEventDuplicateByPayloadHash(t *testing.T) {
	d := openTestDB(t)
	// No source_event_id: dedup falls back to hashing type + data.
	// Identical payloads from the same source are treated as one event.
	a := testEvent("", map[string]any{"sha": "abc", "msg": "fix"})
	b := testEvent("", map[string]any{"sha": "abc", "msg": "fix"})
	if rec, err := d.InsertEvent(a); err != nil || rec.Duplicate {
		t.Fatalf("first insert: rec=%v err=%v, want non-duplicate", rec, err)
	}
	rec, err := d.InsertEvent(b)
	if err != nil {
		t.Fatalf("second insert: %v", err)
	}
	if !rec.Duplicate {
		t.Error("same payload with no source_event_id must be detected as duplicate")
	}

	// Different data hashes differently, so distinct events pass through.
	c := testEvent("", map[string]any{"sha": "def", "msg": "other"})
	rec, err = d.InsertEvent(c)
	if err != nil {
		t.Fatalf("third insert: %v", err)
	}
	if rec.Duplicate {
		t.Error("different payload must not be a duplicate")
	}
}

// Malformed optional IDs are absent identities, not shared synthetic keys.
// Hash fallback must still suppress actual redeliveries of the same payload.
func TestInvalidSourceEventIDFallsBackToPayload(t *testing.T) {
	for _, id := range []any{nil, "", true, []any{"id"}, map[string]any{"id": "x"}} {
		d := openTestDB(t)
		for i, payload := range []string{"first", "second", "second"} {
			e := testEvent("", map[string]any{"message": payload})
			e.Metadata = map[string]any{"source_event_id": id}
			rec, err := d.InsertEvent(e)
			if err != nil {
				t.Fatal(err)
			}
			if rec.Duplicate != (i == 2) {
				t.Fatalf("id=%#v payload=%q duplicate=%v", id, payload, rec.Duplicate)
			}
		}
	}
}

// Every read path feeds inspection or export. None may undo exact ingestion
// by silently rounding a numeric identity on the way back out of SQLite.
func TestEventNumbersSurviveStorageReads(t *testing.T) {
	d := openTestDB(t)
	const id = json.Number("9007199254740993")
	e := testEvent("", map[string]any{"id": id})
	e.Metadata = map[string]any{"source_event_id": id}
	if _, err := d.InsertEvent(e); err != nil {
		t.Fatal(err)
	}
	if _, err := d.LabelEvent(e.ID, "important", true, "notify"); err != nil {
		t.Fatal(err)
	}
	ins, err := d.Inspect(e.ID)
	if err != nil {
		t.Fatal(err)
	}
	list, err := d.ListEvents(10, false)
	if err != nil {
		t.Fatal(err)
	}
	labeled, err := d.LabeledEvents()
	if err != nil {
		t.Fatal(err)
	}
	if len(list) != 1 || len(labeled) != 1 {
		t.Fatal("stored event missing from review/export")
	}
	for _, got := range []event.Event{ins.Event, list[0].Event, labeled[0].Event} {
		if got.Data["id"] != id || got.Metadata["source_event_id"] != id {
			t.Fatalf("numeric identity changed: %+v", got)
		}
		got.ID = event.NewID("evt_")
		if rec, err := d.InsertEvent(got); err != nil || !rec.Duplicate {
			t.Fatalf("round-tripped event did not deduplicate: rec=%+v err=%v", rec, err)
		}
	}
}

func TestDecisionRoundTrip(t *testing.T) {
	d := openTestDB(t)
	ev, err := d.InsertEvent(testEvent("gh-1", nil))
	if err != nil {
		t.Fatalf("insert event: %v", err)
	}
	dec := event.Decision{
		ID:          event.NewID("dec_"),
		EventID:     ev.Event.ID,
		Interpreter: "local",
		Model:       "mock-model",
		Status:      "ok",
		Result:      map[string]any{"category": "important", "importance": 0.9},
		LatencyMs:   42,
	}
	if err := d.InsertDecision(dec); err != nil {
		t.Fatalf("insert decision: %v", err)
	}

	var (
		resultJSON, status, model, interpreter string
		latency                                int64
	)
	err = d.QueryRow(`SELECT interpreter, model, status, result, latency_ms FROM decisions WHERE id = ?`, dec.ID).
		Scan(&interpreter, &model, &status, &resultJSON, &latency)
	if err != nil {
		t.Fatalf("query decision: %v", err)
	}
	if interpreter != dec.Interpreter || model != dec.Model || status != "ok" || latency != 42 {
		t.Errorf("round trip got interpreter=%q model=%q status=%q latency=%d, want original", interpreter, model, status, latency)
	}
	var result map[string]any
	if err := json.Unmarshal([]byte(resultJSON), &result); err != nil {
		t.Fatalf("unmarshal result: %v", err)
	}
	if result["category"] != "important" || result["importance"] != 0.9 {
		t.Errorf("result = %v, want marshaled decision result back", result)
	}
}

