// Source cursor persistence. The cursor is a per-source watermark: the
// poller's restart-safe position in a feed. It is an optimization and a
// resume point, never the dedup mechanism — dedup lives in InsertEvent's
// (source, source_event_id) key, so a lost or stale cursor can cause
// re-offering, never re-processing.
package storage

import (
	"database/sql"
	"fmt"
)

// Cursor returns the persisted watermark for a source. An unknown source is
// a fresh poller: "" and no error.
func (d *DB) Cursor(name string) (string, error) {
	var c string
	err := d.QueryRow(`SELECT cursor FROM source_cursors WHERE name = ?`, name).Scan(&c)
	if err == sql.ErrNoRows {
		return "", nil
	}
	if err != nil {
		return "", fmt.Errorf("read cursor %s: %w", name, err)
	}
	return c, nil
}

// SetCursor persists the watermark upsert-style: the poll loop is the only
// writer per source, so last-write-wins is correct.
func (d *DB) SetCursor(name, cursor string) error {
	_, err := d.Exec(`INSERT INTO source_cursors (name, cursor, updated_at) VALUES (?, ?, ?)
		ON CONFLICT(name) DO UPDATE SET cursor = excluded.cursor, updated_at = excluded.updated_at`,
		name, cursor, now())
	if err != nil {
		return fmt.Errorf("set cursor %s: %w", name, err)
	}
	return nil
}

// Package filter applies deterministic checks to Events before any model
// call. It is the pipeline's cost gate (IMPLEMENTATION.md section 3):
// events that ordinary code can already exclude must not spend inference.
// Evaluation is pure: no I/O, no clock, no model. A filter can never
// fail in a way a model can, which is what makes the excluded path safe
// by construction.
//
// Two rules shape this package.
//
// Fail toward ignore. The filter is the only gate before policy, and
// policy is what authorizes outcomes. An event that cannot be resolved
// (missing field, malformed path, incomparable type) fails every
// comparison and is excluded, never passed by default. A malformed
// event that slips past the gate is one good model day from an outcome
// nobody authorized.
//
// Reasons are value-free. Failure reasons flow into the trace, the HTTP
// response, and stdout, and event payloads may be sensitive. A reason
// carries the rule index, field path, and operator only.
//
// This package does not reuse policy's comparisons on purpose. Filter
// ops are named (eq, neq) and compared by strict semantic type; policy
// conditions are operator-expression strings compared by fmt.Sprint.
// The gate is where a type-shifted value becomes a bypass, so it must
// not inherit the looser semantics. If a future third caller really
// shares one of these semantics, extract a neutral condition package
// then, not before.
package filter

import (
	"encoding/json"
	"fmt"
	"math"
	"math/big"
	"strings"

	"github.com/heath0xff/mrmr/internal/event"
)

// Op is the comparison a Spec applies. v0.1 ships only the two
// comparisons the spec documents for filters: neq (excluding known
// senders such as bots) and eq, which is also the default when op is
// left empty. Numeric ordering lands when a real flow needs it; the
// Spec shape does not change.
type Op string

const (
	OpEq  Op = "eq"
	OpNeq Op = "neq"
)

// Spec is one filter line. All Specs in a List are ANDed, mirroring
// policy's condition semantics: alternatives are separate Specs, not OR.
type Spec struct {
	Field string `yaml:"field"`
	Op    Op     `yaml:"op"`
	Value any    `yaml:"value"`
}

// List is the ordered set of Specs. An empty list passes every event, so
// a config without a filter section behaves exactly as before.
type List []Spec

// fieldRoots are the only path roots a Spec may address. They are the
// Event's top-level fields, with data and metadata open to dot descent.
var fieldRoots = map[string]bool{
	"type":     true,
	"source":   true,
	"subject":  true,
	"data":     true,
	"metadata": true,
}

// normalizePath reduces a Spec's field to its canonical form and reports
// whether it addresses a value the runtime can compare. The spec
// documents both "data.author" (section 3) and "event.data.author" (the
// flow example); exactly one leading "event." is accepted, so both forms
// behave identically. Everything else is rejected at config time because
// a filter that can never match is a typo, not a choice: unknown roots,
// a bare data/metadata (a map can never compare), and sub-paths under
// scalar roots (a scalar can never have children).
func normalizePath(field string) (string, error) {
	if field == "" {
		return "", fmt.Errorf("field is required")
	}
	if strings.HasPrefix(field, "event.") {
		field = field[len("event."):]
	}
	parts := strings.Split(field, ".")
	for _, p := range parts {
		if p == "" {
			return "", fmt.Errorf("field %q: empty path segment", field)
		}
	}
	root := parts[0]
	if !fieldRoots[root] {
		return "", fmt.Errorf("field %q: unknown root %q (want type, source, subject, data, or metadata)", field, root)
	}
	switch root {
	case "type", "source", "subject":
		if len(parts) > 1 {
			return "", fmt.Errorf("field %q: %s has no sub-paths", field, root)
		}
	default:
		if len(parts) == 1 {
			return "", fmt.Errorf("field %q: %s requires a sub-path", field, root)
		}
	}
	return field, nil
}

// Validate reports whether the Spec can run correctly. Config calls it
// for every filter line, so a malformed filter refuses startup rather
// than mis-firing at request time.
func (s Spec) Validate() error {
	if _, err := normalizePath(s.Field); err != nil {
		return err
	}
	switch s.Op {
	case "", OpEq, OpNeq:
	default:
		return fmt.Errorf("op %q not supported (v0.1: eq, neq)", s.Op)
	}
	if s.Value == nil {
		return fmt.Errorf("field %q: value is required", s.Field)
	}
	if !valueOK(s.Value) {
		return fmt.Errorf("field %q: value must be a string, number, or boolean", s.Field)
	}
	return nil
}

// Evaluate reports whether e passes every Spec in order, and returns the
// first failure as a value-free reason (rule index, path, operator) for
// the trace. ok is true when the list is empty or every Spec passes.
func (l List) Evaluate(e event.Event) (bool, string) {
	for i, s := range l {
		path, err := normalizePath(s.Field)
		if err != nil {
			// Unreachable after config validation; fail closed anyway.
			// A Spec that cannot be parsed must exclude, not pass.
			return false, fmt.Sprintf("filter %d: malformed field", i+1)
		}
		got, present := resolve(e, path)
		if !present {
			// A missing field fails every operator, including neq: the
			// event cannot prove itself acceptable to the gate, and
			// exclusion is the only safe answer.
			return false, fmt.Sprintf("filter %d: field %s not present", i+1, path)
		}
		if !matches(s.Op, s.Value, got) {
			return false, fmt.Sprintf("filter %d: %s (%s) did not match", i+1, path, opName(s.Op))
		}
	}
	return true, ""
}

func opName(op Op) string {
	if op == "" {
		return string(OpEq)
	}
	return string(op)
}

// resolve walks a normalized dot path against the Event. Scalar roots
// resolve exactly; data and metadata descend into maps. Every miss
// (unknown key, a non-map mid-path, a map at the end, an empty scalar
// root) is "not present": resolution never guesses. Subject is
// optional, so an empty subject is not present. The same guard applies
// to type and source because Ingest can be called outside the HTTP
// handler, which is the only place that requires them non-empty.
func resolve(e event.Event, path string) (any, bool) {
	parts := strings.Split(path, ".")
	switch parts[0] {
	case "type":
		if e.Type != "" {
			return e.Type, true
		}
	case "source":
		if e.Source != "" {
			return e.Source, true
		}
	case "subject":
		if e.Subject != "" {
			return e.Subject, true
		}
	case "data":
		return walk(e.Data, parts[1:])
	case "metadata":
		return walk(e.Metadata, parts[1:])
	}
	return nil, false
}

// walk descends one level at a time. It is only called with a non-empty
// parts slice: normalizePath rejects a bare data/metadata root.
func walk(m map[string]any, parts []string) (any, bool) {
	cur, ok := m[parts[0]]
	if !ok {
		return nil, false
	}
	if len(parts) == 1 {
		return cur, true
	}
	next, ok := cur.(map[string]any)
	if !ok {
		return nil, false
	}
	return walk(next, parts[1:])
}

// kind is a value's semantic type. Anything that is not a number,
// string, or bool (nil, maps, slices) is opaque and comparable with
// nothing.
type kind int

const (
	kindNumber kind = iota
	kindString
	kindBool
	kindOpaque
)

func classify(v any) kind {
	switch v.(type) {
	case json.Number, int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64, float32, float64:
		return kindNumber
	case string:
		return kindString
	case bool:
		return kindBool
	}
	return kindOpaque
}

// toNumber compares numeric spellings exactly: preserving IDs at ingestion
// is useless if a filter immediately aliases adjacent large integers again.
// The finite check also bounds JSON exponents before big.Rat allocates them;
// malformed/non-finite values remain incomparable for both eq and neq.
func toNumber(v any) (*big.Rat, bool) {
	if n, ok := v.(json.Number); ok {
		f, err := n.Float64()
		if err != nil || !finite(f) {
			return nil, false
		}
		if f == 0 {
			// ParseFloat permits underflow. Reject nonzero mantissas rather
			// than allocating an enormous denominator for e.g. 1e-999999999.
			mantissa, _, _ := strings.Cut(strings.ToLower(string(n)), "e")
			return new(big.Rat), strings.Trim(mantissa, "-0.") == ""
		}
	}
	return new(big.Rat).SetString(fmt.Sprint(v))
}

// valueOK reports whether a Spec value can ever take part in a
// comparison. The comparator works on three semantic types: number,
// string, bool. Anything else (lists, maps, channels) can never
// match, and a filter line that can never match is a typo, not a
// choice: it must fail startup, not silently exclude every event at
// runtime. Numbers must be finite: NaN never equals itself, so it can
// never satisfy eq and would pass neq against every value; Inf is not
// a value a source will send. Both are unmatchable by construction.
func valueOK(v any) bool {
	switch n := v.(type) {
	case string, bool:
		return true
	case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64:
		return true
	case float32:
		return finite(float64(n))
	case float64:
		return finite(n)
	}
	return false
}

// finite reports whether a number can take part in a comparison.
// Shared by valueOK (config side) and toNumber (event side) so the
// non-finite rule has one definition.
func finite(f float64) bool {
	return !math.IsNaN(f) && !math.IsInf(f, 0)
}

// compare reports whether two values are equal, and whether they are
// comparable at all. Comparison is strict by semantic type on purpose,
// and intentionally stricter than policy.match's fmt.Sprint semantics:
// at the gate, a type-shifted value (the number 5 where a string is
// expected, "true" where a bool is expected) must not satisfy neq and
// slide past the gate. Numeric values normalize across int and float
// representations because YAML decodes 5 as int and ingestion preserves JSON
// numbers as json.Number: the same number, two sources. Different kinds are
// incomparable.
func compare(want, got any) (equal, comparable bool) {
	k := classify(want)
	if k != classify(got) || k == kindOpaque {
		return false, false
	}
	switch k {
	case kindNumber:
		w, wok := toNumber(want)
		g, gok := toNumber(got)
		if !wok || !gok {
			return false, false
		}
		return w.Cmp(g) == 0, true
	case kindString:
		return want.(string) == got.(string), true
	case kindBool:
		return want.(bool) == got.(bool), true
	}
	return false, false
}

// matches applies the operator. An incomparable pair fails for both eq
// and neq: the event is excluded either way, and the trace says which
// check excluded it.
func matches(op Op, want, got any) bool {
	equal, comparable := compare(want, got)
	if !comparable {
		return false
	}
	if op == OpNeq {
		return !equal
	}
	return equal
}

// These tests pin the filter gate's contract: deterministic, fail
// toward ignore, value-free reasons. The cases that matter most are the
// bypass cases: a missing field must not pass neq, and a type-shifted
// value must not satisfy either operator.
package filter

import (
	"encoding/json"
	"fmt"
	"math"
	"strings"
	"testing"

	"github.com/heath0xff/mrmr/internal/event"
)

func evt(data, meta map[string]any) event.Event {
	return event.Event{
		Type:     "commit.pushed",
		Source:   "github",
		Subject:  "mrmr",
		Data:     data,
		Metadata: meta,
	}
}

func TestEvaluatePassAndFail(t *testing.T) {
	tests := []struct {
		name  string
		specs List
		e     event.Event
		want  bool
	}{
		{"neq passes a different value", List{{Field: "data.author", Op: OpNeq, Value: "dependabot[bot]"}}, evt(map[string]any{"author": "alice"}, nil), true},
		{"neq excludes an equal value", List{{Field: "data.author", Op: OpNeq, Value: "dependabot[bot]"}}, evt(map[string]any{"author": "dependabot[bot]"}, nil), false},
		{"empty op defaults to eq", List{{Field: "data.author", Value: "alice"}}, evt(map[string]any{"author": "alice"}, nil), true},
		{"eq excludes a different value", List{{Field: "data.author", Op: OpEq, Value: "alice"}}, evt(map[string]any{"author": "bob"}, nil), false},
		{"exact JSON number matches YAML integer", List{{Field: "data.count", Value: 5}}, evt(map[string]any{"count": json.Number("5.0")}, nil), true},
		{"large integer matches exactly", List{{Field: "data.count", Value: int64(9007199254740993)}}, evt(map[string]any{"count": json.Number("9007199254740993")}, nil), true},
		{"adjacent large integers differ", List{{Field: "data.count", Value: int64(9007199254740992)}}, evt(map[string]any{"count": json.Number("9007199254740993")}, nil), false},
		{"numeric string stays a string", List{{Field: "data.count", Op: OpNeq, Value: "5"}}, evt(map[string]any{"count": json.Number("5")}, nil), false},
		{"numbers normalize int vs float", List{{Field: "data.count", Value: 5}}, evt(map[string]any{"count": 5.0}, nil), true},
		{"numbers compare across representations", List{{Field: "data.count", Op: OpNeq, Value: 5.0}}, evt(map[string]any{"count": 4}, nil), true},
		{"bools compare as bools", List{{Field: "data.flag", Value: true}}, evt(map[string]any{"flag": true}, nil), true},
		{"top-level type", List{{Field: "type", Op: OpNeq, Value: "spam.ping"}}, evt(nil, nil), true},
		{"top-level source", List{{Field: "source", Value: "github"}}, evt(nil, nil), true},
		{"subject", List{{Field: "subject", Value: "mrmr"}}, evt(nil, nil), true},
		{"nested data path", List{{Field: "data.a.b", Value: "x"}}, evt(map[string]any{"a": map[string]any{"b": "x"}}, nil), true},
		{"metadata path", List{{Field: "metadata.source_event_id", Value: "gh-1"}}, evt(nil, map[string]any{"source_event_id": "gh-1"}), true},
		{"event prefix form", List{{Field: "event.data.author", Op: OpNeq, Value: "dependabot[bot]"}}, evt(map[string]any{"author": "alice"}, nil), true},
		{"empty list passes", List{}, evt(nil, nil), true},
		{"all specs must pass", List{{Field: "type", Value: "commit.pushed"}, {Field: "data.author", Value: "alice"}}, evt(map[string]any{"author": "bob"}, nil), false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, _ := tt.specs.Evaluate(tt.e)
			if got != tt.want {
				t.Fatalf("Evaluate() = %v, want %v", got, tt.want)
			}
		})
	}
}

// TestEvaluateMissingFieldFailsEveryOp pins the gate rule: a field the
// event does not carry fails the filter for every operator. In
// particular neq must not pass a missing field, or a malformed event
// bypasses the pre-model gate and reaches policy, which can authorize
// outcomes.
func TestEvaluateMissingFieldFailsEveryOp(t *testing.T) {
	for _, op := range []Op{"", OpEq, OpNeq} {
		t.Run("op="+string(op), func(t *testing.T) {
			specs := List{{Field: "data.author", Op: op, Value: "dependabot[bot]"}}
			if got, _ := specs.Evaluate(evt(nil, nil)); got {
				t.Fatal("Evaluate() = true for a missing field, want excluded")
			}
		})
	}
}

// TestEvaluateTypeMismatchFailsBothOps pins the second bypass rule: a
// type-shifted value is incomparable and fails both operators. The
// fmt.Sprint equality this package deliberately does not use would let
// true satisfy a "true" check and let a number slide past a string neq.
func TestEvaluateTypeMismatchFailsBothOps(t *testing.T) {
	tests := []struct {
		name  string
		specs List
		e     event.Event
	}{
		{"bool want, string got, neq", List{{Field: "data.flag", Op: OpNeq, Value: true}}, evt(map[string]any{"flag": "true"}, nil)},
		{"bool want, string got, eq", List{{Field: "data.flag", Value: true}}, evt(map[string]any{"flag": "true"}, nil)},
		{"string want, number got, neq", List{{Field: "data.author", Op: OpNeq, Value: "dependabot[bot]"}}, evt(map[string]any{"author": 5}, nil)},
		{"number want, string got, eq", List{{Field: "data.count", Value: 5}}, evt(map[string]any{"count": "5"}, nil)},
		{"number want, string got, neq", List{{Field: "data.count", Op: OpNeq, Value: 5}}, evt(map[string]any{"count": "5"}, nil)},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got, _ := tt.specs.Evaluate(tt.e); got {
				t.Fatal("Evaluate() = true for a type mismatch, want excluded")
			}
		})
	}
}

// TestEvaluateReasonIsValueFree pins the privacy rule: the failure
// reason reaches the trace, the HTTP response, and stdout, so it may
// carry the rule index, field path, and operator only. Event payload
// and configured values must never appear in it.
func TestEvaluateReasonIsValueFree(t *testing.T) {
	specs := List{{Field: "data.token", Op: OpNeq, Value: "expected-secret"}}
	e := evt(map[string]any{"token": "expected-secret"}, nil)
	got, reason := specs.Evaluate(e)
	if got {
		t.Fatal("Evaluate() = true, want excluded")
	}
	for _, leaked := range []string{"expected-secret"} {
		if strings.Contains(reason, leaked) {
			t.Errorf("reason %q leaks %q", reason, leaked)
		}
	}
	if reason != "filter 1: data.token (neq) did not match" {
		t.Errorf("reason = %q, want the value-free form", reason)
	}
}

// TestEvaluateReasonNamesTheFailingRule pins that the reason identifies
// which rule excluded the event, so the trace answers "why" without
// reading the config.
func TestEvaluateReasonNamesTheFailingRule(t *testing.T) {
	specs := List{
		{Field: "type", Value: "commit.pushed"},
		{Field: "metadata.source_event_id", Op: OpNeq, Value: "dup-1"},
	}
	e := evt(nil, map[string]any{"source_event_id": "dup-1"})
	got, reason := specs.Evaluate(e)
	if got {
		t.Fatal("Evaluate() = true, want excluded")
	}
	if reason != "filter 2: metadata.source_event_id (neq) did not match" {
		t.Errorf("reason = %q, want the second rule named", reason)
	}
}

func TestSpecValidate(t *testing.T) {
	tests := []struct {
		name string
		spec Spec
		want string
	}{
		{"empty field", Spec{Op: OpEq, Value: "x"}, "field is required"},
		{"unknown root", Spec{Field: "foo.bar", Op: OpEq, Value: "x"}, `unknown root "foo"`},
		{"bare data root", Spec{Field: "data", Op: OpEq, Value: "x"}, "data requires a sub-path"},
		{"bare metadata root", Spec{Field: "metadata", Op: OpEq, Value: "x"}, "metadata requires a sub-path"},
		{"sub-path under scalar root", Spec{Field: "type.x", Op: OpEq, Value: "x"}, "type has no sub-paths"},
		{"double event prefix", Spec{Field: "event.event.data.x", Op: OpEq, Value: "x"}, `unknown root "event"`},
		{"empty segment", Spec{Field: "data..x", Op: OpEq, Value: "x"}, "empty path segment"},
		{"trailing dot", Spec{Field: "data.x.", Op: OpEq, Value: "x"}, "empty path segment"},
		{"unknown op", Spec{Field: "data.author", Op: "lt", Value: "x"}, `op "lt" not supported`},
		{"missing value", Spec{Field: "data.author", Op: OpNeq, Value: nil}, "value is required"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := tt.spec.Validate()
			if err == nil {
				t.Fatal("Validate() = nil, want error")
			}
			if !strings.Contains(err.Error(), tt.want) {
				t.Errorf("Validate() error = %q, want containing %q", err, tt.want)
			}
		})
	}
}

// TestSpecValidateAcceptsDocumentedForms pins the two documented
// spellings of a filter field (section 3 and the flow example) plus the
// scalar-root and metadata forms, so strict validation never rejects a
// documented example.
func TestSpecValidateAcceptsDocumentedForms(t *testing.T) {
	specs := []Spec{
		{Field: "data.author", Op: OpNeq, Value: "x"},
		{Field: "event.data.author", Op: OpNeq, Value: "x"},
		{Field: "event.type", Value: "x"},
		{Field: "metadata.source_event_id", Op: "", Value: 5},
	}
	for _, s := range specs {
		if err := s.Validate(); err != nil {
			t.Errorf("Validate(%+v) = %v, want nil", s, err)
		}
	}
}

// TestEvaluateEmptySubjectFailsNeq pins the optional-field rule:
// subject is optional, so an event without one has no value to
// compare. neq must not treat the empty string as a value that differs
// from the excluded one, or a subject-less event slips past the gate.
func TestEvaluateEmptySubjectFailsNeq(t *testing.T) {
	specs := List{{Field: "subject", Op: OpNeq, Value: "blocked"}}
	e := event.Event{Type: "commit.pushed", Source: "github"}
	if got, _ := specs.Evaluate(e); got {
		t.Fatal("Evaluate() = true for an empty subject, want excluded")
	}
}

// TestEvaluateEmptyScalarRootsFailNeq pins the same guard on type and
// source: Ingest can be called outside the HTTP handler, which is the
// only place that requires them non-empty, so an empty value there is
// not present, not a comparison.
func TestEvaluateEmptyScalarRootsFailNeq(t *testing.T) {
	for _, field := range []string{"type", "source", "subject"} {
		t.Run(field, func(t *testing.T) {
			specs := List{{Field: field, Op: OpNeq, Value: "blocked"}}
			if got, _ := specs.Evaluate(event.Event{}); got {
				t.Fatal("Evaluate() = true for an empty scalar root, want excluded")
			}
		})
	}
}

// TestSpecValidateRejectsNonFiniteFloat32 pins the config-side half of
// the non-finite rule for the float32 kind: a NaN or Inf config value
// can never match, so it must fail startup rather than silently
// exclude every event at runtime.
func TestSpecValidateRejectsNonFiniteFloat32(t *testing.T) {
	for _, v := range []any{float32(math.NaN()), float32(math.Inf(1))} {
		spec := Spec{Field: "data.score", Op: OpNeq, Value: v}
		if err := spec.Validate(); err == nil {
			t.Fatalf("Validate() = nil for %v, want a non-finite value error", v)
		}
	}
}

// TestEvaluateNonFiniteEventValueFails pins the event-side half: a NaN
// or Inf value in event data is not comparable, so it fails both
// operators. Without the guard, neq passes every non-finite value and
// malformed data slips past the gate.
func TestEvaluateNonFiniteEventValueFails(t *testing.T) {
	for _, v := range []any{math.NaN(), math.Inf(1), json.Number("NaN"), json.Number("1e999999999"), json.Number("1e-999999999")} {
		for _, op := range []Op{OpEq, OpNeq} {
			t.Run(fmt.Sprintf("%v-%s", v, op), func(t *testing.T) {
				specs := List{{Field: "data.score", Op: op, Value: 0.5}}
				if got, _ := specs.Evaluate(evt(map[string]any{"score": v}, nil)); got {
					t.Fatal("Evaluate() = true for a non-finite event value, want excluded")
				}
			})
		}
	}
}

// These tests pin the deterministic half of the mrmr loop: policy.Evaluate
// must depend only on the decision result and rule order, never on model
// judgment. Everything the interpreter produces flows through here, so a
// regression in matching, ordering, or the default fallback silently
// changes what outcomes users see.
package policy

import "testing"

func notify() Then         { return Then{Notify: &Notify{Via: "stdout"}} }
func ignore() Then         { return Then{Ignore: true} }
func isNotify(t Then) bool { return t.Outcome() == "notify" }

func eval(t testing.TB, p Policy, result map[string]any) Then {
	then, _ := p.Evaluate(result)
	return then
}

func TestEvaluateOperators(t *testing.T) {
	tests := []struct {
		name string
		op   string
		got  any
		want bool
	}{
		{"gt true", "> 0.8", 0.9, true},
		{"gt false at boundary", "> 0.8", 0.8, false},
		{"gt false below", "> 0.8", 0.1, false},
		{"gte true at boundary", ">= 0.8", 0.8, true},
		{"gte true above", ">= 0.8", 0.81, true},
		{"gte false below", ">= 0.8", 0.79, false},
		{"lt true", "< 0.5", 0.4, true},
		{"lt false at boundary", "< 0.5", 0.5, false},
		{"lte true at boundary", "<= 0.5", 0.5, true},
		{"lte false above", "<= 0.5", 0.51, false},
		{"neq numeric false when equal", "!= 5", 5, false},
		{"neq numeric true when different", "!= 5", 6, true},
		{"neq numeric string operand", "!= 5", "6", true},
		{"neq non-numeric strings", "!= urgent", "normal", true},
		{"neq non-numeric equal strings", "!= urgent", "urgent", false},
		{"gt non-numeric operand never matches", "> high", "high", false},
		{"gt non-numeric result never matches", "> 0.5", "high", false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			p := Policy{
				Rules:   []Rule{{If: map[string]any{"result.score": tt.op}, Then: notify()}},
				Default: ignore(),
			}
			if got := isNotify(eval(t, p, map[string]any{"score": tt.got})); got != tt.want {
				t.Errorf("Evaluate(score=%v, cond %q) notify=%v, want %v", tt.got, tt.op, got, tt.want)
			}
		})
	}
}

func TestEvaluateLiteralEquality(t *testing.T) {
	p := Policy{
		Rules:   []Rule{{If: map[string]any{"result.category": "important"}, Then: notify()}},
		Default: ignore(),
	}
	if !isNotify(eval(t, p, map[string]any{"category": "important"})) {
		t.Error("string literal equality should match")
	}
	if isNotify(eval(t, p, map[string]any{"category": "unimportant"})) {
		t.Error("different string literal should not match")
	}
}

func TestEvaluateNestedResultFields(t *testing.T) {
	p := Policy{
		Rules: []Rule{{If: map[string]any{
			"result.category.choice":      "incident",
			"result.category.confidence":  ">= 0.8",
			"result.requires_action.noul": ">= 0.8",
		}, Then: notify()}},
		Default: ignore(),
	}
	result := map[string]any{
		"category":        map[string]any{"choice": "incident", "confidence": 0.9},
		"requires_action": map[string]any{"noul": 0.85},
	}
	if !isNotify(eval(t, p, result)) {
		t.Error("nested typed answer should match")
	}
	result["category"].(map[string]any)["confidence"] = 0.7
	if isNotify(eval(t, p, result)) {
		t.Error("nested value below threshold must not match")
	}
}

func TestEvaluateFirstMatchWins(t *testing.T) {
	// Both rules match; the earlier one must win. Rule order is the only
	// tiebreaker — policy has no priorities or scores.
	p := Policy{
		Rules: []Rule{
			{If: map[string]any{"result.category": "important"}, Then: ignore()},
			{If: map[string]any{"result.importance": "> 0"}, Then: notify()},
		},
		Default: notify(),
	}
	got := eval(t, p, map[string]any{"category": "important", "importance": 0.9})
	if isNotify(got) {
		t.Error("first matching rule should win (ignore), got notify")
	}
}

func TestEvaluateDefaultFallback(t *testing.T) {
	p := Policy{
		Rules:   []Rule{{If: map[string]any{"result.importance": "> 0.8"}, Then: notify()}},
		Default: ignore(),
	}
	if isNotify(eval(t, p, map[string]any{"importance": 0.2})) {
		t.Error("no rule matched; default (ignore) should apply")
	}
}

func TestEvaluateMissingResultFieldDoesNotMatch(t *testing.T) {
	// A condition naming a field the model never returned must fail the
	// rule, not panic and not silently match — otherwise typos in rule
	// keys would fire outcomes on every event.
	p := Policy{
		Rules:   []Rule{{If: map[string]any{"result.nonexistent": "> 0"}, Then: notify()}},
		Default: ignore(),
	}
	if isNotify(eval(t, p, map[string]any{"importance": 0.9})) {
		t.Error("condition on missing field must not match")
	}
}

func TestEvaluateResultPrefixStripping(t *testing.T) {
	// Conditions canonically use the "result." prefix, but the prefix is
	// stripped so bare field names behave identically. Both spellings
	// must resolve to the same result key.
	p := Policy{
		Rules: []Rule{
			{If: map[string]any{"result.category": "important"}, Then: notify()},
		},
		Default: ignore(),
	}
	if !isNotify(eval(t, p, map[string]any{"category": "important"})) {
		t.Error(`"result." prefixed key should strip the prefix`)
	}

	bare := Policy{
		Rules:   []Rule{{If: map[string]any{"category": "important"}, Then: notify()}},
		Default: ignore(),
	}
	if !isNotify(eval(t, bare, map[string]any{"category": "important"})) {
		t.Error("bare key (no prefix) should match the same field")
	}
}

func TestEvaluateReturnsMatchedRuleIndex(t *testing.T) {
	// The trace must be able to say which rule fired, so Evaluate reports
	// the matched rule's index — or -1 when the default applied. A trace
	// that says "notify" without saying why is half an answer.
	p := Policy{
		Rules: []Rule{
			{If: map[string]any{"result.importance": "> 0.9"}, Then: notify()},
			{If: map[string]any{"result.importance": "> 0.5"}, Then: ignore()},
		},
		Default: notify(),
	}
	if _, i := p.Evaluate(map[string]any{"importance": 0.95}); i != 0 {
		t.Errorf("importance 0.95 matched rule %d, want 0", i)
	}
	if _, i := p.Evaluate(map[string]any{"importance": 0.6}); i != 1 {
		t.Errorf("importance 0.6 matched rule %d, want 1", i)
	}
	if _, i := p.Evaluate(map[string]any{"importance": 0.1}); i != -1 {
		t.Errorf("no match returned %d, want -1 (default)", i)
	}
}

func TestEvaluateMultipleConditionsANDed(t *testing.T) {
	p := Policy{
		Rules: []Rule{{
			If:   map[string]any{"result.category": "important", "result.importance": "> 0.8"},
			Then: notify(),
		}},
		Default: ignore(),
	}
	if !isNotify(eval(t, p, map[string]any{"category": "important", "importance": 0.9})) {
		t.Error("all conditions satisfied should match")
	}
	if isNotify(eval(t, p, map[string]any{"category": "important", "importance": 0.5})) {
		t.Error("one unsatisfied condition must fail the whole rule (AND)")
	}
}

