// These tests pin trace durability. The trace returned to whoever posted an
// event is gone the moment that caller drops it; the stored copy is what
// answers "why did this happen?" a week later, so it must match the returned
// trace step for step and must exist for the short-circuit paths too — a
// filter exclusion is precisely the case someone comes back to inspect.
package runtime

import (
	"context"
	"testing"

	"github.com/heath0xff/mrmr/internal/filter"
	"github.com/heath0xff/mrmr/internal/policy"
)

func TestIngestPersistsTraceForInspection(t *testing.T) {
	url, _ := modelServer(t, `{"category":"important","importance":0.95}`)
	rt := newTestRuntime(t, url)

	resp, err := rt.Ingest(context.Background(), testEvent("gh-trace"))
	if err != nil {
		t.Fatalf("Ingest: %v", err)
	}
	stored, err := rt.DB.EventTrace(resp.EventID)
	if err != nil {
		t.Fatalf("EventTrace: %v", err)
	}
	if len(stored) != len(resp.Trace) {
		t.Fatalf("stored trace has %d steps, want %d (the returned trace)", len(stored), len(resp.Trace))
	}
	for i := range resp.Trace {
		if stored[i].Stage != resp.Trace[i].Stage || stored[i].Msg != resp.Trace[i].Msg {
			t.Fatalf("stored step %d = %+v, want %+v", i, stored[i], resp.Trace[i])
		}
	}
}

func TestIngestPersistsTraceForFilterExcludedEvent(t *testing.T) {
	url, calls := modelServer(t, `{"category":"important","importance":0.95}`)
	rt := newTestRuntime(t, url)
	rt.Filters = filter.List{{Field: "source", Op: filter.OpNeq, Value: "github"}}

	resp, err := rt.Ingest(context.Background(), testEvent("gh-filtered"))
	if err != nil {
		t.Fatalf("Ingest: %v", err)
	}
	if n := calls.Load(); n != 0 {
		t.Fatalf("model called %d times, want 0 (filter must short-circuit)", n)
	}
	stored, err := rt.DB.EventTrace(resp.EventID)
	if err != nil {
		t.Fatalf("EventTrace: %v", err)
	}
	if len(stored) != len(resp.Trace) {
		t.Fatalf("stored trace has %d steps, want %d", len(stored), len(resp.Trace))
	}
	var sawFilter bool
	for _, s := range stored {
		if s.Stage == "filter" {
			sawFilter = true
		}
	}
	if !sawFilter {
		t.Errorf("stored trace = %+v, want a filter step explaining the exclusion", stored)
	}
}

func TestIngestDuplicateStoresNoTrace(t *testing.T) {
	url, _ := modelServer(t, `{"category":"important","importance":0.9}`)
	rt := newTestRuntime(t, url)

	if _, err := rt.Ingest(context.Background(), testEvent("gh-dup-trace")); err != nil {
		t.Fatalf("first Ingest: %v", err)
	}
	// The duplicate's event ID was never stored, so there is nothing for a
	// trace to hang off; the original event's trace is the explanation.
	dup := testEvent("gh-dup-trace")
	resp, err := rt.Ingest(context.Background(), dup)
	if err != nil {
		t.Fatalf("second Ingest: %v", err)
	}
	if !resp.Duplicate {
		t.Fatal("second ingest of the same source_event_id must be a duplicate")
	}
	stored, err := rt.DB.EventTrace(dup.ID)
	if err != nil {
		t.Fatalf("EventTrace: %v", err)
	}
	if len(stored) != 0 {
		t.Errorf("duplicate stored %d trace steps, want 0", len(stored))
	}
}

func TestIngestEmitStoresTraceForEveryEventInTheChain(t *testing.T) {
	// An emitted child runs the pipeline itself, so it gets its own trace
	// under its own event id — including the last child, which the depth cap
	// records without interpreting. If any hop stored no trace, an emitted
	// chain would be unexplainable past the first one.
	url, _ := modelServer(t, `{"category":"important","importance":0.95}`)
	rt := newTestRuntime(t, url)
	rt.Policy = policy.Policy{
		Rules: []policy.Rule{{
			If:   map[string]any{"result.importance": "> 0.8"},
			Then: policy.Then{Action: &policy.Action{Type: "emit", EventType: "chain.child"}},
		}},
		Default: policy.Then{Ignore: true},
	}

	if _, err := rt.Ingest(context.Background(), testEvent("gh-emit-trace")); err != nil {
		t.Fatalf("Ingest: %v", err)
	}

	var untraced int
	if err := rt.DB.QueryRow(`SELECT COUNT(*) FROM events e
		WHERE NOT EXISTS (SELECT 1 FROM event_traces t WHERE t.event_id = e.id)`).Scan(&untraced); err != nil {
		t.Fatalf("count untraced events: %v", err)
	}
	if untraced != 0 {
		t.Errorf("%d stored events have no trace, want 0", untraced)
	}
}

// These tests pin the events handler, the runtime's only ingress: every way
// untrusted input is rejected (missing type/source, malformed JSON, oversized
// bodies) must fail with a 400 and {"error": ...} before the pipeline —
// SQLite, model call, policy — is ever touched, and a valid event must come
// back as a 200 whose body is the full trace of what happened. The handler
// is exercised directly with a recorder instead of booting the server so a
// failure points at ingress logic, not at the run loop.
package main

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"sync/atomic"
	"testing"

	"github.com/heath0xff/mrmr/internal/config"
	"github.com/heath0xff/mrmr/internal/model"
	"github.com/heath0xff/mrmr/internal/policy"
	"github.com/heath0xff/mrmr/internal/runtime"
	"github.com/heath0xff/mrmr/internal/storage"
)

// modelServer serves canned chat-completion contents over httptest, so
// these tests need no network and no real model. The call count lets the
// rejection cases assert the pipeline was never reached.
func modelServer(t *testing.T, contents ...string) (url string, calls *atomic.Int32) {
	t.Helper()
	var n atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		i := int(n.Add(1)) - 1
		content := contents[len(contents)-1]
		if i < len(contents) {
			content = contents[i]
		}
		w.Header().Set("Content-Type", "application/json")
		fmt.Fprint(w, `{"choices":[{"message":{"content":`+fmt.Sprintf("%q", content)+`}}]}`)
	}))
	t.Cleanup(srv.Close)
	return srv.URL, &n
}

// newTestHandler wires a real runtime over a temp-dir SQLite DB and a mock
// model endpoint. The schema and policy mirror the runtime tests: one
// classification contract and a single importance threshold routing to
// stdout, so a canned "important" answer deterministically produces notify.
func newTestHandler(t *testing.T, contents ...string) (http.HandlerFunc, *atomic.Int32) {
	t.Helper()
	url, calls := modelServer(t, contents...)
	db, err := storage.Open(filepath.Join(t.TempDir(), "test.db"))
	if err != nil {
		t.Fatalf("open storage: %v", err)
	}
	t.Cleanup(func() { db.Close() })
	rt := &runtime.Runtime{
		DB:       db,
		Client:   &model.Client{},
		ModelCfg: model.Config{Provider: "openai-compatible", BaseURL: url, Model: "mock-model"},
		ModelKey: "mock",
		Prompt:   "classify this event",
		Schema: model.Schema{
			"category":   {Type: "string", Enum: []any{"important", "unimportant"}},
			"importance": {Type: "number"},
		},
		Policy: policy.Policy{
			Rules: []policy.Rule{{
				If:   map[string]any{"result.importance": "> 0.8"},
				Then: policy.Then{Notify: &policy.Notify{Via: "stdout"}},
			}},
			Default: policy.Then{Ignore: true},
		},
	}
	return eventsHandler(rt), calls
}

// handlerResponse mirrors just the response fields the handler contract
// promises, so the assertions stay about the wire shape and not the
// runtime's internal structs.
type handlerResponse struct {
	EventID  string `json:"event_id"`
	Outcome  string `json:"outcome"`
	Decision *struct {
		Status string         `json:"status"`
		Result map[string]any `json:"result"`
	} `json:"decision"`
}

func post(t *testing.T, h http.HandlerFunc, contentType string, body string) *httptest.ResponseRecorder {
	t.Helper()
	req := httptest.NewRequest(http.MethodPost, "/api/events", strings.NewReader(body))
	req.Header.Set("Content-Type", contentType)
	rec := httptest.NewRecorder()
	h(rec, req)
	return rec
}

// A failed later source must not activate an earlier poller. In particular,
// journal permission/platform failures must not leave effects running during
// a startup that the user was told failed.
func TestPrepareSourcesDoesNotActivatePartialConfig(t *testing.T) {
	var calls atomic.Int32
	feed := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls.Add(1)
		fmt.Fprint(w, `[]`)
	}))
	defer feed.Close()
	t.Setenv("PATH", t.TempDir()) // missing journalctl on Linux, platform error elsewhere
	runners, err := prepareSources(context.Background(), []config.Source{
		{Name: "http", Type: "http-poller", URL: feed.URL},
		{Name: "journal", Type: "systemd-journal"},
	}, nil)
	if err == nil || runners != nil || calls.Load() != 0 {
		t.Fatalf("partial activation: runners=%d, err=%v, calls=%d", len(runners), err, calls.Load())
	}
}

func TestEventsHandlerValidEvent(t *testing.T) {
	h, calls := newTestHandler(t, `{"category":"important","importance":0.95}`)

	rec := post(t, h, "application/json", `{"type":"commit.pushed","source":"github","data":{"msg":"fix bug"}}`)
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200 (body: %s)", rec.Code, rec.Body.String())
	}
	var resp handlerResponse
	if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil {
		t.Fatalf("decode response: %v", err)
	}
	if resp.EventID == "" {
		t.Error("event_id missing from response body")
	}
	if resp.Outcome != "notify" {
		t.Errorf("outcome = %q, want notify (importance 0.95 > 0.8)", resp.Outcome)
	}
	if resp.Decision == nil || resp.Decision.Status != "ok" {
		t.Fatalf("decision = %+v, want an ok decision in the body", resp.Decision)
	}
	if resp.Decision.Result["importance"] != 0.95 {
		t.Errorf("decision result = %v, want the model's validated result", resp.Decision.Result)
	}
	if n := calls.Load(); n != 1 {
		t.Errorf("model called %d times, want 1", n)
	}
}

// The API and poller share the same dedup boundary. Fixing numeric feed IDs
// must not leave webhook deliveries rounding to the same storage key.
func TestEventsHandlerPreservesNumericIDs(t *testing.T) {
	for _, field := range []string{`"metadata":{"source_event_id":%s}`, `"data":{"id":%s}`} {
		h, calls := newTestHandler(t, `{"category":"unimportant","importance":0.1}`)
		for i, id := range []string{"9007199254740992", "9007199254740993", "9007199254740993"} {
			body := `{"type":"test","source":"api",` + fmt.Sprintf(field, id) + `}`
			rec := post(t, h, "application/json", body)
			if rec.Code != http.StatusOK {
				t.Fatalf("status=%d body=%s", rec.Code, rec.Body.String())
			}
			var resp runtime.Response
			if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil {
				t.Fatal(err)
			}
			if resp.Duplicate != (i == 2) {
				t.Fatalf("field %s delivery %d duplicate=%v", field, i, resp.Duplicate)
			}
		}
		if calls.Load() != 2 {
			t.Fatalf("model calls=%d, want 2", calls.Load())
		}
	}
}

func TestEventsHandlerRejectsBadRequests(t *testing.T) {
	tests := []struct {
		name string
		body string
	}{
		{
			name: "missing type",
			body: `{"source":"github"}`,
		},
		{
			name: "missing source",
			body: `{"type":"commit.pushed"}`,
		},
		{
			name: "malformed JSON",
			body: `{"type": "commit.pushed", "source":`,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			h, calls := newTestHandler(t, `{"category":"important","importance":0.95}`)
			rec := post(t, h, "application/json", tt.body)
			if rec.Code != http.StatusBadRequest {
				t.Fatalf("status = %d, want 400 (body: %s)", rec.Code, rec.Body.String())
			}
			if got := rec.Body.String(); !strings.Contains(got, `"error"`) {
				t.Errorf("body = %s, want an {\"error\": ...} envelope", got)
			}
			// Rejection must happen before the pipeline: nothing persisted
			// and, as the cheapest observable proxy, no model call.
			if n := calls.Load(); n != 0 {
				t.Errorf("model called %d times, want 0 (rejected input must not reach the pipeline)", n)
			}
		})
	}
}

func TestEventsHandlerRejectsOversizedBody(t *testing.T) {
	h, calls := newTestHandler(t, `{"category":"important","importance":0.95}`)
	// The body is valid JSON but padded past the 1 MiB ingress bound; the
	// limit must trip before the event is constructed or anything persists.
	pad := strings.Repeat("a", 1<<20+64)
	rec := post(t, h, "application/json", `{"type":"t","source":"s","data":{"pad":"`+pad+`"}}`)
	if rec.Code != http.StatusBadRequest {
		t.Fatalf("status = %d, want 400 for body over the 1 MiB bound", rec.Code)
	}
	if got := rec.Body.String(); !strings.Contains(got, `"error"`) {
		t.Errorf("body = %s, want an {\"error\": ...} envelope", got)
	}
	if n := calls.Load(); n != 0 {
		t.Errorf("model called %d times, want 0 (oversized input must not reach the pipeline)", n)
	}
}

// This test pins the `mrmr inspect` wiring: config → database → one JSON
// object on stdout. The query itself is covered in internal/storage; what
// matters here is that the command reaches the right database and prints
// the durable trace, because that is the only way to answer "why did this
// happen?" once the ingest response is gone.
package main

import (
	"encoding/json"
	"io"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/heath0xff/mrmr/internal/event"
	"github.com/heath0xff/mrmr/internal/storage"
)

// inspectFixture writes a config whose db.path points at a temp database,
// stores one fully-processed event in it, and returns the config path and
// the event id.
func inspectFixture(t *testing.T) (configPath, eventID string) {
	t.Helper()
	dir := t.TempDir()
	dbPath := filepath.Join(dir, "inspect.db")
	configPath = filepath.Join(dir, "mrmr.yaml")
	// db.path is the only field this command reads, but the config must
	// still be a valid one — inspect refuses to guess at a broken runtime
	// definition just because it is only reading.
	yaml := "models:\n" +
		"  m:\n" +
		"    provider: openai-compatible\n" +
		"    base_url: http://localhost:1/v1\n" +
		"    model: mock\n" +
		"db:\n" +
		"  path: " + dbPath + "\n" +
		"interpret:\n" +
		"  model: m\n" +
		"  prompt: classify this event\n" +
		"  schema:\n" +
		"    category:\n" +
		"      type: string\n" +
		"policy:\n" +
		"  - if:\n" +
		"      result.category: incident\n" +
		"    then:\n" +
		"      notify:\n" +
		"        via: stdout\n" +
		"default:\n" +
		"  ignore: true\n"
	if err := os.WriteFile(configPath, []byte(yaml), 0o600); err != nil {
		t.Fatalf("write config: %v", err)
	}

	db, err := storage.Open(dbPath)
	if err != nil {
		t.Fatalf("open storage: %v", err)
	}
	defer db.Close()

	e := event.Event{
		ID: event.NewID("evt_"), Type: "monitor.alert", Source: "monitoring",
		Timestamp: time.Now().UTC(), Data: map[string]any{"message": "service unavailable"},
	}
	if _, err := db.InsertEvent(e); err != nil {
		t.Fatalf("insert event: %v", err)
	}
	dec := event.Decision{
		ID: event.NewID("dec_"), EventID: e.ID, Interpreter: "m", Model: "mock",
		Status: "ok", Result: map[string]any{"category": "incident"},
	}
	if err := db.InsertDecision(dec); err != nil {
		t.Fatalf("insert decision: %v", err)
	}
	if err := db.InsertExecution(event.NewID("exe_"), e.ID, dec.ID, "notify", "stdout", "ok", ""); err != nil {
		t.Fatalf("insert execution: %v", err)
	}
	if err := db.InsertTrace(e.ID, []event.TraceStep{
		{At: time.Now().UTC(), Stage: "receive", Msg: "type=monitor.alert source=monitoring"},
		{At: time.Now().UTC(), Stage: "policy", Msg: "rule 1 → notify"},
	}); err != nil {
		t.Fatalf("insert trace: %v", err)
	}
	return configPath, e.ID
}

// captureStdout runs fn with os.Stdout replaced by a pipe and returns what
// it wrote. inspect prints its result rather than returning it, so the
// output is the contract under test.
func captureStdout(t *testing.T, fn func() error) (string, error) {
	t.Helper()
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatalf("pipe: %v", err)
	}
	saved := os.Stdout
	os.Stdout = w
	// Drain concurrently: a pipe holds ~64 KiB, and an inspection of a long
	// trace would otherwise block the writer forever waiting on a reader
	// that only runs after fn returns.
	done := make(chan []byte, 1)
	go func() {
		out, _ := io.ReadAll(r)
		done <- out
	}()
	fnErr := fn()
	os.Stdout = saved
	w.Close()
	out := <-done
	r.Close()
	return string(out), fnErr
}

func TestInspectPrintsStoredTrace(t *testing.T) {
	configPath, eventID := inspectFixture(t)

	out, err := captureStdout(t, func() error {
		return inspect([]string{eventID, "-config", configPath})
	})
	if err != nil {
		t.Fatalf("inspect: %v", err)
	}

	var got storage.Inspection
	if err := json.Unmarshal([]byte(out), &got); err != nil {
		t.Fatalf("inspect output is not one JSON object: %v\n%s", err, out)
	}
	if got.Event.ID != eventID {
		t.Errorf("event id = %q, want %q", got.Event.ID, eventID)
	}
	if len(got.Decisions) != 1 || got.Decisions[0].Result["category"] != "incident" {
		t.Errorf("decisions = %+v, want the stored decision", got.Decisions)
	}
	if len(got.Executions) != 1 || got.Executions[0].Outcome != "notify" {
		t.Errorf("executions = %+v, want the stored notify execution", got.Executions)
	}
	if len(got.Trace) != 2 || got.Trace[0].Stage != "receive" || got.Trace[1].Stage != "policy" {
		t.Errorf("trace = %+v, want the stored steps in order", got.Trace)
	}
}

func TestInspectRejectsMissingArguments(t *testing.T) {
	if err := inspect(nil); err == nil {
		t.Error("inspect with no event id must fail with usage")
	}
	configPath, _ := inspectFixture(t)
	err := inspect([]string{"evt_missing", "-config", configPath})
	if err == nil || !strings.Contains(err.Error(), "not found") {
		t.Errorf("inspect of an unknown event = %v, want a not-found error", err)
	}
}

