package superhuman

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"net/url"
	"time"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"golang.org/x/oauth2"
)

const (
	endpoint      = "https://mcp.mail.superhuman.com/mcp"
	authHost      = "mcp.auth.mail.superhuman.com"
	tokenEndpoint = "https://" + authHost + "/oauth2/token"
)

// This is deliberately not an arbitrary MCP client: neither configuration nor
// a model may change the resource, OAuth authority, or callable operation.
// Use the official SDK for protocol negotiation, discovery, and PKCE instead
// of maintaining our own implementation of those security-sensitive protocols.
type guardedTransport struct{ base http.RoundTripper }

func (t guardedTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	if !allowedURL(req.URL) {
		return nil, errors.New("Superhuman request outside the allowed HTTPS origins")
	}
	resp, err := t.base.RoundTrip(req)
	if err != nil {
		return nil, safeError("Superhuman HTTPS request", err)
	}
	resp.Body = http.MaxBytesReader(nil, resp.Body, 4<<20)
	return resp, nil
}

func allowedURL(u *url.URL) bool {
	return u != nil && u.Scheme == "https" && u.User == nil && u.Fragment == "" &&
		(u.Host == "mcp.mail.superhuman.com" || u.Host == authHost)
}

func newHTTPClient() *http.Client {
	return &http.Client{
		Timeout:   30 * time.Second,
		Transport: guardedTransport{http.DefaultTransport},
		// No redirects: a token, code, or client secret must never be forwarded
		// to a location chosen in an HTTP response, even within the allowlist.
		CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
	}
}

func safeError(operation string, err error) error {
	for _, known := range []error{context.Canceled, context.DeadlineExceeded, ErrLoginRequired} {
		if errors.Is(err, known) {
			return fmt.Errorf("%s: %w", operation, known)
		}
	}
	// External error strings may echo authorization codes, tokens, or mail.
	// Do not wrap them: even downstream debug logging must not recover them.
	return fmt.Errorf("%s failed; check connectivity or sign in again (remote details suppressed)", operation)
}

// storedAuth never opens a browser or expands scopes. An expired access token
// refreshes via the saved grant; a rejected grant requires explicit login.
type storedAuth struct{ source oauth2.TokenSource }

func (a storedAuth) TokenSource(context.Context) (oauth2.TokenSource, error) { return a.source, nil }
func (a storedAuth) Authorize(_ context.Context, _ *http.Request, resp *http.Response) error {
	resp.Body.Close()
	return ErrLoginRequired
}

func newClient() *mcp.Client {
	return mcp.NewClient(&mcp.Implementation{Name: "mrmr", Version: "dev"}, &mcp.ClientOptions{
		Capabilities:   &mcp.ClientCapabilities{},
		MultiRoundTrip: &mcp.MultiRoundTripOptions{Disabled: true},
		Logger:         slog.New(slog.NewTextHandler(io.Discard, nil)),
	})
}

// Check authenticates without interactive fallback, checks the required tool
// catalog, and counts linked accounts. It never reads messages, changes the
// default account, or exposes account addresses in logs or CLI output.
func Check(ctx context.Context, dir string) (int, error) {
	return check(ctx, dir, newHTTPClient())
}

func check(ctx context.Context, dir string, hc *http.Client) (int, error) {
	store, err := openStore(dir)
	if err != nil {
		return 0, err
	}
	defer store.lock.Close()
	record, err := store.read()
	if err != nil {
		return 0, err
	}
	source := &persistingTokens{ctx: context.WithValue(ctx, oauth2.HTTPClient, hc), store: store, record: *record}
	session, err := newClient().Connect(ctx, &mcp.StreamableClientTransport{
		Endpoint: endpoint, HTTPClient: hc, OAuthHandler: storedAuth{source}, DisableStandaloneSSE: true,
	}, &mcp.ClientSessionOptions{ProtocolVersion: "2025-11-25"})
	if err != nil {
		return 0, safeError("connect to Superhuman", err)
	}
	defer session.Close()
	return checkSession(ctx, session)
}

func checkSession(ctx context.Context, session *mcp.ClientSession) (int, error) {
	wanted := map[string]bool{"list_accounts": false, "list_threads": false, "get_thread": false, "get_message": false}
	params := &mcp.ListToolsParams{}
	// Catalog pagination is bounded too. A server can't keep the CLI alive by
	// returning an endless cursor chain; no tool has been invoked at this point.
	for page := 0; ; page++ {
		if page == 10 {
			return 0, errors.New("Superhuman tool catalog exceeded 10 pages")
		}
		result, err := session.ListTools(ctx, params)
		if err != nil {
			return 0, safeError("list Superhuman tools", err)
		}
		for _, tool := range result.Tools {
			if _, ok := wanted[tool.Name]; ok {
				wanted[tool.Name] = true
			}
		}
		if result.NextCursor == "" {
			break
		}
		if result.NextCursor == params.Cursor {
			return 0, errors.New("Superhuman tool catalog repeated a cursor")
		}
		params.Cursor = result.NextCursor
	}
	for name, present := range wanted {
		if !present {
			return 0, fmt.Errorf("Superhuman is missing required read tool %s", name)
		}
	}
	// Fixed name and fixed arguments are the authority boundary. Server tool
	// annotations are hints, not permission; write tools are never dispatched.
	result, err := session.CallTool(ctx, &mcp.CallToolParams{Name: "list_accounts", Arguments: map[string]any{}})
	if err != nil {
		return 0, safeError("list Superhuman accounts", err)
	}
	if result.IsError {
		return 0, errors.New("Superhuman rejected account listing")
	}
	var accounts struct {
		Accounts []struct {
			Email string `json:"accountEmail"`
		} `json:"accounts"`
	}
	// Prefer the typed payload. Older servers may only return JSON text; never
	// interpret free-form prose or fetch a URL from a tool result to recover it.
	var data []byte
	if result.StructuredContent != nil {
		data, err = json.Marshal(result.StructuredContent)
	} else if len(result.Content) == 1 {
		if text, ok := result.Content[0].(*mcp.TextContent); ok {
			data = []byte(text.Text)
		}
	}
	if err != nil || json.Unmarshal(data, &accounts) != nil || len(accounts.Accounts) == 0 {
		return 0, errors.New("Superhuman returned no usable linked accounts")
	}
	seen := make(map[string]bool)
	for _, account := range accounts.Accounts {
		if account.Email == "" || seen[account.Email] {
			return 0, errors.New("invalid Superhuman linked-account response")
		}
		seen[account.Email] = true
	}
	return len(accounts.Accounts), nil
}

package superhuman

import (
	"context"
	"crypto/subtle"
	"errors"
	"fmt"
	"net"
	"net/http"
	"net/url"
	"strconv"
	"time"

	"github.com/modelcontextprotocol/go-sdk/auth"
	"github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/modelcontextprotocol/go-sdk/oauthex"
	"golang.org/x/oauth2"
)

// Login is the only interactive path. It creates an independent mrmr grant
// and never calls a mail tool. Only a successfully exchanged, refreshable grant
// replaces old credentials; it is saved even if later MCP initialization fails.
// showURL is a local human prompt, not a logger: authorization links should not
// be put into persistent service logs or shared with another person.
func Login(ctx context.Context, dir string, port int, showURL func(string) error) error {
	return login(ctx, dir, port, showURL, newHTTPClient())
}

func login(ctx context.Context, dir string, port int, showURL func(string) error, hc *http.Client) error {
	if port < 0 || port > 65535 || showURL == nil {
		return errors.New("invalid login callback configuration")
	}
	ctx, cancel := context.WithTimeout(ctx, 5*time.Minute)
	defer cancel()
	store, err := openStore(dir)
	if err != nil {
		return err
	}
	defer store.lock.Close()
	listener, err := net.Listen("tcp4", net.JoinHostPort("127.0.0.1", strconv.Itoa(port)))
	if err != nil {
		return errors.New("cannot bind OAuth callback on loopback; choose another callback port")
	}
	defer listener.Close()
	redirect := "http://" + listener.Addr().String() + "/callback"
	saved := false
	handler, err := auth.NewAuthorizationCodeHandler(&auth.AuthorizationCodeHandlerConfig{
		Client: hc, RedirectURL: redirect, RequestRefreshToken: true,
		// Accept a matching issuer even when discovery omits its support flag.
		// The SDK still rejects any mismatched issuer (RFC 9207).
		AcceptUnadvertisedIss: true,
		// Identity scopes are not a server-side read-only mail grant. Our fixed
		// tool calls enforce read-only behavior regardless of the consent scope.
		ScopeFilter: func([]string) []string { return []string{"openid", "email", "profile"} },
		DynamicClientRegistrationConfig: &auth.DynamicClientRegistrationConfig{
			Metadata: &oauthex.ClientRegistrationMetadata{
				ClientName: "mrmr", RedirectURIs: []string{redirect},
				GrantTypes:    []string{"authorization_code", "refresh_token"},
				ResponseTypes: []string{"code"}, TokenEndpointAuthMethod: "none",
			},
		},
		AuthorizationCodeFetcher: func(ctx context.Context, args *auth.AuthorizationArgs) (*auth.AuthorizationResult, error) {
			return receiveCode(ctx, listener, args.URL, showURL)
		},
		NewTokenSource: func(ctx context.Context, config *oauth2.Config, token *oauth2.Token) (oauth2.TokenSource, error) {
			record := credentialRecord{Version: 1, Resource: endpoint, Config: *config, Token: *token}
			if err := store.write(&record); err != nil {
				return nil, err
			}
			saved = true
			return &persistingTokens{ctx: ctx, store: store, record: record}, nil
		},
	})
	if err != nil {
		return safeError("prepare Superhuman authorization", err)
	}
	session, err := newClient().Connect(ctx, &mcp.StreamableClientTransport{
		Endpoint: endpoint, HTTPClient: hc, OAuthHandler: handler, DisableStandaloneSSE: true,
	}, &mcp.ClientSessionOptions{ProtocolVersion: "2025-11-25"})
	if err != nil {
		return safeError("Superhuman login", err)
	}
	defer session.Close()
	if !saved {
		return errors.New("Superhuman did not issue a refreshable OAuth grant")
	}
	return nil
}

func receiveCode(ctx context.Context, listener net.Listener, authURL string, showURL func(string) error) (*auth.AuthorizationResult, error) {
	u, err := url.Parse(authURL)
	if err != nil || !allowedURL(u) || u.Host != authHost || u.Query().Get("state") == "" {
		return nil, errors.New("unexpected Superhuman authorization URL")
	}
	results := make(chan *auth.AuthorizationResult, 1)
	mux := http.NewServeMux()
	mux.HandleFunc("GET /callback", callbackHandler(listener.Addr().String(), u.Query().Get("state"), results))
	server := &http.Server{Handler: mux, ReadHeaderTimeout: 5 * time.Second, ReadTimeout: 5 * time.Second, WriteTimeout: 5 * time.Second, MaxHeaderBytes: 8192}
	serveError := make(chan error, 1)
	stopped := make(chan struct{})
	go func() {
		defer close(stopped)
		serveError <- server.Serve(listener)
	}()
	// The listener, server, and goroutine belong to this attempt. Cancellation,
	// denied consent, and an abandoned browser all close and join the server.
	defer func() { server.Close(); <-stopped }()
	if err := showURL(authURL); err != nil {
		return nil, errors.New("cannot display the Superhuman sign-in URL")
	}
	select {
	case result := <-results:
		if result.Code == "" {
			return nil, errors.New("Superhuman authorization was denied")
		}
		// The SDK verifies PKCE, state again, and the response issuer before
		// exchanging this code. No raw query or remote error is ever logged.
		return result, nil
	case <-serveError:
		return nil, errors.New("OAuth callback server stopped unexpectedly")
	case <-ctx.Done():
		return nil, ctx.Err()
	}
}

func callbackHandler(host, state string, results chan<- *auth.AuthorizationResult) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Cache-Control", "no-store")
		w.Header().Set("Referrer-Policy", "no-referrer")
		w.Header().Set("Content-Security-Policy", "default-src 'none'")
		q := r.URL.Query()
		// Reject stray local requests without consuming the real callback. The
		// state must match before either an error or a code ends this attempt.
		if r.Host != host || len(q["state"]) != 1 || subtle.ConstantTimeCompare([]byte(q.Get("state")), []byte(state)) != 1 ||
			len(q["code"]) > 1 || len(q["iss"]) > 1 || len(q["error"]) > 1 ||
			(q.Get("code") == "" && q.Get("error") == "") || (q.Get("code") != "" && q.Get("error") != "") {
			http.Error(w, "Invalid authorization callback.", http.StatusBadRequest)
			return
		}
		result := &auth.AuthorizationResult{Code: q.Get("code"), State: q.Get("state"), Iss: q.Get("iss")}
		select {
		case results <- result:
			fmt.Fprintln(w, "Authorization response received. Return to the mrmr terminal to check the result.")
		default:
			http.Error(w, "Authorization response already received.", http.StatusConflict)
		}
	}
}

// Package superhuman owns the one Superhuman connection. Credentials belong to
// mrmr, not an agent harness, and never enter event storage or flow definitions.
package superhuman

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"sync"

	"github.com/gofrs/flock"
	"golang.org/x/oauth2"
)

var ErrLoginRequired = errors.New("Superhuman sign-in required: run mrmr auth login superhuman")

// DefaultDir keeps credentials outside the repository and the event database.
// An explicit state directory allows a service account to own its own grant.
func DefaultDir() (string, error) {
	dir, err := os.UserConfigDir()
	if err != nil {
		return "", fmt.Errorf("locate user config directory: %w", err)
	}
	return filepath.Join(dir, "mrmr", "superhuman"), nil
}

type credentialRecord struct {
	Version  int           `json:"version"`
	Resource string        `json:"resource"`
	Config   oauth2.Config `json:"oauth"`
	Token    oauth2.Token  `json:"token"`
}

type credentialStore struct {
	dir  string
	lock *flock.Flock
}

func openStore(dir string) (*credentialStore, error) {
	if !filepath.IsAbs(dir) {
		return nil, errors.New("credential directory must be absolute")
	}
	if err := os.MkdirAll(dir, 0700); err != nil {
		return nil, errors.New("cannot create credential directory")
	}
	info, err := os.Lstat(dir)
	if err != nil || !info.IsDir() || info.Mode().Perm()&0077 != 0 {
		return nil, errors.New("credential directory must be a real, private directory (mode 0700)")
	}
	lockPath := filepath.Join(dir, "credentials.lock")
	if err := privateFile(lockPath); err != nil && !errors.Is(err, os.ErrNotExist) {
		return nil, err
	}
	lock := flock.New(lockPath, flock.SetPermissions(0600))
	ok, err := lock.TryLock()
	if err != nil || !ok {
		lock.Close()
		return nil, errors.New("Superhuman credentials are in use or cannot be locked; stop the other mrmr connection first")
	}
	// ponytail: one process owns the grant for its connection lifetime. Use
	// per-refresh locking only if concurrent clients become a real requirement.
	// OS locks release on process death, unlike a stale pid/lock directory.
	return &credentialStore{dir: dir, lock: lock}, nil
}

func privateFile(path string) error {
	info, err := os.Lstat(path)
	if err != nil {
		return err
	}
	if !info.Mode().IsRegular() || info.Mode().Perm()&0077 != 0 {
		return errors.New("credential files must be regular private files (mode 0600), not symlinks")
	}
	return nil
}

func (s *credentialStore) read() (*credentialRecord, error) {
	path := filepath.Join(s.dir, "credentials.json")
	if err := privateFile(path); err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, ErrLoginRequired
		}
		return nil, errors.New("cannot read private Superhuman credentials")
	}
	f, err := os.Open(path)
	if err != nil {
		return nil, errors.New("cannot open Superhuman credentials")
	}
	defer f.Close()
	if info, err := f.Stat(); err != nil || info.Size() > 1<<20 {
		return nil, errors.New("Superhuman credential file exceeds its size bound or cannot be inspected")
	}
	var record credentialRecord
	decoder := json.NewDecoder(io.LimitReader(f, 1<<20))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&record); err != nil {
		return nil, errors.New("invalid Superhuman credential file")
	}
	if err := decoder.Decode(new(any)); err != io.EOF {
		return nil, errors.New("invalid Superhuman credential file suffix")
	}
	if err := record.validate(); err != nil {
		return nil, err
	}
	return &record, nil
}

func (r *credentialRecord) validate() error {
	// A tampered or accidentally copied state file must not redirect a refresh
	// token to another service. Login metadata is also constrained by the client.
	if r.Version != 1 || r.Resource != endpoint || r.Config.ClientID == "" ||
		r.Config.Endpoint.TokenURL != tokenEndpoint || r.Token.AccessToken == "" ||
		r.Token.RefreshToken == "" || r.Token.Expiry.IsZero() || !strings.EqualFold(r.Token.TokenType, "Bearer") {
		return errors.New("invalid or non-refreshable Superhuman credentials; sign in again")
	}
	return nil
}

func (s *credentialStore) write(record *credentialRecord) error {
	if err := record.validate(); err != nil {
		return err
	}
	data, err := json.Marshal(record)
	if err != nil {
		return errors.New("cannot encode Superhuman credentials")
	}
	// Rename within the same private directory preserves the previous grant on
	// pre-rename failures. Sync before returning a rotated token to any caller.
	f, err := os.CreateTemp(s.dir, ".credentials-*")
	if err != nil {
		return errors.New("cannot create private credential file")
	}
	defer os.Remove(f.Name())
	defer f.Close()
	if _, err = f.Write(data); err == nil {
		err = f.Sync()
	}
	if err == nil {
		err = f.Close()
	}
	if err == nil {
		err = os.Rename(f.Name(), filepath.Join(s.dir, "credentials.json"))
	}
	if err != nil {
		return errors.New("cannot persist Superhuman credentials")
	}
	dir, err := os.Open(s.dir)
	if err != nil {
		return errors.New("cannot sync credential directory")
	}
	defer dir.Close()
	if err := dir.Sync(); err != nil {
		return errors.New("cannot sync credential directory")
	}
	return nil
}

// persistingTokens serializes refreshes within this process; the store's lock
// serializes processes. A rotated refresh token is saved before it is used.
// If saving fails, retain it in memory and retry the save, never re-use the old
// refresh token. A crash between remote rotation and local persistence still
// requires a new sign-in; no local transaction can eliminate that window.
type persistingTokens struct {
	mu     sync.Mutex
	ctx    context.Context
	store  *credentialStore
	record credentialRecord
	dirty  bool
}

func (s *persistingTokens) Token() (*oauth2.Token, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.dirty {
		if err := s.store.write(&s.record); err != nil {
			return nil, err
		}
		s.dirty = false
	}
	token, err := s.record.Config.TokenSource(s.ctx, &s.record.Token).Token()
	if err != nil {
		// oauth2.RetrieveError includes the remote body, which may echo tokens.
		return nil, safeError("refresh Superhuman credentials", err)
	}
	old := &s.record.Token
	if token.AccessToken != old.AccessToken || token.RefreshToken != old.RefreshToken || !token.Expiry.Equal(old.Expiry) {
		s.record.Token = *token
		s.dirty = true
		if err := s.store.write(&s.record); err != nil {
			return nil, err
		}
		s.dirty = false
	}
	copy := *token
	return &copy, nil
}

package superhuman

import (
	"context"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// The production origin guard still runs in these tests. Only the underlying
// dial destination is replaced: all OAuth and MCP traffic terminates at one
// local fixture, with the SDK executing its real discovery/PKCE/refresh flow.
type roundTripFunc func(*http.Request) (*http.Response, error)

func (f roundTripFunc) RoundTrip(r *http.Request) (*http.Response, error) { return f(r) }

type authFixture struct {
	mu                         sync.Mutex
	access, refresh, challenge string
	refreshes, registrations   int
	calls                      []string
	rejectRefresh              bool
	hc                         *http.Client
}

func newAuthFixture(t *testing.T) *authFixture {
	t.Helper()
	f := &authFixture{access: "test-access-original", refresh: "test-refresh-original"}
	server := mcp.NewServer(&mcp.Implementation{Name: "fixture", Version: "1"}, nil)
	for _, name := range []string{"list_accounts", "list_threads", "get_thread", "get_message", "send_draft"} {
		server.AddTool(&mcp.Tool{Name: name, InputSchema: map[string]any{"type": "object"}}, func(_ context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
			f.mu.Lock()
			defer f.mu.Unlock()
			f.calls = append(f.calls, req.Params.Name)
			return &mcp.CallToolResult{Content: []mcp.Content{&mcp.TextContent{Text: `{"accounts":[{"accountEmail":"test@example.invalid","isPrimary":true,"addedAt":"2026-01-01T00:00:00Z"}]}`}}}, nil
		})
	}
	mcpHandler := mcp.NewStreamableHTTPHandler(func(*http.Request) *mcp.Server { return server }, &mcp.StreamableHTTPOptions{Stateless: true, JSONResponse: true})
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		switch r.URL.Path {
		case "/.well-known/oauth-protected-resource/mcp":
			fmt.Fprintf(w, `{"resource":%q,"authorization_servers":["https://%s"]}`, endpoint, authHost)
		case "/.well-known/oauth-authorization-server":
			fmt.Fprintf(w, `{"issuer":"https://%s","authorization_endpoint":"https://%s/oauth2/authorize","token_endpoint":%q,"registration_endpoint":"https://%s/oauth2/register","scopes_supported":["openid","email","profile","offline_access"],"code_challenge_methods_supported":["S256"],"response_types_supported":["code"],"token_endpoint_auth_methods_supported":["none"]}`, authHost, authHost, tokenEndpoint, authHost)
		case "/oauth2/register":
			f.mu.Lock()
			f.registrations++
			f.mu.Unlock()
			var metadata map[string]any
			if json.NewDecoder(r.Body).Decode(&metadata) != nil || metadata["client_name"] != "mrmr" {
				t.Error("invalid client registration")
			}
			fmt.Fprint(w, `{"client_id":"test-client","token_endpoint_auth_method":"none"}`)
		case "/oauth2/token":
			f.mu.Lock()
			defer f.mu.Unlock()
			if err := r.ParseForm(); err != nil {
				t.Error(err)
			}
			switch r.Form.Get("grant_type") {
			case "authorization_code":
				digest := sha256.Sum256([]byte(r.Form.Get("code_verifier")))
				if r.Form.Get("code") != "test-code" || r.Form.Get("resource") != endpoint || base64.RawURLEncoding.EncodeToString(digest[:]) != f.challenge {
					t.Error("invalid code/PKCE/resource exchange")
				}
			case "refresh_token":
				f.refreshes++
				if r.Form.Get("refresh_token") != f.refresh {
					t.Error("reused an obsolete refresh token")
				}
				if f.rejectRefresh {
					w.WriteHeader(http.StatusBadRequest)
					fmt.Fprint(w, `{"error":"invalid_grant","error_description":"test-access-original test-refresh-original PRIVATE-MAIL"}`)
					return
				}
				f.access = fmt.Sprintf("test-access-%d", f.refreshes)
				f.refresh = fmt.Sprintf("test-refresh-%d", f.refreshes)
			default:
				t.Error("unexpected grant type")
			}
			fmt.Fprintf(w, `{"access_token":%q,"refresh_token":%q,"token_type":"Bearer","expires_in":3600}`, f.access, f.refresh)
		case "/mcp":
			f.mu.Lock()
			valid := r.Header.Get("Authorization") == "Bearer "+f.access
			f.mu.Unlock()
			if !valid {
				w.Header().Set("WWW-Authenticate", `Bearer resource_metadata="https://mcp.mail.superhuman.com/.well-known/oauth-protected-resource/mcp"`)
				w.WriteHeader(http.StatusUnauthorized)
				return
			}
			mcpHandler.ServeHTTP(w, r)
		default:
			http.NotFound(w, r)
		}
	}))
	t.Cleanup(srv.Close)
	target, _ := url.Parse(srv.URL)
	f.hc = newHTTPClient()
	f.hc.Transport = guardedTransport{roundTripFunc(func(r *http.Request) (*http.Response, error) {
		copy := r.Clone(r.Context())
		copy.URL.Scheme, copy.URL.Host = target.Scheme, target.Host
		copy.Host = target.Host
		return srv.Client().Transport.RoundTrip(copy)
	})}
	return f
}

func (f *authFixture) browser(t *testing.T) func(string) error {
	t.Helper()
	return func(link string) error {
		u, err := url.Parse(link)
		if err != nil {
			return err
		}
		q := u.Query()
		if u.Host != authHost || q.Get("code_challenge_method") != "S256" || !strings.Contains(q.Get("scope"), "offline_access") {
			t.Error("missing PKCE or offline access")
		}
		f.mu.Lock()
		f.challenge = q.Get("code_challenge")
		f.mu.Unlock()
		callback, _ := url.Parse(q.Get("redirect_uri"))
		if callback.Hostname() != "127.0.0.1" {
			return fmt.Errorf("callback is not loopback")
		}
		callback.RawQuery = url.Values{"state": {q.Get("state")}, "code": {"test-code"}, "iss": {"https://" + authHost}}.Encode()
		resp, err := http.Get(callback.String())
		if err != nil {
			return err
		}
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			return fmt.Errorf("callback status %d", resp.StatusCode)
		}
		return nil
	}
}

func TestLoginCheckRefreshAndRestart(t *testing.T) {
	f := newAuthFixture(t)
	dir := filepath.Join(t.TempDir(), "credentials")
	if err := login(t.Context(), dir, 0, f.browser(t), f.hc); err != nil {
		t.Fatal(err)
	}
	f.mu.Lock()
	if len(f.calls) != 0 {
		t.Error("login invoked mail tools")
	}
	f.mu.Unlock()
	for i := 0; i < 3; i++ {
		// Each check opens a new store and session, as after a process restart.
		// Expire the saved access token to force rotation on subsequent checks.
		if i > 0 {
			s, err := openStore(dir)
			if err != nil {
				t.Fatal(err)
			}
			r, err := s.read()
			if err != nil {
				t.Fatal(err)
			}
			r.Token.Expiry = time.Now().Add(-time.Hour)
			if err := s.write(r); err != nil {
				t.Fatal(err)
			}
			s.lock.Close()
		}
		count, err := check(t.Context(), dir, f.hc)
		if err != nil || count != 1 {
			t.Fatalf("check %d: count=%d err=%v", i, count, err)
		}
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.refreshes != 2 || f.registrations != 1 || strings.Join(f.calls, ",") != "list_accounts,list_accounts,list_accounts" {
		t.Fatalf("refreshes=%d registrations=%d calls=%v", f.refreshes, f.registrations, f.calls)
	}
	info, err := os.Stat(filepath.Join(dir, "credentials.json"))
	if err != nil || info.Mode().Perm() != 0600 {
		t.Fatalf("credential permissions: %v %v", info, err)
	}
}

func TestRefreshErrorDoesNotLeakOrRegisterAgain(t *testing.T) {
	f := newAuthFixture(t)
	dir := filepath.Join(t.TempDir(), "credentials")
	if err := login(t.Context(), dir, 0, f.browser(t), f.hc); err != nil {
		t.Fatal(err)
	}
	s, _ := openStore(dir)
	r, _ := s.read()
	r.Token.Expiry = time.Now().Add(-time.Hour)
	if err := s.write(r); err != nil {
		t.Fatal(err)
	}
	s.lock.Close()
	f.mu.Lock()
	f.rejectRefresh = true
	f.mu.Unlock()
	_, err := check(t.Context(), dir, f.hc)
	if err == nil {
		t.Fatal("refresh failure accepted")
	}
	for _, secret := range []string{"test-access-original", "test-refresh-original", "PRIVATE-MAIL"} {
		if strings.Contains(err.Error(), secret) {
			t.Fatal("remote error leaked")
		}
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.registrations != 1 || len(f.calls) != 0 {
		t.Fatal("unattended check expanded authority or called tools after refresh failure")
	}
}

func TestOriginGuardAndResponseBound(t *testing.T) {
	calls := 0
	transport := guardedTransport{roundTripFunc(func(r *http.Request) (*http.Response, error) {
		calls++
		return &http.Response{StatusCode: 200, Header: make(http.Header), Body: io.NopCloser(strings.NewReader(strings.Repeat("x", (4<<20)+1)))}, nil
	})}
	for _, target := range []string{"http://mcp.mail.superhuman.com/mcp", "https://evil.invalid/mcp", "https://mcp.mail.superhuman.com:444/mcp", "https://user@mcp.mail.superhuman.com/mcp", "https://mcp.mail.superhuman.com.evil.invalid/mcp"} {
		r, _ := http.NewRequest("GET", target, nil)
		if _, err := transport.RoundTrip(r); err == nil {
			t.Errorf("allowed %s", target)
		}
	}
	if calls != 0 {
		t.Fatal("untrusted origin reached network")
	}
	r, _ := http.NewRequest("GET", endpoint, nil)
	resp, err := transport.RoundTrip(r)
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	if _, err := io.ReadAll(resp.Body); err == nil {
		t.Fatal("oversized response accepted")
	}
	if err := newHTTPClient().CheckRedirect(r, nil); err != http.ErrUseLastResponse {
		t.Fatal("redirects must not forward credentials")
	}
}

