 raw, err := io.ReadAll(io.LimitReader(resp.Body, (1<<20)+1))
 if err != nil || len(raw) > 1<<20 { return nil, fmt.Errorf("agent completion unreadable or exceeds 1 MiB") }
 var result Completion
 dec := json.NewDecoder(bytes.NewReader(raw))
 dec.UseNumber()
 dec.DisallowUnknownFields()
 if err := dec.Decode(&result); err != nil { return nil, fmt.Errorf("invalid agent completion object") }
 if err := dec.Decode(new(any)); err != io.EOF { return nil, fmt.Errorf("expected one agent completion object") }
 switch result.Status {
 case "completed", "failed", "cancelled":
 default: return nil, fmt.Errorf("agent completion status must be completed, failed, or cancelled")
 }
 if result.StartedAt != nil && result.CompletedAt != nil && result.CompletedAt.Before(*result.StartedAt) {
  return nil, fmt.Errorf("agent completion precedes start")
 }
 return &result, nil
}

