func delegateRuntime(t *testing.T, endpoint string) *Runtime {
 t.Helper()
 url, _ := modelServer(t, `{"category":"important","importance":0.95}`)
 rt := newTestRuntime(t, url)
 rt.Agents = map[string]agent.Config{"homelab": {Endpoint:endpoint, ReadOnly:true, Capabilities:[]string{"journal.read"}, Model:"worker"}}
 rt.Models = map[string]model.Config{"worker": {Role:"agent", Provider:"openai-compatible", BaseURL:"http://worker.invalid/v1", Model:"small-worker"}}
 rt.Policy = policy.Policy{Rules: []policy.Rule{{If: map[string]any{"event.depth":0}, Then: policy.Then{Delegate:&policy.Delegate{Agent:"homelab", Prompt:"Investigate, do not mutate.", EmitCompletion:true, CompletionEventType:"agent.investigation.completed"}}}}, Default:policy.Then{Ignore:true}}
 return rt
}

func TestDelegateCompletionReentersWithDurableLineage(t *testing.T) {
 var request agent.Request
 var rt *Runtime
 srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
  if err := json.NewDecoder(r.Body).Decode(&request); err != nil { t.Error(err) }
  var status string
  if err := rt.DB.QueryRow(`SELECT status FROM executions WHERE id = ?`, request.Delegation.ExecutionID).Scan(&status); err != nil || status != "pending" { t.Errorf("intent not durable before worker: %s %v", status, err) }
  fmt.Fprint(w, `{"status":"completed","summary":"Service recovered","evidence":[{"record_id":9007199254740993}],"recommended_action":"no_action"}`)
 }))
 defer srv.Close()
 rt = delegateRuntime(t, srv.URL)
 followURL, followCalls := modelServer(t, `{"category":"no_action"}`)
 rt.Models["judge"] = model.Config{Role:"decision", Provider:"openai-compatible", BaseURL:followURL, Model:"small-judge"}
 rt.InterpretByType = map[string]model.Interpretation{"agent.investigation.completed": {Model:"judge", Questions:model.Questions{"category": {Type:"choice", Instructions:"Classify the evidence", Criteria:map[string]string{"no_action":"Resolved", "notify":"Attention needed"}}}}}
 parent := testEvent("completion")
 resp, err := rt.Ingest(context.Background(), parent)
 if err != nil { t.Fatal(err) }
 if resp.Outcome != "delegate" || followCalls.Load() != 1 { t.Fatalf("follow-up did not run: %+v", resp) }
 if request.Event.ID != parent.ID || request.Event.Subject != parent.Subject || !request.ReadOnly || len(request.Capabilities) != 1 || request.Worker.Model != "small-worker" || request.Depth != 0 || request.Prompt == "" { t.Fatalf("request contract: %+v", request) }
 ins, err := rt.DB.Inspect(parent.ID)
 if err != nil { t.Fatal(err) }
 if len(ins.ChildEventIDs) != 1 || len(ins.Executions) != 1 || ins.Executions[0].Status != "ok" { t.Fatalf("parent: %+v", ins) }
 child, err := rt.DB.Inspect(ins.ChildEventIDs[0])
 if err != nil { t.Fatal(err) }
 p := child.Event.Provenance
 if child.Event.Depth != 1 || child.Event.Subject != parent.Subject || p.ParentEventID != parent.ID || p.OriginEventID != parent.ID || p.DecisionID != resp.Decision.ID || p.ExecutionID != ins.Executions[0].ID || p.Agent != "homelab" || p.PolicyRule != "rule:1" || p.PolicyHash != rt.Policy.Version() { t.Fatalf("lineage: %+v", child.Event) }
 if child.Decisions[0].Interpreter != "judge" || child.Executions[0].Outcome != "ignore" { t.Fatalf("follow-up: %+v", child) }
 result := child.Event.Data["result"].(map[string]any)
 if result["status"] != "completed" || result["evidence"].([]any)[0].(map[string]any)["record_id"] != json.Number("9007199254740993") { t.Fatalf("completion data: %+v", result) }
 if _, err := rt.DB.LabelEvent(child.Event.ID, "no_action", false, "ignore"); err != nil { t.Fatal(err) }
 exported, err := rt.DB.LabeledEvents()
 if err != nil || len(exported) != 1 || exported[0].Event.Depth != 1 || exported[0].Event.Provenance.ExecutionID != p.ExecutionID { t.Fatalf("export lost lineage: %+v %v", exported, err) }
 replay := child.Event; replay.ID = event.NewID("evt_")
 dup, err := rt.Ingest(context.Background(), replay)
 if err != nil || !dup.Duplicate || followCalls.Load() != 1 { t.Fatal("completion replay spent inference") }
}

