func TestLineageMigrationIsTransactional(t *testing.T) {
 db:=openTestDB(t)
 // Apply to a deliberately conflicting shape: the depth ALTER succeeds,
 // then provenance fails. Rollback must remove depth and preserve old rows.
 if _,err:=db.Exec(`DROP INDEX idx_events_parent; ALTER TABLE events DROP COLUMN depth;
 DELETE FROM schema_migrations WHERE version = 7;`);err!=nil {t.Fatal(err)}
 if err:=db.migrate();err==nil {t.Fatal("conflicting migration should fail")}
 var count int
 if err:=db.QueryRow(`SELECT count(*) FROM pragma_table_info('events') WHERE name='depth'`).Scan(&count);err!=nil {t.Fatal(err)}
 if count!=0 {t.Fatal("failed migration left a partially altered schema")}
}

