// Select before inference so mixed datasets can grade one model role contract
// without spending calls or changing denominators for the other contract.
func selectEvalMode(cfg *config.Config, cases []evalCase, mode string) ([]evalCase, error) {
	if mode != "all" && mode != "decision" && mode != "structured-output" { return nil, fmt.Errorf("eval mode must be all, decision, or structured-output") }
	var selected []evalCase
	for _, tc := range cases {
		decision := len(cfg.InterpreterFor(tc.Event.Type).Questions) != 0
		if mode == "all" || (mode == "decision" && decision) || (mode == "structured-output" && !decision) { selected = append(selected, tc) }
	}
	if len(selected) == 0 { return nil, fmt.Errorf("no dataset events match eval mode %q", mode) }
	return selected, nil
}

