	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/decisions/v1/systemone" || r.Header.Get("Authorization") != "Bearer synthetic-key" { t.Error("incorrect hosted System One request") }
		response := typeSafeResponse(); response["model"] = "d1:free"
		json.NewEncoder(w).Encode(response)
	}))
	defer srv.Close()
	p, err := NewDecisionProvider(Config{Role:"decision", Provider:"liquid-d1", BaseURL:srv.URL+"/decisions/v1/", APIKeyEnv:"TEST_LIQUID_KEY", Model:"d1:free"})
	if err != nil { t.Fatal(err) }
	j, err := p.Decide(context.Background(), testTypeSafeQuestions(), []byte(`{}`))
	if err != nil || j.Model != "d1:free" { t.Fatalf("hosted judgment=%+v err=%v", j, err) }
}

