#!/usr/bin/env python3
"""Bound startup on the expected API identity, not only a running process."""
import json
import os
import sys
import time
import urllib.error
import urllib.request

mode = sys.argv[1]
assert mode in {"nemotron", "d1"}
url = "http://127.0.0.1:8000/v1/models" if mode == "nemotron" else "http://100.99.177.33:8091/health"
expected = "nemotron-3.5-super-vl" if mode == "nemotron" else "LiquidAI/d1-3B@da1fe36a861f24690f27f622dca1d8688503d113:cuda-bf16"
headers = {} if mode == "nemotron" else {"Authorization": "Bearer " + os.environ["MRMR_D1_API_KEY"]}
http = urllib.request.build_opener(urllib.request.ProxyHandler({}))
deadline = time.monotonic() + 1080
while time.monotonic() < deadline:
    try:
        with http.open(urllib.request.Request(url, headers=headers), timeout=5) as response:
            value = json.load(response)
        identities = [m["id"] for m in value["data"]] if mode == "nemotron" else [value["model"]]
        if expected not in identities:
            raise SystemExit("Unexpected model identity; refusing activation")
        print(mode + " API ready", flush=True)
        break
    except urllib.error.HTTPError as error:
        if error.code in (401, 403):
            raise SystemExit("Model authentication failed; refusing activation")
    except (OSError, urllib.error.URLError):
        pass
    time.sleep(5)
else:
    raise SystemExit("Model startup deadline exceeded")

