import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

// Local OpenAI-compatible providers whose model lists are discovered live via
// /v1/models. Models are fetched through `refreshModels`, which pi invokes on
// every model refresh (including each `/model` open), so additions/removals on
// the host are picked up without a restart. models.json supplies the startup
// catalog; an unreachable host leaves it (or this process's last live list) intact.
const ENDPOINTS = [
	{
		provider: "deepthought-vllm",
		name: "DGX Spark (vLLM)",
		baseUrl: "http://deepthought:8000/v1",
		apiKey: "vllm",
	},
	{
		provider: "omlx",
		name: "MacBook (omlx)",
		baseUrl: "http://localhost:42069/v1",
		apiKey: "1234",
	},
] as const;

interface ModelsResponse {
	data: Array<{
		id: string;
		max_model_len?: number | null; // vllm / omlx
	}>;
}

export default async function (pi: ExtensionAPI) {
	for (const ep of ENDPOINTS) {
		pi.registerProvider(ep.provider, {
			name: ep.name,
			baseUrl: ep.baseUrl,
			apiKey: ep.apiKey,
			api: "openai-completions",
			async refreshModels({ signal, allowNetwork }) {
				// Startup uses models.json without waiting for either host.
				if (!allowNetwork || signal?.aborted) return;
				// ponytail: 8s per-host deadline; model-selector wraps refresh in
				// 15s, so an unreachable host can't stall the whole /model open.
				const timeout = AbortSignal.any([signal, AbortSignal.timeout(8000)]);
				let res: Response;
				try {
					res = await fetch(`${ep.baseUrl}/models`, {
						headers: { Authorization: `Bearer ${ep.apiKey}` },
						signal: timeout,
					});
				} catch {
					return; // host offline or unreachable — keep cached models
				}
				if (!res.ok) return;
				const payload = (await res.json()) as ModelsResponse;
				if (!payload.data?.length) return;
				return payload.data.map((m) => ({
					id: m.id,
					name: m.id,
					reasoning: false,
					input: ["text"],
					cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
					contextWindow: m.max_model_len ?? 128000,
					maxTokens: 16384,
					compat: {
						supportsDeveloperRole: false,
						supportsReasoningEffort: false,
						maxTokensField: "max_tokens",
					},
				}));
			},
		});
	}
}

