const chrome=spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',[
  '--headless=new','--remote-debugging-port=0',`--user-data-dir=${profile}`,
  '--no-first-run','--no-default-browser-check','--disable-background-networking',
  '--disable-component-update','--disable-sync','about:blank'
],{stdio:'ignore'});
let ws;let seq=0;const pending=new Map(),errors=[],requests=[];
const delay=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function call(method,params={}){
  const id=++seq;
  return new Promise((resolve,reject)=>{
    const timer=setTimeout(()=>{pending.delete(id);reject(new Error('CDP timeout: '+method));},15000);
    pending.set(id,{resolve:value=>{clearTimeout(timer);resolve(value);},reject});
    ws.send(JSON.stringify({id,method,params}));
  });
}
async function evaluate(expression){const r=await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw Error(r.exceptionDetails.text+': '+r.result.description);return r.result.value;}
const results=[];
async function test(name,expression){try{const value=await evaluate(expression);results.push({name,pass:value===true,detail:value===true?undefined:value});}catch(error){results.push({name,pass:false,detail:String(error)});}}
try{
