  await test('Search and empty state',`(()=>{$('service-search').value='NO SUCH SERVICE';$('service-search').dispatchEvent(new Event('input'));const empty=!$('empty-services').hidden;$('service-search').value='d1';$('service-search').dispatchEvent(new Event('input'));return empty&&$('service-rows').children.length===1})()`);
