  await test('Clipboard failure has manual fallback',`(async()=>{Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async()=>{throw Error('denied')}}});$('copy-command').click();await new Promise(r=>setTimeout(r,20));return $('copy-status').textContent.includes('selected')&&document.activeElement===$('command-text')})()`);
  const downloads=path.join(root,'.firecrawl/atlas-downloads');await fs.mkdir(downloads,{recursive:true});
