    await fs.writeFile(path.join(out,name+'-top.png'),Buffer.from(top.data,'base64'));
  }
  await call('Emulation.setEmulatedMedia',{features:[{name:'prefers-reduced-motion',value:'reduce'}]});
  await test('Reduced-motion disables animated highlight',`matchMedia('(prefers-reduced-motion:reduce)').matches&&getComputedStyle($('trace-detail')).animationName==='none'`);
  results.push({name:'No page JavaScript exceptions',pass:errors.length===0,detail:errors});
  results.push({name:'No external requests',pass:requests.every(url=>url.startsWith('file:')||url.startsWith('blob:')),detail:requests.filter(url=>!url.startsWith('file:')&&!url.startsWith('blob:'))});
  await fs.writeFile(path.join(out,'tests.json'),JSON.stringify(results,null,2));
  console.log(JSON.stringify({checks:results.length,failures:results.filter(result=>!result.pass)},null,2));
  if(results.some(result=>!result.pass))process.exitCode=1;
}finally{
  ws?.close();chrome.kill('SIGTERM');await new Promise(resolve=>{const timer=setTimeout(()=>chrome.kill('SIGKILL'),5000);if(chrome.exitCode!==null){clearTimeout(timer);resolve();}else chrome.once('exit',()=>{clearTimeout(timer);resolve();});});
  await fs.rm(profile,{recursive:true,force:true});
}

